// ─── Prehistoric Ages: full section-body translations (es/ru/mk/de/fr) ───────
// Arrays follow the section order of each lesson in lessonsData.ts and are
// merged into BODY_TRANS by contentTranslations.ts. Missing entries fall back
// to the English source, so partial coverage is always safe.
import type { Language } from './translations';

type ContentLang = Exclude<Language, 'en'>;

export const PREHISTORIC_BODY_TRANS: Record<string, Partial<Record<ContentLang, string[]>>> = {
  'prehistoric-01': {
    es: [
      "La historia humana no comienza con reyes o ciudades, sino en las sabanas que se secaban en África, hace unos siete millones de años, cuando un linaje de simios empezó a separarse de los ancestros de los chimpancés. Estos primeros homínidos — criaturas como Sahelanthropus tchadensis, cuyo cráneo se halló en Chad — aún tenían cerebros no mayores que los de un chimpancé, pero la posición del orificio donde la columna se une al cráneo insinúa que ya aprendían a erguirse.\n\n¿Por qué caminar sobre dos piernas? La teoría de la sabana sostuvo largo tiempo que, al ralear los bosques en pradera, erguirse permitía a nuestros ancestros ver por encima de la hierba, cargar comida y crías y viajar con eficacia por campo abierto. El bipedismo también exponía menos cuerpo al sol del mediodía y liberaba por completo las manos. Fuera cual fuese la causa, la marcha erguida — y no un gran cerebro — fue la primera gran adaptación humana, y todo lo demás siguió de esas manos liberadas.",
      "En 1974, en la región de Afar en Etiopía, el paleoantropólogo Donald Johanson desenterró el 40 % de un solo esqueleto que se convertiría en el fósil más famoso del mundo. Apodada \"Lucy\" por la canción de los Beatles que sonaba en el campamento, pertenecía a Australopithecus afarensis y había vivido hace unos 3,2 millones de años. Lucy medía apenas un metro, con un cerebro un tercio del nuestro — pero su pelvis y sus rodillas prueban que caminaba erguida por completo.\n\nUn año antes del hallazgo de Lucy, en Laetoli (Tanzania), Mary Leakey encontró algo aún más conmovedor: un rastro de huellas impresas en ceniza volcánica hace 3,6 millones de años, donde dos o tres australopitecos habían paseado lado a lado por la llanura. Estas huellas — con un arco moderno y el dedo gordo apuntando al frente — son prueba directa e inequívoca de nuestros ancestros caminando sobre dos piernas un millón de años antes de las primeras herramientas de piedra. Lucy y los suyos aún no eran humanos, pero iban inconfundiblemente camino de serlo.",
      "Durante casi todo el siglo XX, la evolución humana se imaginó como una marcha recta — una sola línea de ancestros cada vez más altos e inteligentes. Los fósiles cuentan una historia más enrevesada y rica. En cualquier momento del tiempo profundo, varias especies de homínidos solían compartir el paisaje africano: los australopitecos gráciles, de constitución ligera, y las formas robustas de mandíbula pesada como Paranthropus boisei, apodado \"Hombre Cascanueces\" por unos dientes hechos para triturar raíces y semillas duras.\n\nLa evolución humana no fue una escalera, sino un arbusto ramificado cuyas ramas están casi todas muertas. Muchas especies de homínidos surgieron, florecieron durante cientos de miles de años y se extinguieron sin dejar descendientes. Somos los únicos supervivientes de una familia antaño concurrida — un hecho que debería inspirar humildad. Nuestra existencia nunca fue inevitable; es el resultado improbable de una larga serie de extinciones en la que, por suerte y adaptación, una pequeña rama perduró.",
      "Hace unos 2,6 millones de años, en las regiones de Gona y Ledi-Geraru de Etiopía, los homínidos empezaron a golpear deliberadamente una piedra contra otra para desprender bordes afiladísimos. Estos simples cantos tallados y lascas cortantes — el instrumental olduvayense, así llamado por la Garganta de Olduvai donde se estudiaron primero — son la tecnología más antigua de la Tierra. Con ellos, nuestros ancestros podían descuartizar carcasas, partir huesos por la médula y procesar plantas que ningún simio podía comer.\n\nLas herramientas de piedra transformaron la dieta de los homínidos y, a través de ella, su cuerpo. El acceso a carne y médula ricas en calorías pudo alimentar el lento crecimiento del cerebro durante los dos millones de años siguientes. Tallar herramientas también exigía previsión, memoria y una mente capaz de imaginar el borde afilado oculto en un canto redondeado. En estas primeras lascas toscas vislumbramos los inicios del rasgo humano definitorio: no la fuerza ni la velocidad, sino la capacidad de rehacer el mundo con una idea.",
      "¿Cómo puede saberse qué ocurrió millones de años antes de la escritura? La respuesta está en una ciencia detectivesca construida a partir de fragmentos. Los fósiles — huesos y dientes mineralizados durante eras — se datan por las capas de ceniza volcánica que los rodean, cuyos elementos radiactivos se desintegran a ritmos conocidos como un reloj geológico. Herramientas de piedra, huesos con marcas de corte y polen antiguo completan el comportamiento y el entorno. En décadas recientes, un testigo nuevo y asombroso se ha sumado al caso: el ADN antiguo, recuperado de huesos de decenas de miles de años, que permite a los científicos leer directamente las relaciones genéticas entre pueblos desaparecidos.\n\nCada descubrimiento reescribe el mapa. La historia aquí contada es provisional, la mejor lectura de la evidencia que tenemos — y cada temporada de campo en África, cada nueva cueva en Asia, puede volcarla. Ese es el vértigo de la prehistoria: es el único capítulo de la historia humana aún en activa exploración, escrito no a partir de documentos, sino de la paciente lectura del hueso, la piedra y la molécula.",
    ],
    ru: [
      "История человека начинается не с царей и городов, а на высыхающих саваннах Африки, около семи миллионов лет назад, когда линия обезьян начала отделяться от предков шимпанзе. У этих древнейших гоминин — существ вроде Sahelanthropus tchadensis, чей череп нашли в Чаде, — мозг был не больше, чем у шимпанзе, но положение отверстия, где позвоночник соединяется с черепом, намекает, что они уже учились ходить прямо.\n\nЗачем ходить на двух ногах? Саванная теория долго утверждала, что по мере того как леса редели, превращаясь в травянистые равнины, прямохождение позволяло предкам видеть поверх травы, носить пищу и детёнышей и эффективно передвигаться по открытой местности. Прямохождение также подставляло меньше тела полуденному солнцу и полностью освобождало руки. Какова бы ни была причина, именно прямохождение — а не большой мозг — стало первой великой адаптацией человека, и всё остальное вытекло из этих освобождённых рук.",
      "В 1974 году в области Афар в Эфиопии палеоантрополог Дональд Джохансон откопал 40 % единственного скелета, которому предстояло стать самым знаменитым ископаемым в мире. Прозванная «Люси» по песне The Beatles, звучавшей в лагере, она принадлежала к виду Australopithecus afarensis и жила около 3,2 миллиона лет назад. Ростом Люси была едва метр, с мозгом втрое меньше нашего — но её таз и коленные суставы доказывают, что она ходила полностью прямо.\n\nЗа год до находки Люси, в Лаэтоли (Танзания), Мэри Лики нашла нечто ещё более пронзительное: цепочку следов, отпечатавшихся в вулканическом пепле 3,6 миллиона лет назад, где двое или трое австралопитеков прошли бок о бок по равнине. Эти следы — с современным сводом и большим пальцем, направленным вперёд, — прямое, безошибочное свидетельство того, что наши предки ходили на двух ногах за миллион лет до первых каменных орудий. Люси и её сородичи ещё не были людьми, но несомненно шли по пути к нам.",
      "Почти весь двадцатый век эволюцию человека представляли как прямое шествие — единую линию всё более высоких и умных предков. Ископаемые рассказывают более запутанную и богатую историю. В любой момент глубокого времени несколько видов гоминин нередко делили африканский ландшафт: изящно сложённые «грацильные» австралопитеки и тяжелочелюстные «массивные» формы вроде Paranthropus boisei, прозванного «Щелкунчиком» за зубы, приспособленные перетирать жёсткие корни и семена.\n\nЭволюция человека была не лестницей, а ветвящимся кустом, почти все ветви которого — тупики. Многие виды гоминин возникали, процветали сотни тысяч лет и исчезали, не оставив потомков. Мы — единственные уцелевшие из некогда многолюдной семьи, и этот факт должен внушать смирение. Наше существование никогда не было неизбежным; это невероятный итог долгой череды вымираний, в которой по счастью и приспособлению уцелела одна маленькая ветвь.",
      "Около 2,6 миллиона лет назад, в областях Гона и Леди-Герару в Эфиопии, гоминины начали намеренно бить камнем о камень, откалывая острые как бритва края. Эти простые рубила и режущие отщепы — олдувайский набор, названный по Олдувайскому ущелью, где их впервые изучили, — древнейшая технология на Земле. С их помощью предки могли разделывать туши, раскалывать кости ради костного мозга и обрабатывать растения, недоступные ни одной обезьяне.\n\nКаменные орудия преобразили рацион гоминин, а через него — и их тело. Доступ к калорийному мясу и мозгу мог питать медленный рост мозга в последующие два миллиона лет. Изготовление орудий требовало также предвидения, памяти и разума, способного вообразить острый край, скрытый в округлом булыжнике. В этих первых грубых отщепах мы различаем начало определяющей человеческой черты: не силы и не скорости, а способности переделывать мир идеей.",
      "Как можно узнать, что происходило за миллионы лет до письменности? Ответ — в детективной науке, собранной из осколков. Ископаемые — кости и зубы, минерализованные за эпохи, — датируют по слоям вулканического пепла, окружающим их, чьи радиоактивные элементы распадаются с известной скоростью, словно геологические часы. Каменные орудия, кости со следами порезов и древняя пыльца дополняют картину поведения и среды. В последние десятилетия к делу присоединился поразительный новый свидетель: древняя ДНК, извлечённая из костей возрастом в десятки тысяч лет, позволяющая учёным напрямую читать генетические связи между исчезнувшими народами.\n\nКаждое открытие переписывает карту. Изложенная здесь история предварительна — это лучшее прочтение имеющихся данных, и каждый полевой сезон в Африке, каждая новая пещера в Азии способны её опрокинуть. В этом и есть азарт доистории: это единственная глава человеческой истории, всё ещё активно открываемая, написанная не по документам, а по терпеливому чтению кости, камня и молекулы.",
    ],
    mk: [
      "Човечката приказна не започнува со кралеви или градови, туку на сушните савани на Африка, пред некои седум милиони години, кога една лоза мајмуни почнала да се одделува од предците на шимпанзата. Овие најрани хоминини — суштества како Sahelanthropus tchadensis, чиј череп е пронајден во Чад — сè уште имале мозоци не поголеми од оние на шимпанзо, но положбата на отворот каде што ‘рбетот се спојува со черепот наговестува дека веќе учеле да стојат исправено.\n\nЗошто да се оди на две нозе? Саванската теорија долго тврдела дека, како шумите се разретчувале во тревници, исправеното стоење им овозможувало на нашите предци да гледаат над тревата, да носат храна и младенчиња и да патуваат ефикасно низ отворен терен. Двоножноста исто така изложувала помалку тело на пладневото сонце и целосно ги ослободувала рацете. Каква и да била причината, исправеното одење — а не големиот мозок — било првата голема човечка адаптација, и сè друго произлегло од тие ослободени раце.",
      "Во 1974 година, во регионот Афар во Етиопија, палеоантропологот Доналд Џохансон ископал 40 % од еден скелет што ќе станел најпознатиот фосил во светот. Наречена „Луси“ по песната на Битлси што свирела во кампот, таа припаѓала на Australopithecus afarensis и живеела пред околу 3,2 милиони години. Луси била едвај еден метар висока, со мозок една третина од нашиот — но нејзиниот карлица и колена докажуваат дека одела целосно исправено.\n\nГодина пред откритието на Луси, во Лаетоли (Танзанија), Мери Лики нашла нешто уште попотресно: трага од отпечатоци втиснати во вулкански пепел пред 3,6 милиони години, каде што двајца или тројца австралопитеци прошетале рамо до рамо по рамнината. Овие отпечатоци — со модерен свод и палец свртен нанапред — се директен, непогрешлив доказ дека нашите предци оделе на две нозе милион години пред првите камени алатки. Луси и нејзините сè уште не биле луѓе, но несомнено биле на патот кон нас.",
      "Речиси цел дваесетти век, човечката еволуција се замислувала како право маршево движење — една линија сè повисоки и попаметни предци. Фосилите раскажуваат позаплеткана и побогата приказна. Во кој било момент од длабокото време, повеќе видови хоминини често го делеле африканскиот пејзаж: лесно граделите „грацилни“ австралопитеци и тешкочелусните „робусни“ форми како Paranthropus boisei, наречен „Оревокршач“ поради заби направени да мелат тврди корени и семиња.\n\nЧовечката еволуција не била скала, туку разгрането грмушесто стебло чии гранки речиси сите се слепи улици. Многу видови хоминини се појавиле, цветале стотици илјади години и исчезнале без да остават потомци. Ние сме единствените преживеани од едно некогаш преполнето семејство — факт што треба да буди понизност. Нашето постоење никогаш не било неизбежно; тоа е неверојатниот исход на долг низ изумирања во кој, по среќа и прилагодување, една мала гранка опстанала.",
      "Пред околу 2,6 милиони години, во регионите Гона и Леди-Герару во Етиопија, хоминините почнале намерно да удираат камен од камен за да откршат острици остри како жилет. Овие едноставни сечила и режечки отсечоци — олдувајскиот прибор, наречен по Клисурата Олдуваи каде што прв пат се проучувале — се најстарата технологија на Земјата. Со нив, нашите предци можеле да сечат трупови, да кршат коски за срцевина и да обработуваат растенија што ниту еден мајмун не можел да ги јаде.\n\nКамените алатки ја преобразиле исхраната на хоминините и, преку неа, нивното тело. Пристапот до калорично месо и срцевина можеби го хранел бавниот раст на мозокот во следните два милиони години. Изработката на алат барала и предвидување, меморија и ум што можел да ја замисли острата раб скриена во заоблена облутка. Во овие први груби отсечоци ги наѕираме почетоците на дефинирачката човечка особина: не силата или брзината, туку способноста да се преобликува светот со идеја.",
      "Како некој може да знае што се случило милиони години пред писмото? Одговорот лежи во детективска наука изградена од фрагменти. Фосилите — коски и заби минерализирани низ ери — се датираат според слоевите вулкански пепел што ги обвиткуваат, чии радиоактивни елементи се распаѓаат со познати брзини како геолошки часовник. Камените алатки, коските со траги од сечење и стариот полен ги дополнуваат однесувањето и средината. Во последните децении, зачудувачки нов сведок се приклучи на случајот: старата ДНК, извлечена од коски стари десетици илјади години, што им овозможува на научниците директно да ги читаат генетските врски меѓу исчезнатите народи.\n\nСекое откритие ја препишува мапата. Приказната раскажана овде е привремена, најдоброто читање на доказите што ги имаме — и секоја теренска сезона во Африка, секоја нова пештера во Азија, може да ја преврти. Тоа е возбудата на праисторијата: тоа е единственото поглавје од човечката приказна сè уште активно откривано, напишано не од документи, туку од трпеливото читање на коската, каменот и молекулата.",
    ],
    de: [
      "Die Geschichte des Menschen beginnt nicht mit Königen oder Städten, sondern in den austrocknenden Savannen Afrikas, vor etwa sieben Millionen Jahren, als sich eine Linie von Affen von den Vorfahren der Schimpansen zu trennen begann. Diese frühesten Homininen — Wesen wie Sahelanthropus tchadensis, dessen Schädel im Tschad gefunden wurde — hatten noch Gehirne kaum größer als die eines Schimpansen, doch die Lage der Öffnung, wo die Wirbelsäule auf den Schädel trifft, deutet an, dass sie bereits aufrecht zu stehen lernten.\n\nWarum auf zwei Beinen gehen? Die Savannentheorie besagte lange, dass der aufrechte Gang, als sich die Wälder in Grasland lichteten, es den Vorfahren erlaubte, über das Gras zu blicken, Nahrung und Kinder zu tragen und offenes Gelände wirksam zu durchqueren. Der aufrechte Gang setzte den Körper zudem weniger der Mittagssonne aus und machte die Hände völlig frei. Welche Ursache auch immer — der aufrechte Gang, nicht ein großes Gehirn, war die erste große menschliche Anpassung, und alles Übrige folgte aus diesen befreiten Händen.",
      "1974 grub der Paläoanthropologe Donald Johanson in der Afar-Region Äthiopiens 40 % eines einzelnen Skeletts aus, das zum berühmtesten Fossil der Welt werden sollte. Nach dem Beatles-Lied benannt, das im Lager lief, hieß sie „Lucy“, gehörte zu Australopithecus afarensis und hatte vor etwa 3,2 Millionen Jahren gelebt. Lucy war kaum einen Meter groß, mit einem Gehirn von einem Drittel unserer Größe — doch ihr Becken und ihre Kniegelenke beweisen, dass sie völlig aufrecht ging.\n\nEin Jahr vor Lucys Entdeckung fand Mary Leakey in Laetoli (Tansania) etwas noch Ergreifenderes: eine Spur von Fußabdrücken, vor 3,6 Millionen Jahren in vulkanische Asche gedrückt, wo zwei oder drei Australopithecinen Seite an Seite über die Ebene geschritten waren. Diese Abdrücke — mit modernem Gewölbe und nach vorn weisender großer Zehe — sind ein direkter, unverkennbarer Beleg dafür, dass unsere Vorfahren eine Million Jahre vor den ersten Steinwerkzeugen auf zwei Beinen gingen. Lucy und ihresgleichen waren noch keine Menschen, doch sie waren unverkennbar auf dem Weg zu uns.",
      "Fast das ganze zwanzigste Jahrhundert stellte man sich die menschliche Evolution als geraden Marsch vor — eine einzige Linie immer größerer, immer klügerer Vorfahren. Die Fossilien erzählen eine wirrere, reichere Geschichte. Zu jedem Zeitpunkt der Tiefenzeit teilten sich oft mehrere Homininenarten die afrikanische Landschaft: die leicht gebauten „graziler“ Australopithecinen und die schwerkiefrigen „robusten“ Formen wie Paranthropus boisei, wegen seiner zum Zermahlen zäher Wurzeln und Samen gebauten Zähne „Nussknackermensch“ genannt.\n\nDie menschliche Evolution war keine Leiter, sondern ein verzweigter Busch, dessen Äste fast alle Sackgassen sind. Viele Homininenarten entstanden, blühten Hunderttausende Jahre und verschwanden, ohne Nachkommen zu hinterlassen. Wir sind die einzigen Überlebenden einer einst dicht bevölkerten Familie — eine Tatsache, die zur Demut mahnen sollte. Unsere Existenz war nie unvermeidlich; sie ist das unwahrscheinliche Ergebnis einer langen Reihe von Aussterben, in der durch Glück und Anpassung ein kleiner Zweig überdauerte.",
      "Vor etwa 2,6 Millionen Jahren begannen Homininen in den Regionen Gona und Ledi-Geraru in Äthiopien, gezielt einen Stein gegen einen anderen zu schlagen, um rasiermesserscharfe Kanten abzuspalten. Diese einfachen Geröllgeräte und schneidenden Abschläge — das Oldowan-Werkzeug, benannt nach der Olduvai-Schlucht, wo man es zuerst untersuchte — sind die älteste Technik der Erde. Mit ihnen konnten unsere Vorfahren Kadaver zerlegen, Knochen für das Mark aufbrechen und Pflanzen verarbeiten, die kein Affe essen konnte.\n\nSteinwerkzeuge veränderten die Ernährung der Homininen und, durch sie, ihren Körper. Der Zugang zu kalorienreichem Fleisch und Mark könnte über die nächsten zwei Millionen Jahre das langsame Wachstum des Gehirns befeuert haben. Werkzeugmachen verlangte auch Voraussicht, Gedächtnis und einen Geist, der sich die im runden Kiesel verborgene scharfe Kante vorstellen konnte. In diesen ersten groben Abschlägen erblicken wir die Anfänge des bestimmenden menschlichen Zuges: nicht Kraft oder Schnelligkeit, sondern die Fähigkeit, die Welt mit einer Idee neu zu formen.",
      "Wie kann irgendjemand wissen, was Millionen Jahre vor der Schrift geschah? Die Antwort liegt in einer detektivischen Wissenschaft, aus Bruchstücken erbaut. Fossilien — über Zeitalter mineralisierte Knochen und Zähne — werden anhand der sie umgebenden Vulkanascheschichten datiert, deren radioaktive Elemente mit bekannten Raten zerfallen wie eine geologische Uhr. Steinwerkzeuge, mit Schnittspuren versehene Knochen und alter Pollen füllen Verhalten und Umwelt aus. In den letzten Jahrzehnten ist ein verblüffender neuer Zeuge hinzugekommen: alte DNA, aus zehntausende Jahre alten Knochen gewonnen, die es Wissenschaftlern erlaubt, die genetischen Beziehungen zwischen verschwundenen Völkern direkt zu lesen.\n\nJede Entdeckung schreibt die Karte neu. Die hier erzählte Geschichte ist vorläufig, die beste Lesart der vorhandenen Belege — und jede Feldsaison in Afrika, jede neue Höhle in Asien kann sie umstürzen. Das ist der Reiz der Urgeschichte: Sie ist das einzige Kapitel der Menschheitsgeschichte, das noch aktiv entdeckt wird, geschrieben nicht aus Dokumenten, sondern aus dem geduldigen Lesen von Knochen, Stein und Molekül.",
    ],
    fr: [
      "L'histoire humaine ne commence pas avec des rois ou des cités, mais dans les savanes desséchées d'Afrique, il y a quelque sept millions d'années, quand une lignée de singes commença à se séparer des ancêtres des chimpanzés. Ces premiers hominidés — des créatures comme Sahelanthropus tchadensis, dont le crâne fut trouvé au Tchad — avaient encore un cerveau à peine plus grand que celui d'un chimpanzé, mais la position de l'orifice où la colonne rejoint le crâne laisse entendre qu'ils apprenaient déjà à se tenir debout.\n\nPourquoi marcher sur deux jambes ? La théorie de la savane a longtemps soutenu qu'à mesure que les forêts s'éclaircissaient en prairies, se tenir droit permettait à nos ancêtres de voir par-dessus l'herbe, de porter nourriture et enfants et de parcourir efficacement le terrain découvert. La bipédie exposait aussi moins le corps au soleil de midi et libérait entièrement les mains. Quelle qu'en fût la cause, la marche debout — et non un grand cerveau — fut la première grande adaptation humaine, et tout le reste découla de ces mains libérées.",
      "En 1974, dans la région de l'Afar en Éthiopie, le paléoanthropologue Donald Johanson exhuma 40 % d'un seul squelette qui allait devenir le fossile le plus célèbre du monde. Surnommée « Lucy » d'après la chanson des Beatles qui passait au campement, elle appartenait à Australopithecus afarensis et avait vécu il y a environ 3,2 millions d'années. Lucy mesurait à peine un mètre, avec un cerveau trois fois plus petit que le nôtre — mais son bassin et ses genoux prouvent qu'elle marchait pleinement debout.\n\nUn an avant la découverte de Lucy, à Laetoli (Tanzanie), Mary Leakey trouva quelque chose de plus émouvant encore : une piste d'empreintes imprimées dans la cendre volcanique il y a 3,6 millions d'années, où deux ou trois australopithèques avaient marché côte à côte à travers la plaine. Ces empreintes — avec une voûte moderne et un gros orteil pointant vers l'avant — sont la preuve directe et indubitable de nos ancêtres marchant sur deux jambes un million d'années avant les premiers outils de pierre. Lucy et les siens n'étaient pas encore humains, mais ils étaient indéniablement sur le chemin qui mène à nous.",
      "Pendant presque tout le XXe siècle, on imagina l'évolution humaine comme une marche rectiligne — une seule lignée d'ancêtres toujours plus grands et plus intelligents. Les fossiles racontent une histoire plus embrouillée et plus riche. À tout moment du temps profond, plusieurs espèces d'hominidés partageaient souvent le paysage africain : les australopithèques « graciles », de constitution légère, et les formes « robustes » à mâchoire lourde comme Paranthropus boisei, surnommé « l'Homme casse-noix » pour des dents faites pour broyer racines et graines coriaces.\n\nL'évolution humaine ne fut pas une échelle mais un buisson ramifié dont presque toutes les branches sont des impasses. Bien des espèces d'hominidés surgirent, prospérèrent des centaines de milliers d'années, puis disparurent sans laisser de descendants. Nous sommes les seuls survivants d'une famille jadis populeuse — un fait qui devrait inspirer l'humilité. Notre existence ne fut jamais inévitable ; elle est le fruit improbable d'une longue série d'extinctions au terme de laquelle, par chance et adaptation, une petite branche subsista.",
      "Il y a environ 2,6 millions d'années, dans les régions de Gona et Ledi-Geraru en Éthiopie, les hominidés se mirent à frapper délibérément une pierre contre une autre pour en détacher des bords tranchants comme des rasoirs. Ces simples choppers et éclats coupants — l'outillage oldowayen, du nom des gorges d'Olduvai où on l'étudia d'abord — sont la plus ancienne technologie de la Terre. Grâce à eux, nos ancêtres pouvaient dépecer les carcasses, briser les os pour la moelle et traiter des plantes qu'aucun singe ne pouvait manger.\n\nLes outils de pierre transformèrent le régime des hominidés et, à travers lui, leur corps. L'accès à une viande et à une moelle riches en calories put alimenter la lente croissance du cerveau au cours des deux millions d'années suivantes. Fabriquer des outils exigeait aussi prévoyance, mémoire et un esprit capable d'imaginer le bord tranchant caché dans un galet arrondi. Dans ces premiers éclats grossiers, on entrevoit les débuts du trait humain déterminant : non la force ni la vitesse, mais la capacité de refaçonner le monde par une idée.",
      "Comment peut-on savoir ce qui se passa des millions d'années avant l'écriture ? La réponse tient dans une science détective bâtie à partir de fragments. Les fossiles — os et dents minéralisés au fil des âges — se datent par les couches de cendre volcanique qui les encadrent, dont les éléments radioactifs se désintègrent à des rythmes connus, telle une horloge géologique. Outils de pierre, os portant des traces de découpe et pollen ancien complètent le comportement et l'environnement. Ces dernières décennies, un témoin nouveau et stupéfiant a rejoint l'enquête : l'ADN ancien, extrait d'os vieux de dizaines de milliers d'années, qui permet aux scientifiques de lire directement les liens génétiques entre des peuples disparus.\n\nChaque découverte réécrit la carte. L'histoire racontée ici est provisoire, la meilleure lecture des indices dont nous disposons — et chaque campagne de fouilles en Afrique, chaque nouvelle grotte en Asie, peut la renverser. C'est là le frisson de la préhistoire : c'est le seul chapitre de l'histoire humaine encore activement découvert, écrit non à partir de documents, mais de la lecture patiente de l'os, de la pierre et de la molécule.",
    ],
  },
  'prehistoric-02': {
    es: [
      "Hace unos 1,9 millones de años, un nuevo tipo de homínido recorría África: Homo erectus, el \"hombre erguido\". Más alto y robusto que los australopitecos, con piernas más largas, brazos más cortos y un cerebro que se acercaba a dos tercios del nuestro, erectus tenía un cuerpo hecho para caminar y correr con resistencia por campo abierto. Era, sin duda, el primer ancestro con aspecto verdaderamente humano.\n\nY no se quedó quieto. Homo erectus fue el primer homínido en salir de África, extendiéndose por Asia en un gran arco. Sus fósiles aparecen como el \"Hombre de Java\" en Indonesia y el \"Hombre de Pekín\" cerca de Pekín, datados en mucho más de un millón de años. Fue una de las especies más exitosas de todo el linaje humano, perdurando casi dos millones de años — unas diez veces más de lo que nuestra propia especie ha existido hasta ahora. Comprender cuán lejos viajó erectus y cuánto duró es captar cuán profundo se hunde el pasado humano.",
      "Ninguna tecnología cambió más el rumbo humano que el fuego. El uso controlado del fuego — no huir de un incendio, sino conservar, alimentar y transportar una llama — es uno de los logros humanos definitorios. Huesos quemados y ceniza de la cueva de Wonderwerk, en Sudáfrica, sugieren que los homínidos usaban el fuego dentro de refugios hace al menos un millón de años, y hacia hace 400.000 años los hogares son comunes por todo el Viejo Mundo.\n\nEl fuego rehízo la vida humana en todos los planos. Empujó atrás la oscuridad y el frío, permitiendo a los homínidos colonizar climas más fríos y seguir activos tras la puesta del sol. Ahuyentaba a los depredadores, convirtiendo la noche de tiempo de terror en tiempo de seguridad junto al hogar. Y, crucialmente, la reunión de la banda en torno a un fuego compartido pudo ser el primer hogar social de la cultura humana — el lugar donde, mucho antes del lenguaje tal como lo conocemos, la gente se sentaba junta, miraba las llamas y empezaba a compartir.",
      "El don más profundo del fuego fue cocinar. El primatólogo Richard Wrangham sostiene que cocinar fue el verdadero motor de la evolución humana. Cocinar gelatiniza el almidón y desnaturaliza la proteína, \"predigiriendo\" en efecto la comida fuera del cuerpo: los platos cocinados liberan muchas más calorías aprovechables y exigen mucha menos masticación y trabajo intestinal que los crudos. Compárense los dientes pequeños, las mandíbulas débiles y el intestino corto del humano con los de un chimpancé, que pasa la mitad de su vida despierta masticando plantas crudas y duras.\n\nLa energía liberada por cocinar, sostiene esta teoría, es lo que pagó el cerebro humano — un órgano que quema alrededor de una quinta parte de nuestras calorías en reposo. Un simio crudívoro sencillamente no puede comer suficientes horas al día para alimentar un cerebro como el nuestro. Al externalizar parte de la digestión al fuego, Homo erectus y sus descendientes pudieron costear cerebros cada vez más grandes y hambrientos. En sentido real, somos el animal que hizo la hoguera.",
      "El giro hacia la comida cocinada dejó su marca en el propio cuerpo humano, y compararnos con nuestros primos simios la vuelve inconfundible. Nuestras mandíbulas menguaron, nuestros dientes se achicaron y nuestro intestino se contrajo — lujos que solo una especie que preprocesa su comida fuera del cuerpo puede permitirse. La energía ya no gastada en digerir pudo redirigirse al cerebro, que se hinchó a lo largo de los linajes de erectus y posteriores desde unos 600 centímetros cúbicos hacia los 1.350 modernos.\n\nEste es un ejemplo llamativo de cómo tecnología y biología coevolucionan: un comportamiento (cocinar) remodeló la anatomía a lo largo de cientos de miles de años, y esa nueva anatomía a su vez hizo posible un comportamiento aún más sofisticado. Homo erectus no planeó nada de esto. Sin embargo, al dominar el fuego, puso en marcha un bucle de retroalimentación entre la cultura y el cuerpo que, a lo largo de un millón de años, produciría una criatura capaz de preguntarse de dónde venía.",
      "Homo erectus también refinó el instrumental de forma drástica. Hacia hace 1,7 millones de años, el tosco canto tallado olduvayense dio paso al bifaz achelense — una herramienta en forma de lágrima trabajada simétricamente por ambas caras hasta un filo fino. El mismo diseño elegante se fabricó, con asombrosamente poca variación, por toda África, Europa y Asia durante más de un millón de años. Es la tecnología más longeva de la historia humana, testimonio de cuán despacio se movían las ideas y cuán honda corría la tradición en aquellas mentes tempranas.\n\nEse conservadurismo es en sí mismo revelador. Durante la mayor parte del pasado humano, el cambio reptaba a paso glacial; el bifaz de un tallador era casi idéntico al de un ancestro lejano de quinientas generaciones atrás. La cultura existía, pero se aprendía por imitación y se transmitía casi sin cambios. La explosión de innovación que damos por sentada quedaba muy lejos en el futuro. La historia de Homo erectus recuerda que, durante más del 99 % de la cronología humana, nuestros ancestros vivieron y murieron en un mundo que se sentía, de una vida a la siguiente, esencialmente inmutable.",
    ],
    ru: [
      "Около 1,9 миллиона лет назад по Африке зашагал новый вид гоминин: Homo erectus, «человек прямоходящий». Более высокий и мощный, чем австралопитеки, с более длинными ногами, короткими руками и мозгом, приближавшимся к двум третям нашего, эректус имел тело, приспособленное для выносливой ходьбы и бега по открытой местности. Это был, по всем меркам, первый по-настоящему человекоподобный предок.\n\nИ он не сидел на месте. Homo erectus первым из гоминин вышел из Африки, расселившись по Азии широкой дугой. Его ископаемые находят как «яванского человека» в Индонезии и «пекинского человека» под Пекином, возрастом далеко за миллион лет. Это был один из самых успешных видов во всей человеческой линии, просуществовавший почти два миллиона лет — примерно в десять раз дольше, чем существует наш собственный вид. Понять, как далеко зашёл эректус и как долго он продержался, — значит осознать, насколько глубоко уходит человеческое прошлое.",
      "Ни одна технология не изменила ход человечества сильнее, чем огонь. Управляемое использование огня — не бегство от пожара, а поддержание, питание и перенос пламени — одно из определяющих человеческих достижений. Обожжённые кости и зола из пещеры Вондерверк в Южной Африке позволяют думать, что гоминины пользовались огнём в укрытиях по меньшей мере миллион лет назад, а к 400 000 лет назад очаги обычны по всему Старому Свету.\n\nОгонь переделал человеческую жизнь на всех уровнях. Он отодвинул тьму и холод, позволив гомининам заселять более холодные земли и оставаться деятельными после заката. Он отпугивал хищников, превращая ночь из времени ужаса во время безопасности у очага. И, что важно, собрание группы вокруг общего огня могло стать первым социальным очагом человеческой культуры — местом, где задолго до языка в нашем понимании люди сидели вместе, смотрели на пламя и начинали делиться.",
      "Глубочайшим даром огня стало приготовление пищи. Приматолог Ричард Рэнгем утверждает, что готовка была подлинным двигателем эволюции человека. Готовка желатинизирует крахмал и денатурирует белок, по сути «переваривая» пищу вне тела: приготовленная еда высвобождает гораздо больше усвояемых калорий и требует куда меньше жевания и работы кишечника, чем сырая. Сравните маленькие зубы, слабые челюсти и короткий кишечник человека с теми, что у шимпанзе, которое проводит половину бодрствования, пережёвывая жёсткие сырые растения.\n\nЭнергия, высвобождённая готовкой, по этой теории, и оплатила человеческий мозг — орган, сжигающий в покое около пятой части наших калорий. Сыроядной обезьяне попросту не хватит часов в сутках, чтобы прокормить мозг вроде нашего. Передав часть пищеварения огню, Homo erectus и его потомки смогли позволить себе всё более крупный и прожорливый мозг. В прямом смысле мы — животное, которое создал костёр.",
      "Переход к приготовленной пище оставил след на самом теле человека, и сравнение с обезьяньими родичами делает перемену очевидной. Наши челюсти уменьшились, зубы измельчали, а кишечник сократился — роскошь, доступная лишь виду, что предварительно обрабатывает пищу вне тела. Энергию, больше не тратимую на переваривание, можно было направить к мозгу, который на протяжении линий эректуса и последующих раздулся примерно с 600 кубических сантиметров к современным 1350.\n\nЭто яркий пример того, как технология и биология эволюционируют совместно: поведение (готовка) переформировало анатомию на протяжении сотен тысяч лет, а эта новая анатомия, в свою очередь, сделала возможным ещё более сложное поведение. Homo erectus ничего этого не планировал. И всё же, овладев огнём, он запустил петлю обратной связи между культурой и телом, которая за миллион лет породит существо, способное спросить, откуда оно взялось.",
      "Homo erectus также резко усовершенствовал набор орудий. Около 1,7 миллиона лет назад грубое олдувайское рубило уступило место ашёльскому ручному рубилу — каплевидному орудию, симметрично обработанному с обеих сторон до тонкого лезвия. Тот же изящный образец изготавливали с поразительно малыми отличиями по всей Африке, Европе и Азии более миллиона лет. Это самая долгоживущая технология в истории человека, свидетельство того, как медленно двигались идеи и как глубоко укоренялась традиция в этих ранних умах.\n\nЭтот консерватизм сам по себе показателен. На протяжении большей части человеческого прошлого перемены ползли ледниковым шагом; рубило одного мастера было почти неотличимо от рубила далёкого предка, отстоящего на пятьсот поколений. Культура существовала, но усваивалась подражанием и передавалась почти без изменений. Взрыв новшеств, который мы принимаем как должное, лежал далеко в будущем. История Homo erectus напоминает, что более 99 % человеческой хронологии наши предки жили и умирали в мире, который от одной жизни к другой ощущался по существу неизменным.",
    ],
    mk: [
      "Пред околу 1,9 милиони години, нов вид хоминин чекорел низ Африка: Homo erectus, „исправениот човек“. Повисок и посилно граден од австралопитеците, со подолги нозе, пократки раце и мозок што се приближувал кон две третини од нашиот, еректус имал тело создадено за издржливо одење и трчање низ отворен терен. Тоа било, по секоја мерка, првиот навистина човеколик предок.\n\nИ не седел мирно. Homo erectus бил првиот хоминин што ја напуштил Африка, ширејќи се низ Азија во голем лак. Неговите фосили се јавуваат како „Јавански човек“ во Индонезија и „Пекиншки човек“ близу Пекинг, датирани на далеку повеќе од милион години. Тоа бил еден од најуспешните видови во целата човечка лоза, опстојувајќи речиси два милиони години — околу десет пати подолго отколку што нашиот вид постои досега. Да се разбере колку далеку патувал еректус и колку долго траел значи да се сфати колку длабоко се протега човечкото минато.",
      "Ниту една технологија не го променила човечкиот тек повеќе од огнот. Контролираната употреба на огнот — не бегање од пожар, туку чување, хранење и носење на пламен — е едно од дефинирачките човечки достигнувања. Изгорени коски и пепел од пештерата Вондерверк во Јужна Африка укажуваат дека хоминините користеле оган во засолништа пред најмалку милион години, а до пред 400.000 години огништата се вообичаени низ целиот Стар Свет.\n\nОгнот го преобликувал човечкиот живот на секое ниво. Ги оттиснал темнината и студот, овозможувајќи им на хоминините да населуваат постудени клими и да останат активни по зајдисонце. Ги плашел предаторите, претворајќи ја ноќта од време на ужас во време на безбедност покрај огништето. И, што е клучно, собирањето на групата околу заеднички оган можеби било првото општествено огниште на човечката култура — местото каде, долго пред јазикот каков што го знаеме, луѓето седеле заедно, гледале во пламените и почнувале да споделуваат.",
      "Најдлабокиот дар на огнот било готвењето. Приматологот Ричард Рангам тврди дека готвењето било вистинскиот мотор на човечката еволуција. Готвењето го желатинизира скробот и ги денатурира протеините, всушност „предвари“ ја храната надвор од телото: готвените оброци ослободуваат многу повеќе искористливи калории и бараат многу помалку џвакање и цревна работа од суровите. Споредете ги малите заби, слабите вилици и краткото црево на човекот со оние на шимпанзото, кое поминува половина од будниот живот џвакајќи тврди сурови растенија.\n\nЕнергијата ослободена со готвењето, тврди оваа теорија, е тоа што го платило човечкиот мозок — орган што согорува околу една петтина од нашите калории во мирување. Мајмун што јаде сурово едноставно не може да јаде доволно часови во денот за да нахрани мозок како нашиот. Со изнесување на дел од варењето на огнот, Homo erectus и неговите потомци можеле да си дозволат сè поголеми и погладни мозоци. Во вистинска смисла, ние сме животното што го создал логорскиот оган.",
      "Преминот кон готвена храна оставил белег врз самото човечко тело, и споредбата со нашите мајмунски роднини ја прави промената непогрешлива. Нашите вилици се намалиле, забите ни станале мали, а цревата ни се собрале — луксузи што само вид што ја преработува храната надвор од телото може да си ги дозволи. Енергијата што повеќе не се трошела на варење можела да се пренасочи кон мозокот, кој низ лозите на еректус и подоцнежните набабрил од околу 600 кубни сантиметри кон модерните 1.350.\n\nОва е впечатлив пример како технологијата и биологијата коеволуираат: однесување (готвење) ја преобликувало анатомијата низ стотици илјади години, а таа нова анатомија пак овозможила уште посложено однесување. Homo erectus ништо од ова не го планирал. Сепак, совладувајќи го огнот, тој пуштил во движење повратна јамка меѓу културата и телото што, низ милион години, ќе создаде суштество способно да праша од каде дошло.",
      "Homo erectus исто така драстично го усовршил приборот. Пред околу 1,7 милиони години, грубото олдувајско сечило му отстапило место на ашелската рачна секира — алат во облик на солза, симетрично обработен од двете страни до фина острица. Истиот елегантен дизајн се изработувал, со зачудувачки мала варијација, низ цела Африка, Европа и Азија повеќе од милион години. Тоа е најдолговечната технологија во човечката историја, сведоштво за тоа колку бавно се движеле идеите и колку длабоко течела традицијата во тие рани умови.\n\nТој конзервативизам сам по себе е откривачки. Во најголемиот дел од човечкото минато, промената ползела со леднички чекор; рачната секира на еден изработувач била речиси идентична со онаа на далечен предок оддалечен петстотини генерации. Културата постоела, но се учела преку имитација и се пренесувала речиси непроменета. Експлозијата на иновации што ја земаме здраво за готово лежела далеку во иднината. Приказната за Homo erectus нè потсетува дека, повеќе од 99 % од човечката хронологија, нашите предци живееле и умирале во свет што се чувствувал, од еден живот до следниот, суштински непроменлив.",
    ],
    de: [
      "Vor etwa 1,9 Millionen Jahren schritt eine neue Art von Homininen durch Afrika: Homo erectus, der „aufrechte Mensch“. Größer und kräftiger gebaut als die Australopithecinen, mit längeren Beinen, kürzeren Armen und einem Gehirn, das sich zwei Dritteln des unseren näherte, hatte erectus einen Körper, der zum ausdauernden Gehen und Laufen über offenes Land gebaut war. Er war, an jedem Maßstab gemessen, der erste wahrhaft menschenähnliche Vorfahr.\n\nUnd er blieb nicht sitzen. Homo erectus war der erste Hominine, der aus Afrika hinauswanderte und sich in einem großen Bogen über Asien ausbreitete. Seine Fossilien tauchen als „Java-Mensch“ in Indonesien und „Peking-Mensch“ nahe Peking auf, datiert auf weit über eine Million Jahre. Er war eine der erfolgreichsten Arten der gesamten menschlichen Linie und bestand fast zwei Millionen Jahre — etwa zehnmal länger, als unsere eigene Art bislang existiert. Zu begreifen, wie weit erectus reiste und wie lange er dauerte, heißt zu erfassen, wie tief die menschliche Vergangenheit reicht.",
      "Keine Technik veränderte den Weg des Menschen mehr als das Feuer. Der kontrollierte Gebrauch des Feuers — nicht vor einem Brand zu fliehen, sondern eine Flamme zu hüten, zu nähren und zu tragen — ist eine der bestimmenden menschlichen Leistungen. Verbrannte Knochen und Asche aus der Wonderwerk-Höhle in Südafrika lassen vermuten, dass Homininen vor mindestens einer Million Jahren Feuer in Unterkünften nutzten, und vor 400.000 Jahren sind Feuerstellen in der ganzen Alten Welt verbreitet.\n\nDas Feuer formte das menschliche Leben auf jeder Ebene neu. Es drängte Dunkelheit und Kälte zurück und erlaubte Homininen, kältere Klimazonen zu besiedeln und nach Sonnenuntergang tätig zu bleiben. Es verscheuchte Raubtiere und machte die Nacht von einer Zeit des Schreckens zu einer Zeit der Sicherheit am Herd. Und entscheidend: die Versammlung der Gruppe um ein gemeinsames Feuer könnte der erste soziale Herd der menschlichen Kultur gewesen sein — der Ort, wo Menschen lange vor der Sprache, wie wir sie kennen, beisammensaßen, in die Flammen sahen und zu teilen begannen.",
      "Die tiefste Gabe des Feuers war das Kochen. Der Primatologe Richard Wrangham argumentiert, das Kochen sei der wahre Motor der menschlichen Evolution gewesen. Kochen geliert Stärke und denaturiert Eiweiß und „verdaut“ die Nahrung gleichsam außerhalb des Körpers vor: gekochte Mahlzeiten setzen weit mehr nutzbare Kalorien frei und erfordern weit weniger Kauen und Darmarbeit als rohe. Man vergleiche die kleinen Zähne, schwachen Kiefer und den kurzen Darm des Menschen mit denen eines Schimpansen, der die Hälfte seines wachen Lebens mit dem Kauen zäher roher Pflanzen verbringt.\n\nDie durch das Kochen freigesetzte Energie, so diese Theorie, ist es, was das menschliche Gehirn bezahlte — ein Organ, das in Ruhe etwa ein Fünftel unserer Kalorien verbrennt. Ein rohkostessender Affe kann schlicht nicht genug Stunden am Tag essen, um ein Gehirn wie das unsere zu speisen. Indem Homo erectus und seine Nachkommen einen Teil der Verdauung an das Feuer auslagerten, konnten sie sich immer größere, immer hungrigere Gehirne leisten. In einem echten Sinn sind wir das Tier, das das Lagerfeuer schuf.",
      "Der Übergang zu gekochter Nahrung hinterließ seine Spur am menschlichen Körper selbst, und der Vergleich mit unseren Affenvettern macht den Wandel unverkennbar. Unsere Kiefer schrumpften, unsere Zähne wurden klein und unser Darm zog sich zusammen — Luxus, den sich nur eine Art leisten kann, die ihre Nahrung außerhalb des Körpers vorverarbeitet. Die nicht länger für die Verdauung aufgewandte Energie konnte zum Gehirn umgeleitet werden, das über die erectus- und späteren Linien von etwa 600 Kubikzentimetern zu den modernen 1.350 anschwoll.\n\nDies ist ein eindrucksvolles Beispiel dafür, wie Technik und Biologie sich gemeinsam entwickeln: ein Verhalten (Kochen) formte über Hunderttausende Jahre die Anatomie um, und diese neue Anatomie machte wiederum noch ausgefeilteres Verhalten möglich. Homo erectus plante nichts davon. Doch indem er das Feuer meisterte, setzte er eine Rückkopplungsschleife zwischen Kultur und Körper in Gang, die über eine Million Jahre ein Wesen hervorbringen würde, das fähig ist zu fragen, woher es kam.",
      "Homo erectus verfeinerte auch den Werkzeugsatz drastisch. Vor etwa 1,7 Millionen Jahren wich das grobe Oldowan-Geröllgerät dem acheuléischen Faustkeil — einem tropfenförmigen Werkzeug, symmetrisch auf beiden Seiten zu einer feinen Schneide gearbeitet. Derselbe elegante Entwurf wurde mit erstaunlich geringer Abweichung über Afrika, Europa und Asien mehr als eine Million Jahre lang hergestellt. Es ist die langlebigste Technik der Menschheitsgeschichte, ein Zeugnis dafür, wie langsam sich Ideen bewegten und wie tief die Tradition in diesen frühen Geistern verlief.\n\nDieser Konservatismus ist selbst aufschlussreich. Über den größten Teil der menschlichen Vergangenheit kroch der Wandel im Gletschertempo; der Faustkeil eines Werkzeugmachers war nahezu identisch mit dem eines fernen Vorfahren fünfhundert Generationen zuvor. Kultur existierte, wurde aber durch Nachahmung erlernt und fast unverändert weitergegeben. Die Explosion der Innovation, die wir für selbstverständlich halten, lag weit in der Zukunft. Die Geschichte des Homo erectus erinnert daran, dass unsere Vorfahren über mehr als 99 % der menschlichen Zeitachse in einer Welt lebten und starben, die sich von einem Leben zum nächsten im Wesentlichen unveränderlich anfühlte.",
    ],
    fr: [
      "Il y a environ 1,9 million d'années, un nouveau type d'hominidé arpentait l'Afrique : Homo erectus, « l'homme debout ». Plus grand et plus robuste que les australopithèques, avec des jambes plus longues, des bras plus courts et un cerveau approchant les deux tiers du nôtre, erectus avait un corps fait pour marcher et courir avec endurance en terrain découvert. C'était, à tous égards, le premier ancêtre à l'aspect véritablement humain.\n\nEt il ne resta pas en place. Homo erectus fut le premier hominidé à quitter l'Afrique, se répandant à travers l'Asie en un vaste arc. Ses fossiles apparaissent sous les noms d'« Homme de Java » en Indonésie et d'« Homme de Pékin » près de Pékin, datés de bien plus d'un million d'années. Ce fut l'une des espèces les plus prospères de toute la lignée humaine, durant près de deux millions d'années — environ dix fois plus longtemps que notre propre espèce n'a existé jusqu'ici. Comprendre jusqu'où voyagea erectus et combien de temps il dura, c'est saisir la profondeur du passé humain.",
      "Aucune technologie ne changea davantage la trajectoire humaine que le feu. L'usage maîtrisé du feu — non pas fuir un incendie, mais garder, nourrir et transporter une flamme — est l'une des réalisations humaines déterminantes. Os brûlés et cendres de la grotte de Wonderwerk, en Afrique du Sud, suggèrent que les hominidés utilisaient le feu dans des abris il y a au moins un million d'années, et il y a 400 000 ans les foyers sont fréquents dans tout l'Ancien Monde.\n\nLe feu refaçonna la vie humaine à tous les niveaux. Il repoussa les ténèbres et le froid, permettant aux hominidés de coloniser des climats plus froids et de rester actifs après le coucher du soleil. Il effrayait les prédateurs, transformant la nuit d'un temps de terreur en un temps de sécurité près du foyer. Et surtout, le rassemblement de la bande autour d'un feu partagé fut peut-être le premier foyer social de la culture humaine — le lieu où, bien avant le langage tel que nous le connaissons, les gens s'asseyaient ensemble, regardaient les flammes et commençaient à partager.",
      "Le don le plus profond du feu fut la cuisson. Le primatologue Richard Wrangham soutient que la cuisson fut le véritable moteur de l'évolution humaine. La cuisson gélatinise l'amidon et dénature les protéines, « prédigérant » en somme la nourriture hors du corps : les repas cuits libèrent bien plus de calories utilisables et exigent bien moins de mastication et de travail intestinal que les crus. Comparez les petites dents, les mâchoires faibles et l'intestin court de l'humain à ceux d'un chimpanzé, qui passe la moitié de sa vie éveillée à mâcher des plantes crues et coriaces.\n\nL'énergie libérée par la cuisson, selon cette théorie, est ce qui paya le cerveau humain — un organe qui brûle environ un cinquième de nos calories au repos. Un singe crudivore ne peut tout simplement pas manger assez d'heures par jour pour alimenter un cerveau comme le nôtre. En externalisant une partie de la digestion vers le feu, Homo erectus et ses descendants purent s'offrir des cerveaux toujours plus grands et plus affamés. En un sens réel, nous sommes l'animal que le feu de camp a fait.",
      "Le passage à la nourriture cuite laissa sa marque sur le corps humain lui-même, et nous comparer à nos cousins singes rend le changement indubitable. Nos mâchoires rétrécirent, nos dents s'amenuisèrent et notre intestin se contracta — des luxes que seule une espèce prétraitant sa nourriture hors du corps peut se permettre. L'énergie qui n'était plus dépensée à digérer put être redirigée vers le cerveau, qui gonfla au fil des lignées d'erectus et des suivantes d'environ 600 centimètres cubes vers les 1 350 modernes.\n\nC'est un exemple frappant de la coévolution de la technique et de la biologie : un comportement (la cuisson) refaçonna l'anatomie sur des centaines de milliers d'années, et cette nouvelle anatomie rendit à son tour possible un comportement encore plus sophistiqué. Homo erectus ne planifia rien de tout cela. Pourtant, en maîtrisant le feu, il enclencha une boucle de rétroaction entre la culture et le corps qui, sur un million d'années, produirait une créature capable de demander d'où elle venait.",
      "Homo erectus perfectionna aussi radicalement la panoplie. Il y a environ 1,7 million d'années, le grossier chopper oldowayen céda la place au biface acheuléen — un outil en forme de larme travaillé symétriquement sur les deux faces jusqu'à un tranchant fin. Le même dessin élégant fut fabriqué, avec une variation étonnamment faible, à travers l'Afrique, l'Europe et l'Asie durant plus d'un million d'années. C'est la technologie la plus durable de l'histoire humaine, témoignage de la lenteur du mouvement des idées et de la profondeur de la tradition dans ces esprits anciens.\n\nCe conservatisme est en soi révélateur. Pendant l'essentiel du passé humain, le changement rampait à un pas glaciaire ; le biface d'un tailleur était presque identique à celui d'un ancêtre lointain de cinq cents générations. La culture existait, mais s'apprenait par imitation et se transmettait presque sans changement. L'explosion d'innovation que nous tenons pour acquise gisait loin dans l'avenir. L'histoire d'Homo erectus rappelle que, pendant plus de 99 % de la chronologie humaine, nos ancêtres vécurent et moururent dans un monde qui semblait, d'une vie à l'autre, essentiellement immuable.",
    ],
  },
  'prehistoric-03': {
    es: [
      "Durante cientos de miles de años, mucho antes de que llegara nuestra especie, Europa y Asia occidental pertenecieron a otro tipo de humano: Homo neanderthalensis. Evolucionados de poblaciones anteriores que habían salido de África, los neandertales estaban soberbiamente adaptados al frío riguroso de la Europa glacial — bajos y de músculos poderosos, con tórax en tonel y narices grandes para calentar el aire helado, y cerebros que eran, de media, algo mayores que el nuestro.\n\nDurante un siglo tras su descubrimiento en el valle de Neander, en Alemania, en 1856, se caricaturizó a los neandertales como cavernícolas encorvados y brutos — la imagen misma de lo \"primitivo\". Casi todo en ese retrato era falso. Los neandertales eran hábiles cazadores de caza mayor que abatían mamuts, bisontes y rinocerontes lanudos a corta distancia con pesadas lanzas de empuje, un modo asombrosamente peligroso de ganarse la vida. Sus fósiles están plagados de fracturas curadas, del tipo que hoy se ve en jinetes de rodeo — prueba no de estupidez, sino de una vida ferozmente física vivida al borde de lo posible.",
      "La vieja imagen del neandertal bruto se ha derrumbado bajo el peso de la evidencia. Los neandertales dominaban el fuego, vestían ropa entallada contra el frío y elaboraban un refinado instrumental de piedra, el musteriense, con una sofisticada técnica de \"núcleo preparado\" que desprendía lascas de forma predeterminada. En yacimientos de España, el ocre rojo y las conchas perforadas insinúan adorno corporal y uso de pigmentos decenas de miles de años antes de que los humanos modernos llegaran a Europa.\n\nMás conmovedor aún, los neandertales enterraban a sus muertos. En la cueva de Shanidar, en Irak, yacía un hombre que había sobrevivido, durante años, con un brazo atrofiado, una cuenca ocular aplastada y otras heridas que lo habrían dejado incapaz de cazar — lo que significa que otros de su banda lo alimentaron y cuidaron. Esto es compasión, en lo hondo del pasado humano, en una especie que no es la nuestra. Si los neandertales hablaban como nosotros sigue debatiéndose, pero poseían el gen FOXP2 vinculado al lenguaje y la anatomía para el habla. No eran humanos fallidos; eran un modo distinto, plenamente humano, de ser.",
      "En 2010, un solo hueso de dedo de la cueva de Denisova, en Siberia, dio una bomba genética: no pertenecía ni a un neandertal ni a un humano moderno, sino a una población humana antes desconocida, hoy llamada los denisovanos. Los conocemos casi por entero a partir del ADN y un puñado de dientes y fragmentos de hueso — toda una rama de la humanidad descubierta no por sus esqueletos, sino por sus genes.\n\nLos denisovanos revelan cuán poblado estaba de verdad el mundo humano reciente. Hace apenas 50.000 años, al menos cuatro tipos de humano compartían el planeta: neandertales en el oeste, denisovanos en el este, el diminuto \"hobbit\" Homo floresiensis en una isla de Indonesia y nuestra propia especie extendiéndose desde África. La genética detecta incluso poblaciones \"fantasma\" — linajes que nunca hemos hallado como fósiles, delatados solo por fragmentos de su ADN que sobreviven en personas vivas. El mundo de un solo humano que damos por sentado es un estado de cosas muy reciente e inusual.",
      "Cuando Homo sapiens salió por fin de África y entró en las tierras de los neandertales, ambos pueblos se encontraron — y el encuentro está escrito en nuestro propio ADN. Toda persona viva cuya ascendencia esté fuera del África subsahariana porta en torno a un uno o dos por ciento de ADN neandertal, legado del mestizaje de hace unos 50.000–60.000 años. Los pueblos de Asia y Oceanía portan también ADN denisovano. No eran especies separadas en sentido estricto; eran poblaciones humanas que podían tener hijos juntas, y los tuvieron.\n\nEsa herencia no es mera curiosidad. Algunas variantes génicas neandertales moldearon respuestas inmunitarias, piel y cabello en los humanos que se adentraron en climas fríos del norte; una variante denisovana ayuda a los tibetanos modernos a prosperar en la altura. Cuando nuestros ancestros salieron de África, no entraban en un mundo vacío — se unían a las otras ramas de la humanidad, y las absorbían. Llevamos a esos primos desaparecidos dentro de nosotros aún hoy.",
      "Hace unos 40.000 años, a los pocos miles de años de llegar Homo sapiens a Europa, los neandertales desaparecieron. Por qué es uno de los grandes misterios de la prehistoria, y la respuesta honesta es que nadie está seguro. Probablemente no hubo una causa única. Los humanos modernos pudieron tener ventajas sutiles — redes sociales más amplias que comerciaban materiales a larga distancia, armas arrojadizas que mataban a distancia más segura, quizá una planificación más flexible o poblaciones mayores que absorbieron a los grupos neandertales, más pequeños, por pura cantidad y mestizaje.\n\nEl clima también tuvo su parte: la última glaciación se sacudió con oscilaciones violentas que estresaron a toda población. Es probable que no hiciera falta ninguna guerra ni matanza dramática — solo que el número de neandertales, siempre escaso en una tierra dura, menguara lentamente por debajo del punto de recuperación mientras nuestra propia especie florecía. Su final no fue seguramente una batalla, sino un desvanecimiento. Y sin embargo no se esfumaron del todo: un fragmento de ellos sobrevive en miles de millones de personas hoy vivas, monumento silencioso a los otros humanos que un día compartieron nuestro mundo.",
    ],
    ru: [
      "Сотни тысяч лет, задолго до появления нашего вида, Европа и западная Азия принадлежали другому виду человека: Homo neanderthalensis. Произошедшие от более ранних популяций, покинувших Африку, неандертальцы были превосходно приспособлены к жестокому холоду ледниковой Европы — приземистые и мощно сложённые, с бочкообразной грудью и крупными носами, согревавшими морозный воздух, и мозгом, в среднем чуть большим, чем наш.\n\nВ течение века после их открытия в Неандертальской долине в Германии в 1856 году неандертальцев изображали как сутулых, грубых пещерных людей — сам образ «примитивного». Почти всё в этой картине было неверно. Неандертальцы были искусными охотниками на крупную дичь, поражавшими мамонтов, бизонов и шерстистых носорогов вблизи тяжёлыми колющими копьями — поразительно опасный способ добывать пропитание. Их кости испещрены зажившими переломами, какие сегодня встречаются у наездников родео, — свидетельство не глупости, а яростно физической жизни, прожитой на грани возможного.",
      "Старый образ грубого неандертальца рухнул под тяжестью улик. Неандертальцы владели огнём, носили подогнанную одежду против холода и изготавливали изысканный каменный набор — мустьерский, — используя сложную технику «подготовленного нуклеуса», отделявшую отщепы заранее заданной формы. На стоянках в Испании красная охра и просверлённые раковины намекают на украшение тела и использование пигментов за десятки тысяч лет до прихода современных людей в Европу.\n\nЕщё трогательнее то, что неандертальцы хоронили своих мёртвых. В пещере Шанидар в Ираке лежал человек, годами проживший с усохшей рукой, раздробленной глазницей и другими увечьями, которые лишили бы его возможности охотиться, — а значит, другие в его группе кормили и опекали его. Это сострадание — в глубине человеческого прошлого, у вида, который не есть наш. Говорили ли неандертальцы, как мы, остаётся спорным, но они обладали связанным с языком геном FOXP2 и анатомией для речи. Они не были неудавшимися людьми; они были иным, вполне человеческим способом бытия.",
      "В 2010 году единственная фаланга пальца из Денисовой пещеры в Сибири произвела генетическую бомбу: она принадлежала ни неандертальцу, ни современному человеку, а прежде неизвестной человеческой популяции, ныне называемой денисовцами. Мы знаем их почти целиком по ДНК и горстке зубов и обломков кости — целая ветвь человечества, открытая не по скелетам, а по генам.\n\nДенисовцы показывают, насколько многолюдным был недавний человеческий мир. Всего 50 000 лет назад планету делили по меньшей мере четыре вида человека: неандертальцы на западе, денисовцы на востоке, крохотный «хоббит» Homo floresiensis на индонезийском острове и наш собственный вид, расселявшийся из Африки. Генетика обнаруживает даже «призрачные» популяции — линии, которых мы никогда не находили в виде ископаемых, выданные лишь фрагментами их ДНК, уцелевшими в живущих людях. Мир единственного человека, который мы принимаем как должное, — весьма недавнее и необычное положение дел.",
      "Когда Homo sapiens наконец вышел из Африки и вступил в земли неандертальцев, два народа встретились — и встреча записана в нашей собственной ДНК. Каждый живущий человек, чьи корни лежат вне субсахарской Африки, несёт примерно один-два процента неандертальской ДНК — наследие скрещивания около 50 000–60 000 лет назад. Народы Азии и Океании несут также денисовскую ДНК. Это не были отдельные виды в строгом смысле; это были человеческие популяции, которые могли иметь детей вместе — и имели.\n\nЭто наследие — не просто любопытство. Некоторые неандертальские генные варианты сформировали иммунные ответы, кожу и волосы у людей, ушедших в холодные северные края; денисовский вариант помогает современным тибетцам благоденствовать на высоте. Когда наши предки покинули Африку, они входили не в пустой мир — они присоединялись к другим ветвям человечества и вбирали их. Мы носим этих исчезнувших родичей внутри себя и поныне.",
      "Около 40 000 лет назад, спустя несколько тысяч лет после прихода Homo sapiens в Европу, неандертальцы исчезли. Почему — одна из великих загадок доистории, и честный ответ таков: никто не уверен. Единственной причины, вероятно, не было. У современных людей могли быть тонкие преимущества — более широкие социальные сети, торговавшие материалами на дальние расстояния, метательное оружие, убивавшее с более безопасного расстояния, возможно, более гибкое планирование или большие популяции, поглотившие меньшие неандертальские группы самой численностью и скрещиванием.\n\nСвою роль сыграл и климат: последняя ледниковая эпоха сотрясалась резкими колебаниями, тяжело сказывавшимися на каждой популяции. Вероятно, никакой драматической войны или бойни не потребовалось — лишь то, что численность неандертальцев, всегда скудная на суровой земле, медленно опустилась ниже точки восстановления, тогда как наш собственный вид процветал. Их конец был, скорее всего, не битвой, а угасанием. И всё же они не исчезли вовсе: их частица живёт в миллиардах людей, живущих ныне, — тихий памятник другим людям, что некогда делили с нами мир.",
    ],
    mk: [
      "Стотици илјади години, долго пред да пристигне нашиот вид, Европа и западна Азија му припаѓале на друг вид човек: Homo neanderthalensis. Еволуирани од порани популации што ја напуштиле Африка, неандерталците биле извонредно прилагодени на лутиот студ на ледничка Европа — ниски и силно мускулести, со буриести гради и големи носеви за да го затоплуваат смрзнатиот воздух, и мозоци што биле, во просек, малку поголеми од нашиот.\n\nЕден век по нивното откритие во Неандерталската долина во Германија во 1856 година, неандерталците биле карикирани како погрбени, груби пештерски луѓе — самата слика на „примитивното“. Речиси сè во таа слика било погрешно. Неандерталците биле вешти ловци на крупен дивеч што соборувале мамути, бизони и волнести носорози оддблиску со тешки прободни копја, зачудувачки опасен начин за преживување. Нивните фосили се преполни со заздравени фрактури, од оние што денес се гледаат кај родео-јавачи — доказ не за глупост, туку за жестоко физички живот проживеан на работ на можното.",
      "Старата слика за грубиот неандерталец се урна под тежината на доказите. Неандерталците владееле со огнот, носеле кроена облека против студот и изработувале рафиниран камен прибор, мустеријанскиот, со софистицирана техника на „подготвено јадро“ што откршувала отсечоци со однапред определена форма. На наоѓалишта во Шпанија, црвениот окер и продупчените школки наговестуваат украсување на телото и употреба на пигменти десетици илјади години пред модерните луѓе да стигнат во Европа.\n\nУште потрогателно, неандерталците ги погребувале своите мртви. Во пештерата Шанидар во Ирак лежел човек што преживеал, со години, со свенната рака, здробена очна дупка и други повреди што би го оставиле неспособен да лови — што значи дека други од неговата група го хранеле и се грижеле за него. Ова е сочувство, длабоко во човечкото минато, кај вид што не е нашиот. Дали неандерталците зборувале како нас останува спорно, но го поседувале генот FOXP2 поврзан со јазикот и анатомијата за говор. Тие не биле неуспешни луѓе; тие биле поинаков, целосно човечки начин на постоење.",
      "Во 2010 година, една единствена коска од прст од пештерата Денисова во Сибир исфрли генетска бомба: не припаѓала ниту на неандерталец ниту на модерен човек, туку на дотогаш непозната човечка популација, денес наречена денисовци. Ги знаеме речиси целосно од ДНК и грст заби и парчиња коска — цела гранка на човештвото откриена не по своите скелети, туку по своите гени.\n\nДенисовците откриваат колку навистина населен бил неодамнешниот човечки свет. Пред само 50.000 години, најмалку четири видови човек ја делеле планетата: неандерталци на запад, денисовци на исток, ситниот „хобит“ Homo floresiensis на еден индонезиски остров и нашиот вид што се ширел од Африка. Генетиката открива дури и „духовни“ популации — лози што никогаш не сме ги нашле како фосили, издадени само од фрагменти од нивната ДНК што преживуваат кај живи луѓе. Светот на еден единствен човек што го земаме здраво за готово е многу неодамнешна и необична состојба.",
      "Кога Homo sapiens конечно излегол од Африка и влегол во неандерталските земји, двата народа се сретнале — и средбата е запишана во нашата сопствена ДНК. Секој жив човек чие потекло лежи надвор од субсахарска Африка носи околу еден до два проценти неандерталска ДНК, наследство од вкрстувањето пред околу 50.000–60.000 години. Народите на Азија и Океанија носат и денисовска ДНК. Тоа не биле одделни видови во строга смисла; тоа биле човечки популации што можеле, и имале, деца заедно.\n\nТоа наследство не е само куриозитет. Некои неандерталски генски варијанти обликувале имунски одговори, кожа и коса кај луѓето што влегле во студените северни клими; една денисовска варијанта им помага на модерните Тибетанци да напредуваат на голема надморска височина. Кога нашите предци ја напуштиле Африка, тие не влегувале во празен свет — се приклучувале, и ги впивале, другите гранки на човештвото. Ги носиме тие исчезнати братучеди во себе и денес.",
      "Пред околу 40.000 години, неколку илјади години по доаѓањето на Homo sapiens во Европа, неандерталците исчезнале. Зошто е една од големите загатки на праисторијата, и искрениот одговор е дека никој не е сигурен. Веројатно немало една единствена причина. Модерните луѓе можеби имале суптилни предности — пошироки општествени мрежи што тргувале со материјали на далечина, фрлачко оружје што убивало од побезбедна далечина, можеби пофлексибилно планирање или поголеми популации што ги впиеле помалите неандерталски групи со сама бројност и вкрстување.\n\nИ климата одиграла своја улога: последната глацијација се тресела со насилни осцилации што ја оптоварувале секоја популација. Веројатно не била потребна никаква драматична војна или колеж — само бројот на неандерталците, секогаш редок на сурова земја, полека да падне под точката на закрепнување додека нашиот вид цветал. Нивниот крај веројатно не бил битка, туку избледување. Сепак, тие не исчезнале сосема: нивен дел преживува кај милијарди луѓе живи денес, тивок споменик на другите луѓе што некогаш го делеле нашиот свет.",
    ],
    de: [
      "Hunderttausende Jahre lang, lange vor der Ankunft unserer eigenen Art, gehörten Europa und Westasien einer anderen Art Mensch: Homo neanderthalensis. Aus früheren Populationen hervorgegangen, die Afrika verlassen hatten, waren die Neandertaler hervorragend an die bittere Kälte des eiszeitlichen Europa angepasst — kurz und kräftig bemuskelt, mit tonnenförmigem Brustkorb und großen Nasen, um die eisige Luft zu wärmen, und Gehirnen, die im Schnitt etwas größer als unsere waren.\n\nEin Jahrhundert lang nach ihrer Entdeckung im Neandertal in Deutschland 1856 wurden Neandertaler als vornübergebeugte, brutale Höhlenmenschen karikiert — das Sinnbild des „Primitiven“. Nahezu alles an diesem Bild war falsch. Neandertaler waren geschickte Großwildjäger, die Mammut, Bison und Wollnashorn aus nächster Nähe mit schweren Stoßspeeren erlegten, eine erstaunlich gefährliche Art, den Lebensunterhalt zu bestreiten. Ihre Fossilien sind durchsetzt von verheilten Brüchen, wie man sie heute bei Rodeoreitern sieht — Beleg nicht für Dummheit, sondern für ein wild körperliches Leben am Rande des Möglichen.",
      "Das alte Bild des brutalen Neandertalers ist unter der Last der Belege zusammengebrochen. Neandertaler beherrschten das Feuer, trugen gegen die Kälte geschneiderte Kleidung und fertigten einen verfeinerten Steinwerkzeugsatz, das Moustérien, mit einer ausgefeilten „Kernvorbereitungs“-Technik, die Abschläge einer vorbestimmten Form ablöste. An Fundstellen in Spanien deuten roter Ocker und durchbohrte Muscheln auf Körperschmuck und Pigmentgebrauch zehntausende Jahre vor der Ankunft moderner Menschen in Europa hin.\n\nAm ergreifendsten: Neandertaler bestatteten ihre Toten. In der Shanidar-Höhle im Irak lag ein Mann, der jahrelang mit einem verkümmerten Arm, einer zerschmetterten Augenhöhle und weiteren Verletzungen überlebt hatte, die ihn jagdunfähig gemacht hätten — was bedeutet, dass andere in seiner Gruppe ihn ernährten und pflegten. Das ist Mitgefühl, tief in der menschlichen Vergangenheit, bei einer Art, die nicht die unsere ist. Ob Neandertaler sprachen wie wir, bleibt umstritten, doch sie besaßen das mit Sprache verknüpfte FOXP2-Gen und die Anatomie zum Sprechen. Sie waren keine gescheiterten Menschen; sie waren eine andere, ganz und gar menschliche Art zu sein.",
      "2010 lieferte ein einzelner Fingerknochen aus der Denisova-Höhle in Sibirien eine genetische Bombe: Er gehörte weder einem Neandertaler noch einem modernen Menschen, sondern einer zuvor unbekannten Menschenpopulation, heute Denisova-Menschen genannt. Wir kennen sie fast ausschließlich aus DNA und einer Handvoll Zähnen und Knochensplittern — ein ganzer Zweig der Menschheit, entdeckt nicht durch seine Skelette, sondern durch seine Gene.\n\nDie Denisova-Menschen zeigen, wie bevölkert die jüngere Menschenwelt wirklich war. Vor gerade 50.000 Jahren teilten sich mindestens vier Menschenarten den Planeten: Neandertaler im Westen, Denisova-Menschen im Osten, der winzige „Hobbit“ Homo floresiensis auf einer indonesischen Insel und unsere eigene Art, die sich aus Afrika ausbreitete. Die Genetik entdeckt sogar „Geister“-Populationen — Linien, die wir nie als Fossilien gefunden haben, verraten nur durch Bruchstücke ihrer DNA, die in lebenden Menschen überdauern. Die Welt des einzigen Menschen, die wir für selbstverständlich halten, ist ein sehr junger und ungewöhnlicher Zustand.",
      "Als Homo sapiens endlich aus Afrika hinauszog und in Neandertalerland eintrat, begegneten sich die beiden Völker — und die Begegnung steht in unserer eigenen DNA geschrieben. Jeder lebende Mensch, dessen Abstammung außerhalb Subsahara-Afrikas liegt, trägt etwa ein bis zwei Prozent Neandertaler-DNA, das Erbe der Vermischung vor etwa 50.000–60.000 Jahren. Völker Asiens und Ozeaniens tragen auch Denisova-DNA. Es waren keine getrennten Arten im strengen Sinn; es waren Menschenpopulationen, die miteinander Kinder haben konnten — und hatten.\n\nDieses Erbe ist nicht bloß eine Kuriosität. Manche Neandertaler-Genvarianten formten Immunantworten, Haut und Haare bei den Menschen, die in kalte nördliche Klimazonen zogen; eine Denisova-Variante hilft heutigen Tibetern, in großer Höhe zu gedeihen. Als unsere Vorfahren Afrika verließen, betraten sie keine leere Welt — sie schlossen sich den anderen Zweigen der Menschheit an und nahmen sie in sich auf. Wir tragen diese verschwundenen Vettern bis heute in uns.",
      "Vor etwa 40.000 Jahren, wenige tausend Jahre nach der Ankunft des Homo sapiens in Europa, verschwanden die Neandertaler. Warum, ist eines der großen Rätsel der Urgeschichte, und die ehrliche Antwort lautet: niemand weiß es gewiss. Wahrscheinlich gab es keine einzige Ursache. Moderne Menschen mochten subtile Vorteile haben — weitere soziale Netze, die Materialien über große Entfernungen tauschten, Wurfwaffen, die aus sichererer Distanz töteten, vielleicht flexiblere Planung oder größere Populationen, welche die kleineren Neandertalergruppen durch schiere Zahl und Vermischung aufsaugten.\n\nAuch das Klima spielte seine Rolle: die letzte Eiszeit taumelte durch heftige Schwankungen, die jede Population belasteten. Wahrscheinlich brauchte es keinen dramatischen Krieg oder ein Massaker — nur, dass die Neandertalerzahlen, auf einem harten Land stets dünn, langsam unter den Punkt der Erholung sanken, während unsere eigene Art gedieh. Ihr Ende war vermutlich keine Schlacht, sondern ein Verlöschen. Doch sie verschwanden nicht gänzlich: ein Bruchteil von ihnen überlebt in Milliarden heute lebender Menschen, ein stilles Denkmal für die anderen Menschen, die einst unsere Welt teilten.",
    ],
    fr: [
      "Pendant des centaines de milliers d'années, bien avant l'arrivée de notre propre espèce, l'Europe et l'Asie de l'Ouest appartenaient à un autre type d'humain : Homo neanderthalensis. Issus de populations antérieures ayant quitté l'Afrique, les Néandertaliens étaient superbement adaptés au froid rigoureux de l'Europe glaciaire — courts et puissamment musclés, avec un thorax en tonneau et de grandes narines pour réchauffer l'air glacé, et un cerveau en moyenne légèrement plus grand que le nôtre.\n\nPendant un siècle après leur découverte dans la vallée de Neander, en Allemagne, en 1856, les Néandertaliens furent caricaturés en hommes des cavernes voûtés et brutaux — l'image même du « primitif ». Presque tout dans ce portrait était faux. Les Néandertaliens étaient d'habiles chasseurs de gros gibier qui abattaient mammouths, bisons et rhinocéros laineux à courte portée avec de lourds épieux d'estoc, une manière étonnamment dangereuse de gagner sa vie. Leurs fossiles sont truffés de fractures guéries, du type que l'on voit aujourd'hui chez les cavaliers de rodéo — preuve non de stupidité, mais d'une vie farouchement physique vécue à la limite du possible.",
      "La vieille image du Néandertalien brutal s'est effondrée sous le poids des preuves. Les Néandertaliens maîtrisaient le feu, portaient des vêtements ajustés contre le froid et façonnaient un outillage de pierre raffiné, le moustérien, selon une technique sophistiquée de « nucléus préparé » qui détachait des éclats d'une forme prédéterminée. Sur des sites d'Espagne, l'ocre rouge et les coquillages percés laissent entrevoir la parure corporelle et l'usage de pigments des dizaines de milliers d'années avant l'arrivée des humains modernes en Europe.\n\nPlus émouvant encore, les Néandertaliens enterraient leurs morts. Dans la grotte de Shanidar, en Irak, gisait un homme qui avait survécu, des années durant, avec un bras atrophié, une orbite écrasée et d'autres blessures qui l'auraient rendu incapable de chasser — ce qui signifie que d'autres, dans sa bande, le nourrissaient et le soignaient. C'est de la compassion, au fond du passé humain, chez une espèce qui n'est pas la nôtre. Que les Néandertaliens aient parlé comme nous reste débattu, mais ils possédaient le gène FOXP2 lié au langage et l'anatomie de la parole. Ce n'étaient pas des humains ratés ; c'était une autre manière, pleinement humaine, d'être.",
      "En 2010, un unique os de doigt de la grotte de Denisova, en Sibérie, livra une bombe génétique : il n'appartenait ni à un Néandertalien ni à un humain moderne, mais à une population humaine jusqu'alors inconnue, aujourd'hui appelée les Dénisoviens. Nous les connaissons presque entièrement à partir de l'ADN et d'une poignée de dents et d'éclats d'os — toute une branche de l'humanité découverte non par ses squelettes, mais par ses gènes.\n\nLes Dénisoviens révèlent à quel point le monde humain récent était peuplé. Il y a à peine 50 000 ans, au moins quatre types d'humains partageaient la planète : les Néandertaliens à l'ouest, les Dénisoviens à l'est, le minuscule « hobbit » Homo floresiensis sur une île d'Indonésie et notre propre espèce se répandant depuis l'Afrique. La génétique détecte même des populations « fantômes » — des lignées que nous n'avons jamais trouvées à l'état de fossiles, trahies seulement par des fragments de leur ADN survivant chez des personnes vivantes. Le monde d'un humain unique que nous tenons pour acquis est un état de choses très récent et inhabituel.",
      "Quand Homo sapiens sortit enfin d'Afrique et pénétra dans les terres néandertaliennes, les deux peuples se rencontrèrent — et la rencontre est inscrite dans notre propre ADN. Toute personne vivante dont l'ascendance se situe hors de l'Afrique subsaharienne porte environ un à deux pour cent d'ADN néandertalien, héritage du métissage d'il y a quelque 50 000–60 000 ans. Les peuples d'Asie et d'Océanie portent aussi de l'ADN dénisovien. Ce n'étaient pas des espèces séparées au sens strict ; c'étaient des populations humaines qui pouvaient avoir des enfants ensemble, et qui en eurent.\n\nCet héritage n'est pas qu'une curiosité. Certaines variantes géniques néandertaliennes ont façonné les réponses immunitaires, la peau et les cheveux chez les humains qui gagnèrent les climats froids du Nord ; une variante dénisovienne aide les Tibétains modernes à prospérer en altitude. Quand nos ancêtres quittèrent l'Afrique, ils n'entraient pas dans un monde vide — ils rejoignaient, et absorbaient, les autres branches de l'humanité. Nous portons encore ces cousins disparus en nous.",
      "Il y a environ 40 000 ans, quelques milliers d'années après l'arrivée d'Homo sapiens en Europe, les Néandertaliens disparurent. Pourquoi est l'un des grands mystères de la préhistoire, et la réponse honnête est que nul n'en est certain. Il n'y eut probablement pas de cause unique. Les humains modernes purent avoir de subtils avantages — des réseaux sociaux plus vastes échangeant des matériaux sur de longues distances, des armes de jet qui tuaient à distance plus sûre, peut-être une planification plus souple ou des populations plus nombreuses qui absorbèrent les groupes néandertaliens, plus petits, par le seul nombre et le métissage.\n\nLe climat joua aussi son rôle : la dernière glaciation fut secouée d'oscillations violentes qui éprouvèrent toute population. Il est probable qu'aucune guerre ni aucun massacre spectaculaire ne fut nécessaire — seulement que les effectifs néandertaliens, toujours ténus sur une terre rude, glissèrent lentement sous le seuil de reconstitution tandis que notre propre espèce prospérait. Leur fin ne fut sans doute pas une bataille mais une extinction lente. Pourtant, ils ne s'évanouirent pas tout à fait : un fragment d'eux survit chez des milliards de personnes vivant aujourd'hui, monument silencieux aux autres humains qui partagèrent jadis notre monde.",
    ],
  },
  'prehistoric-04': {
    es: [
      "Nuestra propia especie, Homo sapiens, surgió en África. Los fósiles más antiguos que se parecen a nosotros proceden de Jebel Irhoud, en Marruecos, y datan de hace unos 300.000 años — empujando el nacimiento de nuestra especie mucho más atrás de lo que se creía, y a lo largo de todo el continente africano y no de una pequeña cuna. Durante la mayor parte de la existencia de nuestra especie, toda la humanidad vivió en África, desarrollando los cuerpos altos y gráciles, los rostros pequeños y los cráneos redondeados que nos distinguen.\n\nLo que de verdad diferenció a nuestros ancestros no fue su cuerpo, sino su comportamiento, y este surgió solo de forma gradual. En yacimientos africanos de hace 100.000 años y más, los arqueólogos hallan cuentas de concha perforada, bloques de ocre grabados con patrones geométricos y herramientas finamente trabajadas de hueso y piedra. Son los primeros destellos de la mente simbólica — del arte, el adorno y el pensamiento abstracto. Algo en la Edad de Piedra Media africana encendió una mecha de creatividad que, con el tiempo, llevaría a nuestra especie a cada rincón de la Tierra.",
      "Hubo dispersiones anteriores y menores, pero la gran migración que pobló el mundo comenzó hace unos 60.000 a 70.000 años, cuando bandas de Homo sapiens cruzaron desde África hacia Asia. Desde esa cabeza de playa se extendieron con pasmosa rapidez por las costas y los valles fluviales del sur de Asia. La genética cuenta la historia: casi todos los que viven hoy fuera de África descienden de esa población fundadora comparativamente pequeña, razón por la cual los pueblos no africanos portan menos diversidad genética que los africanos — la firma del \"cuello de botella\" de aquellos primeros viajeros.\n\nNo eran vagabundos a ciegas. Eran hábiles cazadores-recolectores que leían paisajes, seguían costas y caza y se adaptaban por igual a desiertos, selvas y tundras. En quizá 40.000 años — un latido en tiempo evolutivo — los descendientes de aquel éxodo africano ocuparían casi todos los entornos habitables del planeta, el gran animal más versátil que la Tierra había visto jamás.",
      "La hazaña más asombrosa de aquel viaje temprano fue la colonización de Australia. Hace al menos 50.000 años — y quizá 65.000 — Homo sapiens había alcanzado el continente australiano. No fue una simple caminata. Incluso en los niveles del mar más bajos de la glaciación, llegar a Australia exigía cruzar decenas de kilómetros de océano abierto, fuera de la vista de la otra orilla. Esto significa que nuestros ancestros construían embarcaciones y hacían travesías marítimas deliberadas decenas de miles de años antes de las pirámides, la prueba más antigua de navegación en cualquier parte del mundo.\n\nLos aborígenes australianos que descienden de aquellos primeros marineros mantienen las culturas continuas más antiguas de la Tierra, extendidas en una línea ininterrumpida a lo largo de unas dos mil generaciones. Su llegada coincidió además con la extinción de los gigantescos marsupiales de Australia — el Diprotodon de dos toneladas, semejante a un wómbat, los leones marsupiales y los canguros gigantes — uno de los primeros indicios de un patrón que seguiría a los humanos modernos por todo el globo: dondequiera que llegaba la gente, los mayores animales pronto se esfumaban.",
      "Los últimos grandes continentes en poblarse fueron las Américas. Durante la glaciación, tanta agua quedó atrapada en los glaciares que el nivel del mar descendió, dejando al descubierto Beringia — un ancho puente de pradera donde hoy está el estrecho de Bering, uniendo Siberia con Alaska. En algún momento después de hace unos 20.000 años, y con seguridad hacia hace 15.000, pequeñas bandas de cazadores cruzaron a las Américas, ya por un corredor libre de hielo entre los glaciares, ya en barca por la costa del Pacífico.\n\nLo que siguió fue una de las expansiones más veloces de la historia humana. En unos pocos miles de años, la gente había barrido desde Alaska hasta el extremo sur de Sudamérica — a través de tundra ártica, selva tropical, altas montañas y llanuras herbosas, más de 15.000 kilómetros. Como en Australia, la llegada de hábiles cazadores humanos coincidió con la desaparición de las grandes bestias glaciales: mamuts, mastodontes, perezosos terrestres gigantes y tigres dientes de sable se esfumaron todos. Al término de la glaciación, Homo sapiens había alcanzado todos los continentes salvo la Antártida.",
      "La colonización de la Tierra es el verdadero cimiento de toda la historia posterior, y su escala es fácil de subestimar. En el lapso de unas pocas decenas de miles de años — una astilla del profundo pasado homínido — una sola especie africana se extendió por todo el globo, adaptándose culturalmente y no biológicamente a cada clima que encontraba. Los pueblos del extremo norte aprendieron a vivir del hielo marino y del reno; los del trópico profundo, del pez y del bosque; los del desierto, de las aguas más escasas. Seguimos siendo una sola especie, capaz de mestizarse en todas partes, y sin embargo inventamos miles de modos distintos de ser humanos.\n\nEsta es la raíz honda de la diversidad humana. Las diferencias entre los pueblos del mundo — lenguas, costumbres, tecnologías, creencias — son abrumadoramente culturales, no biológicas, superpuestas a una herencia compartida de solo unos pocos miles de generaciones. Para cuando aparecieron los primeros agricultores y comenzó la historia \"propiamente dicha\", el lienzo humano ya estaba tendido sobre todo el planeta, dispuesto para todo lo que la agricultura, las ciudades y la escritura pronto pintarían sobre él.",
    ],
    ru: [
      "Наш собственный вид, Homo sapiens, возник в Африке. Древнейшие ископаемые, похожие на нас, происходят из Джебель-Ирхуда в Марокко и датируются возрастом около 300 000 лет — отодвигая рождение нашего вида гораздо глубже, чем считалось прежде, и по всему африканскому континенту, а не в одной небольшой колыбели. Большую часть существования нашего вида всё человечество жило в Африке, вырабатывая высокие, изящные тела, малые лица и округлые черепа, что нас отличают.\n\nПо-настоящему выделило наших предков не тело, а поведение, и оно возникало лишь постепенно. На африканских стоянках возрастом 100 000 лет и более археологи находят просверлённые бусины из раковин, куски охры, гравированные геометрическими узорами, и тонко обработанные орудия из кости и камня. Это первые проблески символического разума — искусства, украшения, абстрактной мысли. Нечто в африканском среднем каменном веке зажгло фитиль творчества, который со временем понесёт наш вид в каждый уголок Земли.",
      "Были более ранние, меньшие расселения, но великая миграция, заселившая мир, началась около 60 000–70 000 лет назад, когда группы Homo sapiens перешли из Африки в Азию. С этого плацдарма они расселились с поразительной быстротой по побережьям и речным долинам южной Азии. Генетика рассказывает эту повесть: почти все живущие ныне вне Африки происходят от той сравнительно небольшой основательской популяции, отчего неафриканские народы несут меньше генетического разнообразия, чем африканцы, — след «бутылочного горлышка» тех первых странников.\n\nЭто не были слепые скитальцы. Это были умелые охотники-собиратели, читавшие ландшафты, следовавшие за берегами и дичью и одинаково приспосабливавшиеся к пустыням, джунглям и тундре. За, быть может, 40 000 лет — миг в эволюционном времени — потомки того африканского исхода заняли почти все обитаемые среды планеты, самое приспособляемое крупное животное, какое видела Земля.",
      "Самым захватывающим ранним подвигом того путешествия было заселение Австралии. По меньшей мере 50 000 лет назад — а возможно, и 65 000 — Homo sapiens достиг австралийского материка. Это была не простая прогулка. Даже при самом низком уровне моря ледникового периода достичь Австралии значило пересечь десятки километров открытого океана, вне видимости дальнего берега. Это значит, что наши предки строили лодки и совершали намеренные морские плавания за десятки тысяч лет до пирамид — древнейшее свидетельство мореходства где бы то ни было в мире.\n\nАборигены Австралии, происходящие от тех первых мореходов, хранят древнейшие непрерывные культуры на Земле, тянущиеся неразрывной линией сквозь примерно две тысячи поколений. Их приход совпал также с вымиранием гигантских сумчатых Австралии — двухтонного, похожего на вомбата дипротодона, сумчатых львов и гигантских кенгуру — одним из первых намёков на закономерность, что последует за современными людьми по всему земному шару: куда бы ни приходили люди, крупнейшие животные вскоре исчезали.",
      "Последними великими материками, что были заселены, стали Америки. Во время ледникового периода столько воды было заперто в ледниках, что уровень моря упал, обнажив Берингию — широкий травянистый мост там, где ныне Берингов пролив, соединявший Сибирь с Аляской. Когда-то после примерно 20 000 лет назад, и уж точно к 15 000, малые группы охотников перешли в Америки — либо по свободному ото льда коридору меж ледниками, либо на лодках вдоль тихоокеанского побережья.\n\nЗа этим последовало одно из самых стремительных расселений в истории человека. За несколько тысяч лет люди прошли от Аляски до южной оконечности Южной Америки — сквозь арктическую тундру, тропический дождевой лес, высокие горы и травянистые равнины, более 15 000 километров. Как и в Австралии, приход умелых охотников-людей совпал с исчезновением великих ледниковых зверей: мамонты, мастодонты, гигантские наземные ленивцы и саблезубые кошки — все исчезли. К концу ледникового периода Homo sapiens достиг всех материков, кроме Антарктиды.",
      "Заселение Земли — подлинное основание всей последующей истории, и его размах легко недооценить. За промежуток в несколько десятков тысяч лет — щепку глубокого прошлого гоминин — один африканский вид расселился по всему земному шару, приспосабливаясь культурно, а не биологически к каждому встреченному климату. Народы крайнего севера научились жить на морском льду и северном олене; народы глубоких тропиков — на рыбе и лесе; народы пустыни — на скуднейших водах. Мы остались единым видом, способным скрещиваться повсюду, и всё же изобрели тысячи разных способов быть человеком.\n\nВ этом — глубокий корень человеческого разнообразия. Различия между народами мира — языки, обычаи, технологии, верования — в подавляющем большинстве культурны, а не биологичны, наложены на общее наследие глубиной всего в несколько тысяч поколений. К тому времени, когда появились первые земледельцы и началась «собственно» история, человеческий холст был уже растянут по всей планете, готовый ко всему, что земледелие, города и письменность вскоре напишут на нём.",
    ],
    mk: [
      "Нашиот вид, Homo sapiens, се појавил во Африка. Најстарите фосили што личат на нас потекнуваат од Џебел Ирхуд во Мароко и датираат од пред околу 300.000 години — туркајќи го раѓањето на нашиот вид далеку подлабоко отколку што се мислело, и низ целиот африкански континент, а не во една мала колепка. Во најголемиот дел од постоењето на нашиот вид, целото човештво живеело во Африка, развивајќи ги високите, грациозни тела, малите лица и заоблените черепи што нè обележуваат.\n\nОна што навистина ги издвоило нашите предци не било нивното тело, туку нивното однесување, и тоа се појавило само постепено. На африкански наоѓалишта стари 100.000 години и повеќе, археолозите наоѓаат продупчени монистра од школки, блокови окер врежани со геометриски шари и фино обработени алатки од коска и камен. Тоа се првите искри на симболичкиот ум — на уметноста, украсувањето и апстрактното мислење. Нешто во африканскиот Среден Камен Век запалило фитил на креативност што, со време, ќе го однесе нашиот вид до секој агол на Земјата.",
      "Имало порани, помали расселувања, но големата преселба што го населила светот започнала пред околу 60.000 до 70.000 години, кога групи Homo sapiens преминале од Африка во Азија. Од тој мостобран се рашириле со зачудувачка брзина по крајбрежјата и речните долини на јужна Азија. Генетиката ја кажува приказната: речиси сите што живеат денес надвор од Африка потекнуваат од таа сразмерно мала основачка популација, поради што нежителите на Африка носат помала генетска разновидност од Африканците — потпис на „грлото на шишето“ на тие први патници.\n\nТие не биле слепи скитници. Биле вешти ловци-собирачи што читале пејзажи, следеле крајбрежја и дивеч и се прилагодувале подеднакво на пустини, џунгли и тундри. За можеби 40.000 години — трепет во еволуциско време — потомците на тој африкански исход ќе заземеле речиси секоја населива средина на планетата, најсприлагодливото крупно животно што Земјата некогаш го видела.",
      "Најзапрепастувачкиот ран подвиг на тоа патување било населувањето на Австралија. Пред најмалку 50.000 години — а можеби и 65.000 — Homo sapiens стигнал до австралискиот континент. Тоа не било проста прошетка. Дури и при најниските нивоа на морето во глацијацијата, стигнувањето до Австралија барало преминување десетици километри отворен океан, надвор од видикот на далечниот брег. Ова значи дека нашите предци граделе пловила и правеле намерни морски патувања десетици илјади години пред пирамидите, најстариот доказ за морепловство каде било во светот.\n\nАборигините Австралијци што потекнуваат од тие први морнари ги одржуваат најстарите непрекинати култури на Земјата, протегајќи се во непрекината линија низ околу две илјади генерации. Нивното пристигнување совпаднало и со изумирањето на џиновските торбари на Австралија — двотонскиот, вомбату сличен Diprotodon, торбарските лавови и џиновските кенгури — еден од првите наговестувања на образец што ќе ги следи модерните луѓе низ целиот свет: каде и да пристигнеле луѓето, најголемите животни наскоро исчезнувале.",
      "Последните големи континенти што биле населени биле Америките. За време на глацијацијата, толку многу вода била заклучена во глечерите што морското ниво паднало, откривајќи ја Берингија — широк тревен мост таму каде што денес е Беринговиот теснец, спојувајќи ги Сибир и Алјаска. Некаде по пред околу 20.000 години, а сигурно до 15.000, мали групи ловци преминале во Америките, било низ бесленов коридор меѓу глечерите, било со чамец по пацифичкото крајбрежје.\n\nОна што следело било едно од најбрзите ширења во човечката историја. За неколку илјади години, луѓето прошле од Алјаска до јужниот врв на Јужна Америка — низ арктичка тундра, тропска прашума, високи планини и тревни рамнини, повеќе од 15.000 километри. Како и во Австралија, доаѓањето на вешти човечки ловци совпаднало со исчезнувањето на големите ледени ѕверови: мамутите, мастодонтите, џиновските копнени мрзливци и сабљозабите мачки сите исчезнале. До крајот на глацијацијата, Homo sapiens стигнал до сите континенти освен Антарктикот.",
      "Населувањето на Земјата е вистинскиот темел на целата подоцнежна историја, и неговиот размер лесно се потценува. Во распон од неколку десетици илјади години — иверка од длабокото хоминино минато — еден единствен африкански вид се раширил по целиот свет, прилагодувајќи се културно, а не биолошки на секоја клима што ја сретнал. Народите на далечниот север научиле да живеат од морскиот мраз и ирвасот; народите на длабоките тропи од риба и шума; народите на пустината од најоскудните води. Останавме еден вид, способен да се вкрстува насекаде, а сепак измисливме илјадници различни начини да се биде човек.\n\nОва е длабокиот корен на човечката разновидност. Разликите меѓу народите на светот — јазици, обичаи, технологии, верувања — се преовладувачки културни, а не биолошки, наслоени врз заедничко наследство длабоко само неколку илјади генерации. Кога се појавиле првите земјоделци и започнала „вистинската“ историја, човечкото платно веќе било растегнато врз целата планета, подготвено за сè што земјоделството, градовите и писмото наскоро ќе го насликаат врз него.",
    ],
    de: [
      "Unsere eigene Art, Homo sapiens, entstand in Afrika. Die ältesten Fossilien, die wie wir aussehen, stammen aus Jebel Irhoud in Marokko und datieren auf etwa 300.000 Jahre — womit sich die Geburt unserer Art weit tiefer verschiebt als einst gedacht, und über den ganzen afrikanischen Kontinent statt in einer kleinen Wiege. Über den größten Teil des Bestehens unserer Art lebte die ganze Menschheit in Afrika und entwickelte die hohen, grazilen Körper, kleinen Gesichter und gerundeten Hirnschädel, die uns auszeichnen.\n\nWas unsere Vorfahren wirklich heraushob, war nicht ihr Körper, sondern ihr Verhalten, und es entstand nur allmählich. An afrikanischen Fundstellen, 100.000 Jahre alt und älter, finden Archäologen durchbohrte Muschelperlen, mit geometrischen Mustern gravierte Ockerblöcke und fein gearbeitete Werkzeuge aus Knochen und Stein. Dies sind die ersten Funken des symbolischen Geistes — der Kunst, des Schmucks, des abstrakten Denkens. Etwas in der afrikanischen Mittelsteinzeit zündete eine Lunte der Kreativität, die unsere Art mit der Zeit in jeden Winkel der Erde tragen würde.",
      "Es gab frühere, kleinere Ausbreitungen, doch die große Wanderung, die die Welt bevölkerte, begann vor etwa 60.000 bis 70.000 Jahren, als Gruppen von Homo sapiens aus Afrika nach Asien hinüberzogen. Von diesem Brückenkopf breiteten sie sich mit erstaunlicher Geschwindigkeit über die Küsten und Flusstäler Südasiens aus. Die Genetik erzählt die Geschichte: fast jeder heute außerhalb Afrikas Lebende stammt von jener vergleichsweise kleinen Gründerpopulation ab, weshalb nicht-afrikanische Völker weniger genetische Vielfalt tragen als Afrikaner — die Signatur des „Flaschenhalses“ jener ersten Reisenden.\n\nSie waren keine blinden Umherirrenden. Sie waren geschickte Jäger und Sammler, die Landschaften lasen, Küsten und Wild folgten und sich Wüsten, Dschungeln und Tundren gleichermaßen anpassten. In vielleicht 40.000 Jahren — ein Herzschlag in evolutionärer Zeit — würden die Nachkommen jenes afrikanischen Auszugs nahezu jeden bewohnbaren Lebensraum des Planeten besetzen, das anpassungsfähigste Großtier, das die Erde je gesehen hatte.",
      "Die atemberaubendste frühe Leistung jener Reise war die Besiedlung Australiens. Vor mindestens 50.000 Jahren — und vielleicht 65.000 — hatte Homo sapiens den australischen Kontinent erreicht. Das war kein einfacher Fußmarsch. Selbst bei den niedrigsten eiszeitlichen Meeresspiegeln erforderte das Erreichen Australiens die Überquerung Dutzender Kilometer offenen Ozeans, außer Sicht des fernen Ufers. Das heißt, unsere Vorfahren bauten Wasserfahrzeuge und unternahmen absichtliche Seereisen zehntausende Jahre vor den Pyramiden, der älteste Beleg für Seefahrt irgendwo auf der Welt.\n\nDie Aborigines Australiens, die von jenen ersten Seefahrern abstammen, bewahren die ältesten fortlaufenden Kulturen der Erde, die sich in ununterbrochener Linie über etwa zweitausend Generationen erstrecken. Ihre Ankunft fiel auch mit dem Aussterben der riesigen Beuteltiere Australiens zusammen — dem zwei Tonnen schweren, wombatähnlichen Diprotodon, den Beutellöwen und Riesenkängurus — einer der ersten Hinweise auf ein Muster, das den modernen Menschen über den ganzen Globus folgen sollte: wo immer Menschen ankamen, verschwanden die größten Tiere bald.",
      "Die letzten großen Kontinente, die besiedelt wurden, waren die Amerikas. Während der Eiszeit war so viel Wasser in den Gletschern gebunden, dass der Meeresspiegel sank und Beringia freilegte — eine breite Graslandbrücke, wo heute die Beringstraße liegt und Sibirien mit Alaska verband. Irgendwann nach etwa 20.000 Jahren, und gewiss um 15.000, überquerten kleine Jägergruppen in die Amerikas, sei es durch einen eisfreien Korridor zwischen den Gletschern, sei es per Boot entlang der Pazifikküste.\n\nWas folgte, war eine der schnellsten Ausbreitungen der Menschheitsgeschichte. Innerhalb weniger tausend Jahre waren Menschen von Alaska bis zur Südspitze Südamerikas gefegt — durch arktische Tundra, tropischen Regenwald, hohe Gebirge und Grasebenen, über 15.000 Kilometer. Wie in Australien fiel die Ankunft geschickter menschlicher Jäger mit dem Verschwinden der großen Eiszeittiere zusammen: Mammuts, Mastodonten, Riesenfaultiere und Säbelzahnkatzen verschwanden allesamt. Am Ende der Eiszeit hatte Homo sapiens jeden Kontinent außer der Antarktis erreicht.",
      "Die Besiedlung der Erde ist das wahre Fundament aller späteren Geschichte, und ihr Ausmaß wird leicht unterschätzt. In der Spanne weniger zehntausend Jahre — ein Splitter der tiefen Homininen-Vergangenheit — breitete sich eine einzige afrikanische Art über den gesamten Globus aus und passte sich kulturell, nicht biologisch, an jedes Klima an, dem sie begegnete. Völker des hohen Nordens lernten, von Meereis und Rentier zu leben; Völker der tiefen Tropen von Fisch und Wald; Wüstenvölker vom knappsten Wasser. Wir blieben eine Art, überall kreuzungsfähig, und erfanden doch tausende verschiedene Weisen, Mensch zu sein.\n\nDies ist die tiefe Wurzel der menschlichen Vielfalt. Die Unterschiede zwischen den Völkern der Welt — Sprachen, Bräuche, Techniken, Glaubensvorstellungen — sind überwältigend kulturell, nicht biologisch, einem gemeinsamen Erbe von nur wenigen tausend Generationen Tiefe überlagert. Als die ersten Bauern erschienen und die „eigentliche“ Geschichte begann, war die menschliche Leinwand bereits über den ganzen Planeten gespannt, bereit für alles, was Landwirtschaft, Städte und Schrift bald darauf malen würden.",
    ],
    fr: [
      "Notre propre espèce, Homo sapiens, apparut en Afrique. Les plus anciens fossiles qui nous ressemblent proviennent de Jebel Irhoud, au Maroc, et datent d'environ 300 000 ans — repoussant la naissance de notre espèce bien plus loin qu'on ne le pensait, et à travers tout le continent africain plutôt que dans un petit berceau. Pendant l'essentiel de l'existence de notre espèce, toute l'humanité vécut en Afrique, développant les corps hauts et graciles, les petits visages et les crânes arrondis qui nous distinguent.\n\nCe qui distingua vraiment nos ancêtres ne fut pas leur corps mais leur comportement, et celui-ci n'émergea que graduellement. Sur des sites africains vieux de 100 000 ans et plus, les archéologues trouvent des perles de coquillage percées, des blocs d'ocre gravés de motifs géométriques et des outils finement travaillés en os et en pierre. Ce sont les premières lueurs de l'esprit symbolique — de l'art, de la parure, de la pensée abstraite. Quelque chose, dans l'Âge de pierre moyen africain, alluma une mèche de créativité qui, avec le temps, porterait notre espèce dans chaque recoin de la Terre.",
      "Il y eut des dispersions antérieures et plus modestes, mais la grande migration qui peupla le monde commença il y a environ 60 000 à 70 000 ans, quand des bandes d'Homo sapiens passèrent d'Afrique en Asie. De cette tête de pont, elles se répandirent avec une rapidité stupéfiante le long des côtes et des vallées fluviales de l'Asie du Sud. La génétique raconte l'histoire : presque tous ceux qui vivent aujourd'hui hors d'Afrique descendent de cette population fondatrice relativement petite, ce pourquoi les peuples non africains portent moins de diversité génétique que les Africains — la signature du « goulot d'étranglement » de ces premiers voyageurs.\n\nCe n'étaient pas des errants aveugles. C'étaient d'habiles chasseurs-cueilleurs qui lisaient les paysages, suivaient les côtes et le gibier et s'adaptaient également aux déserts, aux jungles et aux toundras. En quelque 40 000 ans — un battement de cœur en temps évolutif — les descendants de cet exode africain occuperaient presque tous les milieux habitables de la planète, l'animal de grande taille le plus polyvalent que la Terre eût jamais connu.",
      "L'exploit le plus stupéfiant de ce voyage précoce fut le peuplement de l'Australie. Il y a au moins 50 000 ans — et peut-être 65 000 — Homo sapiens avait atteint le continent australien. Ce ne fut pas une simple marche. Même aux plus bas niveaux marins de la glaciation, atteindre l'Australie exigeait de traverser des dizaines de kilomètres d'océan ouvert, hors de vue de la rive lointaine. Cela signifie que nos ancêtres construisaient des embarcations et effectuaient des traversées maritimes délibérées des dizaines de milliers d'années avant les pyramides, la plus ancienne preuve de navigation où que ce soit dans le monde.\n\nLes Aborigènes d'Australie, qui descendent de ces premiers marins, entretiennent les plus anciennes cultures continues de la Terre, s'étirant en une ligne ininterrompue sur quelque deux mille générations. Leur arrivée coïncida aussi avec l'extinction des marsupiaux géants d'Australie — le Diprotodon de deux tonnes, semblable à un wombat, les lions marsupiaux et les kangourous géants — l'un des premiers indices d'un schéma qui suivrait les humains modernes à travers le globe : partout où les gens arrivaient, les plus grands animaux disparaissaient bientôt.",
      "Les derniers grands continents à être peuplés furent les Amériques. Pendant la glaciation, tant d'eau était emprisonnée dans les glaciers que le niveau de la mer baissa, dégageant la Béringie — un large pont de prairie là où se trouve aujourd'hui le détroit de Béring, reliant la Sibérie à l'Alaska. Quelque temps après environ 20 000 ans, et certainement vers 15 000, de petites bandes de chasseurs passèrent dans les Amériques, soit par un corridor libre de glace entre les glaciers, soit en bateau le long de la côte du Pacifique.\n\nCe qui suivit fut l'une des expansions les plus rapides de l'histoire humaine. En quelques milliers d'années, les gens avaient balayé de l'Alaska jusqu'à la pointe sud de l'Amérique du Sud — à travers toundra arctique, forêt tropicale, hautes montagnes et plaines herbeuses, plus de 15 000 kilomètres. Comme en Australie, l'arrivée d'habiles chasseurs humains coïncida avec la disparition des grandes bêtes glaciaires : mammouths, mastodontes, paresseux terrestres géants et tigres à dents de sabre s'évanouirent tous. À la fin de la glaciation, Homo sapiens avait atteint tous les continents sauf l'Antarctique.",
      "Le peuplement de la Terre est le véritable fondement de toute l'histoire ultérieure, et son ampleur est facile à sous-estimer. En l'espace de quelques dizaines de milliers d'années — un éclat du passé profond des hominidés — une seule espèce africaine se répandit sur tout le globe, s'adaptant culturellement et non biologiquement à chaque climat rencontré. Les peuples du grand Nord apprirent à vivre de la banquise et du renne ; ceux des tropiques profonds, du poisson et de la forêt ; ceux du désert, des eaux les plus rares. Nous restâmes une seule espèce, capable de se métisser partout, et pourtant nous inventâmes des milliers de manières distinctes d'être humains.\n\nC'est là la racine profonde de la diversité humaine. Les différences entre les peuples du monde — langues, coutumes, techniques, croyances — sont massivement culturelles, non biologiques, superposées à un héritage commun d'à peine quelques milliers de générations de profondeur. Au moment où apparurent les premiers agriculteurs et où commença l'histoire « proprement dite », la toile humaine était déjà tendue sur toute la planète, prête pour tout ce que l'agriculture, les villes et l'écriture allaient bientôt y peindre.",
    ],
  },
  'prehistoric-05': {
    es: [
      "Durante la inmensa mayoría de la historia humana — más de dos millones y medio de años — el filo de la tecnología fue, literalmente, un filo de piedra. La Edad de Piedra no es una nota primitiva a pie de página, sino con mucho el capítulo más largo de la experiencia humana, y comprenderla es entender cómo una roca tallable se convierte en herramienta. Ciertas piedras, sobre todo el sílex y la obsidiana, se fracturan de un modo predecible, vítreo: golpea una en el ángulo justo con la fuerza justa y salta libre una lasca afilada.\n\nHacer buenas herramientas de piedra es mucho más difícil de lo que parece. Un tallador hábil debe leer la geometría oculta de una piedra, juzgar ángulos y fuerzas y planear varios golpes por adelantado — desprendiendo lascas para dar forma a un núcleo que existe, al principio, solo en la mente. Los experimentos modernos muestran que se tarda años de práctica en dominarlo. En cada lasca de piedra trabajada hay prueba de una mente que planifica y resuelve problemas, y el registro arqueológico de estas herramientas es nuestra ventana más clara a cómo evolucionó esa mente.",
      "Las herramientas más antiguas, las olduvayenses, eran de una hermosa sencillez: un canto golpeado unas cuantas veces para producir un borde cortante irregular y una dispersión de lascas afiladas. Toscas como parecen, fueron revolucionarias, dando a los homínidos el poder de cortar piel, tajar carne y partir hueso que sus dientes y uñas nunca pudieron. Durante casi un millón de años, esto fue toda la tecnología humana.\n\nEntonces, hace unos 1,7 millones de años, Homo erectus logró un salto en el oficio: el bifaz achelense. Trabajado por ambas caras hasta una forma simétrica de lágrima con un borde cortante continuo, era una verdadera herramienta múltiple para descuartizar, cavar y trabajar la madera. Sus artífices sostenían claramente una plantilla mental de la forma acabada y trabajaban hacia ella — una mente capaz de imaginar un objeto e imponerlo a la piedra en bruto. Lo más asombroso es su estabilidad: el mismo diseño se fabricó por tres continentes durante más de un millón de años, el artefacto más duradero que los humanos hayan producido jamás.",
      "Hacia hace unos 300.000 años, un método más sutil y eficiente se extendió por el Viejo Mundo: la técnica de núcleo preparado, perfeccionada por igual por neandertales y humanos modernos tempranos. En lugar de martillar una herramienta directamente de una roca, el tallador daba forma primero con cuidado a un núcleo de piedra — recortando sus bordes y su superficie — de modo que un solo golpe bien dirigido desprendiera una lasca de tamaño y forma predeterminados, lista para usar o para acabarla en punta o raspador.\n\nEste fue un avance cognitivo profundo. El artesano tenía ahora que trabajar hacia atrás desde una imagen mental de la lasca final a través de varias etapas preparatorias, sosteniendo en la mente un plan de varios pasos — un tipo de pensamiento no muy distinto al de un ajedrecista que mira varias jugadas por delante. El método de núcleo preparado también exprimía mucho más filo cortante de cada preciosa pieza de buena piedra. Marca el momento en que la tecnología humana pasó a ser no solo cuestión de manos hábiles, sino de auténtica planificación anticipada y economía de recursos.",
      "Entonces, a partir de hace unos 50.000 años, el ritmo del cambio se transformó. La \"revolución\" del Paleolítico Superior vio una explosión en la variedad y sofisticación de las herramientas que empequeñeció todo lo anterior. Los talladores aprendieron a desprender hojas largas y esbeltas de núcleos cilíndricos, exprimiendo muchos metros de filo cortante de una sola piedra. Combinaron materiales en herramientas compuestas — enmangando puntas de piedra en astiles de madera, engastando hojitas en hueso. Tallaron agujas con ojo para coser ropa entallada, arpones de asta y propulsores que multiplicaban el alcance y la potencia del brazo de un cazador.\n\nCrucialmente, las herramientas variaban ahora por región y cambiaban con rapidez en el tiempo — el sello de la verdadera moda cultural y de la innovación en aceleración. Donde un bifaz había permanecido igual durante un millón de años, los estilos del Paleolítico Superior mudaban cada pocos milenios. Este estallido de creatividad en las herramientas apareció junto al primer arte rupestre, los adornos y la música, lo que sugiere un único cambio subyacente: la llegada de la mente humana plenamente moderna, inquieta, simbólica e infinitamente inventiva.",
      "Entre las más trascendentales de todas las invenciones de la Edad de Piedra estuvo el arco y la flecha, de uso extendido para el final de la glaciación. Los cazadores anteriores tenían que acercarse a distancia de lanzamiento de presas peligrosas; el arco permitía a un cazador matar en silencio y con precisión desde lejos, almacenando energía muscular en una vara doblada y liberándola en un instante. Era más seguro, más letal y exigía fina destreza motriz y la intuición mecánica para almacenar y liberar energía — una auténtica máquina de madera y tendón.\n\nEl arco transformó tanto la caza como, con el tiempo, la guerra, y siguió siendo un arma decisiva durante los diez mil años siguientes, hasta la era de los imperios. Es un emblema apropiado del instrumental de la Edad de Piedra en su conjunto: una tecnología de ingenio asombroso, construida enteramente de madera, piedra, hueso y fibra, por gente sin metal ni escritura. Todo lo que vino después — bronce, hierro, vapor y silicio — se edificó sobre el cimiento puesto, lasca a lasca, a lo largo de aquellos dos millones de años de trabajo de la piedra.",
    ],
    ru: [
      "На протяжении подавляющей части человеческой истории — более двух с половиной миллионов лет — передним краем технологии был буквально край камня. Каменный век — не примитивная сноска, а самая длинная глава человеческого опыта, и понять её значит понять, как раскалываемый камень становится орудием. Некоторые камни, прежде всего кремень и обсидиан, раскалываются предсказуемо, по-стеклянному: ударь по такому под нужным углом с нужной силой — и острый отщеп отскочит сам.\n\nДелать хорошие каменные орудия гораздо труднее, чем кажется. Умелый мастер должен читать скрытую геометрию камня, оценивать углы и силу и планировать несколько ударов вперёд — скалывая отщепы, чтобы придать форму нуклеусу, который поначалу существует лишь в уме. Современные опыты показывают, что на овладение уходят годы практики. В каждом отщепе обработанного камня есть свидетельство планирующего, решающего задачи ума, и археологическая летопись этих орудий — наше яснейшее окно в то, как этот ум развивался.",
      "Древнейшие орудия, олдувайские, были прекрасно просты: галька, ударенная несколько раз ради зазубренного рубящего края и россыпи острых отщепов. Как ни грубы они кажутся, они были революционны, дав гомининам силу резать шкуру, кроить мясо и раскалывать кость, чего никогда не могли их зубы и ногти. Почти миллион лет это была вся человеческая технология.\n\nЗатем, около 1,7 миллиона лет назад, Homo erectus совершил скачок в ремесле: ашёльское ручное рубило. Обработанное с обеих сторон до симметричной каплевидной формы со сплошным режущим краем, оно было подлинным многоцелевым орудием для разделки, копания и обработки дерева. Его создатели явно держали мысленный образец готовой формы и работали к нему — ум, способный вообразить предмет и навязать его сырому камню. Всего поразительнее его устойчивость: тот же образец изготавливали на трёх материках более миллиона лет — самый долговечный артефакт, какой люди когда-либо производили.",
      "Около 300 000 лет назад по Старому Свету распространился более тонкий и рациональный метод: техника подготовленного нуклеуса, доведённая до совершенства как неандертальцами, так и ранними современными людьми. Вместо того чтобы отбивать орудие прямо от камня, мастер сперва тщательно формировал каменный нуклеус — подправляя его края и поверхность, — так что единственный точный удар отделял отщеп заранее заданного размера и формы, готовый к употреблению или к доработке в остриё или скребок.\n\nЭто было глубокое когнитивное продвижение. Мастеру теперь приходилось работать вспять от мысленного образа конечного отщепа через несколько подготовительных стадий, удерживая в уме многошаговый план — мышление, не столь отличное от шахматиста, глядящего на несколько ходов вперёд. Метод подготовленного нуклеуса также выжимал куда больше режущего края из каждого драгоценного куска хорошего камня. Он отмечает миг, когда человеческая технология стала делом не только умелых рук, но и подлинного упреждающего планирования и экономии ресурсов.",
      "Затем, начиная примерно с 50 000 лет назад, темп перемен преобразился. «Революция» верхнего палеолита принесла взрыв разнообразия и изощрённости орудий, затмивший всё прежнее. Мастера научились скалывать длинные, стройные пластины с цилиндрических нуклеусов, выжимая многие метры режущего края из одного камня. Они соединяли материалы в составные орудия — насаживая каменные острия на деревянные древки, вставляя крохотные пластинки в кость. Они вырезали иглы с ушком для шитья подогнанной одежды, гарпуны из рога и копьеметалки, умножавшие дальность и силу руки охотника.\n\nЧто важно, орудия теперь различались по областям и быстро менялись во времени — признак подлинной культурной моды и ускоряющегося новшества. Там, где рубило оставалось неизменным миллион лет, стили верхнего палеолита сменялись каждые несколько тысячелетий. Этот всплеск творчества в орудиях появился рядом с первым пещерным искусством, украшениями и музыкой, что указывает на единую подспудную перемену: приход вполне современного человеческого ума — беспокойного, символического и бесконечно изобретательного.",
      "Среди самых значимых из всех изобретений каменного века был лук и стрелы, широко применявшиеся к концу ледникового периода. Прежним охотникам приходилось подходить на бросок к опасной добыче; лук же позволял охотнику убивать бесшумно и точно издалека, запасая мышечную энергию в согнутом древке и высвобождая её в мгновение. Он был безопаснее, смертоноснее и требовал тонкой моторики и механического чутья, чтобы запасать и высвобождать энергию, — настоящая машина из дерева и жилы.\n\nЛук преобразил и охоту, и со временем войну, и оставался решающим оружием следующие десять тысяч лет, вплоть до эпохи империй. Он — подходящий символ всего каменного набора: технология поразительной изобретательности, построенная целиком из дерева, камня, кости и волокна людьми без металла и письменности. Всё, что пришло позже — бронза, железо, пар и кремний, — было воздвигнуто на основании, заложенном отщеп за отщепом на протяжении тех двух миллионов лет обработки камня.",
    ],
    mk: [
      "Во огромното мнозинство од човечката историја — повеќе од два и пол милиони години — сечилото на технологијата било, буквално, сечило од камен. Каменото Доба не е примитивна фуснота, туку далеку најдолгото поглавје од човечкото искуство, и да се разбере тоа значи да се сфати како еден кршлив камен станува алатка. Некои камења, пред сè кременот и опсидијанот, се кршат на предвидлив, стаклест начин: удри едно под вистинскиот агол со вистинската сила и остар отсечок ќе отскокне слободно.\n\nИзработката на добри камени алатки е многу потешка отколку што изгледа. Вешт изработувач мора да ја чита скриената геометрија на каменот, да проценува агли и сили и да планира неколку удари однапред — откршувајќи отсечоци за да обликува јадро што постои, на почетокот, само во умот. Модерните експерименти покажуваат дека се потребни години вежба за да се совлада. Во секој отсечок обработен камен лежи доказ за ум што планира и решава проблеми, и археолошкиот запис на овие алатки е нашиот најјасен прозорец кон тоа како тој ум еволуирал.",
      "Најстарите алатки, олдувајските, биле прекрасно едноставни: облутка удрена неколку пати за да произведе назабено сечиво и расфрлани остри отсечоци. Колку и груби да изгледаат, биле револуционерни, давајќи им на хоминините моќ да сечат кожа, да режат месо и да кршат коска што нивните заби и нокти никогаш не можеле. Речиси милион години, ова била целата човечка технологија.\n\nПотоа, пред околу 1,7 милиони години, Homo erectus постигнал скок во занаетот: ашелската рачна секира. Обработена од двете страни до симетрична форма на солза со непрекинато сечиво, таа била вистинска повеќенаменска алатка за сечење, копање и обработка на дрво. Нејзините изработувачи јасно држеле мисловен образец на завршената форма и работеле кон него — ум способен да замисли предмет и да го наметне врз суровиот камен. Најзачудувачка е нејзината стабилност: истиот дизајн се изработувал на три континенти повеќе од милион години, најтрајниот артефакт што луѓето некогаш го произвеле.",
      "Пред околу 300.000 години, посуптилен и поефикасен метод се раширил низ Стариот Свет: техниката на подготвено јадро, усовршена подеднакво од неандерталците и раните модерни луѓе. Наместо да чука алатка директно од карпа, изработувачот прво внимателно обликувал камено јадро — поткаструвајќи ги неговите рабови и површина — така што еден единствен добро насочен удар откршувал отсечок со однапред определена големина и форма, готов за употреба или за доработка во врв или стругач.\n\nОва бил длабок когнитивен напредок. Занаетчијата сега морал да работи наназад од мисловна слика на конечниот отсечок низ неколку подготвителни фази, држејќи во умот план во повеќе чекори — вид мислење не многу поинакво од шахист што гледа неколку потези нанапред. Методот на подготвено јадро исто така исцедувал многу повеќе сечиво од секое драгоцено парче добар камен. Тој го означува мигот кога човечката технологија станала не само прашање на вешти раце, туку на вистинско претходно планирање и економија на ресурси.",
      "Потоа, почнувајќи од пред околу 50.000 години, темпото на промена се преобразило. „Револуцијата“ на Горниот Палеолит видела експлозија во разновидноста и софистицираноста на алатките што го засенила сè претходно. Изработувачите научиле да откршуваат долги, витки сечива од цилиндрични јадра, исцедувајќи многу метри сечиво од еден единствен камен. Комбинирале материјали во сложени алатки — насадувајќи камени врвови на дрвени држала, вградувајќи ситни сечива во коска. Резеле игли со уши за шиење кроена облека, харпуни од рог и фрлачи што ги умножувале дофатот и моќта на раката на ловецот.\n\nШто е клучно, алатките сега се разликувале по регион и брзо се менувале со текот на времето — печатот на вистинска културна мода и забрзувачка иновација. Таму каде што рачната секира останала иста милион години, стиловите на Горниот Палеолит се менувале секои неколку милениуми. Овој излив на креативност во алатките се појавил заедно со првата пештерска уметност, украсите и музиката, што укажува на една единствена подлежна промена: доаѓањето на целосно модерниот човечки ум, немирен, симболичен и бескрајно инвентивен.",
      "Меѓу најзначајните од сите изуми на Каменото Доба бил лакот и стрелата, во широка употреба до крајот на глацијацијата. Поранешните ловци морале да се приближат на дострел на фрлање до опасен плен; лакот му овозможувал на ловецот да убива тивко и точно оддалеку, складирајќи мускулна енергија во свиткана прачка и ослободувајќи ја во миг. Бил побезбеден, посмртоносен и барал фина моторика и механичка проникливост за складирање и ослободување енергија — вистинска машина од дрво и жила.\n\nЛакот ги преобразил и ловот и, со време, војувањето, и останал одлучувачко оружје во следните десет илјади години, сè до ерата на империите. Тој е соодветен амблем на приборот на Каменото Доба во целина: технологија со зачудувачка досетливост, изградена целосно од дрво, камен, коска и влакно, од луѓе без метал и без писмо. Сè што дошло потоа — бронза, железо, пареа и силициум — било изградено врз темелот поставен, отсечок по отсечок, низ тие два милиони години обработка на каменот.",
    ],
    de: [
      "Über die überwältigende Mehrheit der Menschheitsgeschichte — mehr als zweieinhalb Millionen Jahre — war die Spitze der Technik im wahrsten Sinne eine Kante aus Stein. Die Steinzeit ist keine primitive Fußnote, sondern das bei weitem längste Kapitel der menschlichen Erfahrung, und sie zu verstehen heißt zu begreifen, wie ein spaltbarer Stein zum Werkzeug wird. Bestimmte Steine, vor allem Feuerstein und Obsidian, brechen auf vorhersehbare, glasartige Weise: schlage einen im richtigen Winkel mit der richtigen Kraft, und ein scharfer Abschlag springt frei.\n\nGute Steinwerkzeuge zu machen ist weit schwerer, als es aussieht. Ein geschickter Klopfer muss die verborgene Geometrie eines Steins lesen, Winkel und Kräfte abschätzen und mehrere Schläge vorausplanen — Abschläge ablösen, um einen Kern zu formen, der zunächst nur im Kopf existiert. Moderne Versuche zeigen, dass es Jahre der Übung braucht, um es zu meistern. In jedem Abschlag bearbeiteten Steins liegt der Beleg eines planenden, problemlösenden Geistes, und die archäologische Überlieferung dieser Werkzeuge ist unser klarstes Fenster darauf, wie sich dieser Geist entwickelte.",
      "Die frühesten Werkzeuge, das Oldowan, waren von schöner Einfachheit: ein Kiesel, ein paar Mal geschlagen, um eine gezackte Hackkante und eine Streuung scharfer Abschläge zu erzeugen. So grob sie scheinen, waren sie revolutionär und gaben Homininen die Macht, Haut zu schneiden, Fleisch zu zerteilen und Knochen zu brechen, was ihre Zähne und Nägel nie vermochten. Fast eine Million Jahre lang war dies die gesamte menschliche Technik.\n\nDann, vor etwa 1,7 Millionen Jahren, gelang Homo erectus ein Sprung im Handwerk: der acheuléische Faustkeil. Auf beiden Seiten zu einer symmetrischen Tropfenform mit durchgehender Schneide gearbeitet, war er ein wahres Mehrzweckwerkzeug zum Zerlegen, Graben und Bearbeiten von Holz. Seine Macher hielten eindeutig eine geistige Vorlage der fertigen Form und arbeiteten darauf hin — ein Geist, der ein Objekt sich vorstellen und dem rohen Stein aufzwingen konnte. Am erstaunlichsten ist seine Beständigkeit: derselbe Entwurf wurde auf drei Kontinenten über eine Million Jahre gefertigt, das langlebigste Artefakt, das Menschen je hervorbrachten.",
      "Vor etwa 300.000 Jahren verbreitete sich eine feinere und wirksamere Methode über die Alte Welt: die Kernvorbereitungstechnik, von Neandertalern und frühen modernen Menschen gleichermaßen vervollkommnet. Statt ein Werkzeug direkt aus einem Stein zu hämmern, formte der Klopfer zunächst sorgfältig einen Steinkern — indem er dessen Kanten und Oberfläche zurichtete — sodass ein einziger, gut gezielter Schlag einen Abschlag vorbestimmter Größe und Form ablöste, gebrauchsfertig oder zur Spitze oder zum Schaber weiterzuarbeiten.\n\nDies war ein tiefgreifender kognitiver Fortschritt. Der Handwerker musste nun rückwärts von einem geistigen Bild des Endabschlags durch mehrere Vorbereitungsstufen arbeiten und einen mehrstufigen Plan im Kopf halten — ein Denken, nicht unähnlich einem Schachspieler, der mehrere Züge vorausblickt. Die Kernvorbereitungsmethode presste zudem weit mehr Schneide aus jedem kostbaren Stück guten Steins. Sie markiert den Augenblick, in dem menschliche Technik nicht bloß eine Sache geschickter Hände, sondern echter vorausschauender Planung und Ressourcenökonomie wurde.",
      "Dann, beginnend vor etwa 50.000 Jahren, verwandelte sich das Tempo des Wandels. Die „Revolution“ des Jungpaläolithikums brachte eine Explosion in Vielfalt und Raffinesse der Werkzeuge, die alles Vorherige in den Schatten stellte. Klopfer lernten, lange, schlanke Klingen von zylindrischen Kernen abzuschlagen und viele Meter Schneide aus einem einzigen Stein zu pressen. Sie kombinierten Materialien zu Verbundwerkzeugen — schäfteten Steinspitzen an Holzschäfte, setzten winzige Klingen in Knochen. Sie schnitzten Nadeln mit Öhr zum Nähen passgenauer Kleidung, Harpunen aus Geweih und Speerschleudern, die Reichweite und Kraft des Jägerarms vervielfachten.\n\nEntscheidend war, dass Werkzeuge nun nach Region variierten und sich rasch mit der Zeit änderten — das Kennzeichen echter kultureller Mode und beschleunigter Innovation. Wo ein Faustkeil eine Million Jahre gleich geblieben war, wechselten jungpaläolithische Stile alle paar Jahrtausende. Dieser Ausbruch von Kreativität bei den Werkzeugen erschien zusammen mit der ersten Höhlenkunst, Schmuck und Musik, was auf eine einzige zugrunde liegende Veränderung hindeutet: die Ankunft des vollständig modernen menschlichen Geistes — ruhelos, symbolisch und endlos erfinderisch.",
      "Zu den folgenreichsten aller Erfindungen der Steinzeit gehörte Pfeil und Bogen, gegen Ende der Eiszeit weit verbreitet. Frühere Jäger mussten bis auf Wurfweite gefährlicher Beute herankommen; der Bogen erlaubte einem Jäger, lautlos und genau aus der Ferne zu töten, indem er Muskelenergie in einem gebogenen Stab speicherte und in einem Augenblick freisetzte. Er war sicherer, tödlicher und verlangte feine Feinmotorik und den mechanischen Einblick, Energie zu speichern und freizusetzen — eine echte Maschine aus Holz und Sehne.\n\nDer Bogen verwandelte sowohl die Jagd als auch schließlich den Krieg und blieb für die nächsten zehntausend Jahre, bis in das Zeitalter der Reiche, eine entscheidende Waffe. Er ist ein passendes Sinnbild für den steinzeitlichen Werkzeugsatz als Ganzes: eine Technik von erstaunlichem Erfindungsreichtum, ganz aus Holz, Stein, Knochen und Faser gebaut, von Menschen ohne Metall und ohne Schrift. Alles, was danach kam — Bronze, Eisen, Dampf und Silizium — wurde auf dem Fundament errichtet, das Abschlag um Abschlag über jene zwei Millionen Jahre der Steinbearbeitung gelegt wurde.",
    ],
    fr: [
      "Pendant l'immense majorité de l'histoire humaine — plus de deux millions et demi d'années — la pointe de la technologie fut, littéralement, un tranchant de pierre. L'âge de pierre n'est pas une note primitive en bas de page, mais de loin le plus long chapitre de l'expérience humaine, et le comprendre, c'est saisir comment une roche taillable devient un outil. Certaines pierres, surtout le silex et l'obsidienne, se fracturent d'une manière prévisible et vitreuse : frappez-en une sous le bon angle avec la bonne force, et un éclat tranchant jaillit librement.\n\nFaire de bons outils de pierre est bien plus difficile qu'il n'y paraît. Un tailleur habile doit lire la géométrie cachée d'une pierre, juger angles et forces et planifier plusieurs coups à l'avance — détachant des éclats pour façonner un nucléus qui n'existe, au début, que dans l'esprit. Les expériences modernes montrent qu'il faut des années de pratique pour le maîtriser. Dans chaque éclat de pierre travaillée gît la preuve d'un esprit qui planifie et résout des problèmes, et le registre archéologique de ces outils est notre fenêtre la plus claire sur la façon dont cet esprit évolua.",
      "Les outils les plus anciens, oldowayens, étaient d'une belle simplicité : un galet frappé quelques fois pour produire un bord tranchant irrégulier et une dispersion d'éclats affûtés. Aussi grossiers qu'ils paraissent, ils furent révolutionnaires, donnant aux hominidés le pouvoir de trancher la peau, de tailler la viande et de briser l'os que leurs dents et leurs ongles ne purent jamais. Pendant près d'un million d'années, ce fut toute la technologie humaine.\n\nPuis, il y a environ 1,7 million d'années, Homo erectus accomplit un bond dans l'art : le biface acheuléen. Travaillé sur les deux faces jusqu'à une forme symétrique en larme au tranchant continu, c'était un véritable outil polyvalent pour dépecer, creuser et travailler le bois. Ses artisans tenaient clairement un gabarit mental de la forme achevée et travaillaient vers lui — un esprit capable d'imaginer un objet et de l'imposer à la pierre brute. Le plus étonnant est sa stabilité : le même dessin fut fabriqué sur trois continents pendant plus d'un million d'années, l'artefact le plus durable que les humains aient jamais produit.",
      "Il y a environ 300 000 ans, une méthode plus subtile et plus efficace se répandit dans l'Ancien Monde : la technique du nucléus préparé, perfectionnée aussi bien par les Néandertaliens que par les premiers humains modernes. Au lieu de marteler un outil directement à partir d'une roche, le tailleur façonnait d'abord soigneusement un nucléus de pierre — en rognant ses bords et sa surface — de sorte qu'un seul coup bien dirigé détache un éclat de taille et de forme prédéterminées, prêt à l'emploi ou à finir en pointe ou en grattoir.\n\nCe fut une avancée cognitive profonde. L'artisan devait désormais travailler à rebours à partir d'une image mentale de l'éclat final, à travers plusieurs étapes préparatoires, tenant en tête un plan en plusieurs étapes — une pensée non sans rappeler celle d'un joueur d'échecs regardant plusieurs coups à l'avance. La méthode du nucléus préparé pressait aussi bien plus de tranchant de chaque précieux morceau de bonne pierre. Elle marque le moment où la technologie humaine devint non seulement affaire de mains habiles, mais de véritable planification anticipée et d'économie des ressources.",
      "Puis, à partir d'environ 50 000 ans, le rythme du changement se transforma. La « révolution » du Paléolithique supérieur vit une explosion dans la variété et la sophistication des outils qui éclipsa tout ce qui l'avait précédé. Les tailleurs apprirent à détacher de longues lames élancées de nucléus cylindriques, pressant bien des mètres de tranchant d'une seule pierre. Ils combinèrent des matériaux en outils composites — emmanchant des pointes de pierre sur des hampes de bois, sertissant de minuscules lamelles dans l'os. Ils taillèrent des aiguilles à chas pour coudre des vêtements ajustés, des harpons de bois de cervidé et des propulseurs qui multipliaient la portée et la puissance du bras du chasseur.\n\nSurtout, les outils variaient désormais selon la région et changeaient rapidement dans le temps — la marque de la véritable mode culturelle et de l'innovation qui s'accélère. Là où un biface était resté identique pendant un million d'années, les styles du Paléolithique supérieur muaient tous les quelques millénaires. Cette explosion de créativité dans les outils apparut aux côtés du premier art pariétal, des parures et de la musique, ce qui suggère un unique changement sous-jacent : l'arrivée de l'esprit humain pleinement moderne, inquiet, symbolique et infiniment inventif.",
      "Parmi les plus lourdes de conséquences de toutes les inventions de l'âge de pierre figura l'arc et la flèche, d'usage répandu à la fin de la glaciation. Les chasseurs antérieurs devaient s'approcher à portée de jet d'une proie dangereuse ; l'arc permettait à un chasseur de tuer silencieusement et avec précision de loin, emmagasinant l'énergie musculaire dans un fût plié et la libérant en un instant. Il était plus sûr, plus meurtrier et exigeait une fine motricité et l'intuition mécanique d'emmagasiner et de libérer l'énergie — une véritable machine de bois et de tendon.\n\nL'arc transforma tant la chasse que, avec le temps, la guerre, et resta une arme décisive pendant les dix mille années suivantes, jusqu'à l'ère des empires. C'est un emblème approprié de la panoplie de l'âge de pierre dans son ensemble : une technologie d'une ingéniosité stupéfiante, bâtie entièrement de bois, de pierre, d'os et de fibre, par des gens sans métal ni écriture. Tout ce qui vint ensuite — bronze, fer, vapeur et silicium — fut édifié sur le fondement posé, éclat après éclat, au long de ces deux millions d'années de travail de la pierre.",
    ],
  },
  'prehistoric-06': {
    es: [
      "En lo hondo de cuevas por toda la Europa glacial, en cámaras que nunca ven la luz del día, nuestros ancestros dejaron un estallido de belleza. En 1994, unos exploradores se colaron en la cueva de Chauvet, en el sur de Francia, y hallaron sus lámparas iluminando paredes vivas de leones, rinocerontes, osos y caballos — pintados con tal confianza y gracia que algunos observadores se negaron a creer que tuvieran 36.000 años. Los tenían, y desde entonces ha aparecido arte figurativo más antiguo en Indonesia, donde una pintura de un jabalí verrugoso data de al menos 45.500 años.\n\nEstas imágenes no eran garabatos ociosos. Yacen en lo hondo bajo tierra, alcanzadas por largos gateos en la oscuridad, pintadas al parpadeo de lámparas de sebo. Los artistas entendían la perspectiva, el movimiento y el hinchazón de un cuerpo vivo; usaban los abultamientos naturales de la roca para dar a sus animales forma tridimensional. Estar ante ellas es sentir la presencia de una mente exactamente igual a la nuestra — una mente que veía, imaginaba y necesitaba hacer visible lo que imaginaba. Aquí, decenas de miles de años antes de la escritura, está el inconfundible amanecer del arte.",
      "¿Para qué eran las pinturas rupestres? Nunca lo sabremos del todo, pero las propias imágenes ofrecen pistas. Los animales son de forma abrumadora las grandes bestias de la glaciación — caballos, bisontes, uros, mamuts, leones — mientras que las plantas y las criaturas pequeñas que componían gran parte de la dieta diaria están casi ausentes. Esto sugiere que las cuevas no eran libros ilustrados del menú, sino algo cargado de significado: quizá lugares de ritual, de iniciación, de magia de caza o de contacto con un mundo espiritual intuido tras los animales.\n\nManos fantasmales pueblan muchas cuevas — plantillas hechas soplando pigmento en torno a una mano presionada contra la pared, algunas de niños pequeños, muchas con dedos aparentemente ausentes. A lo largo de miles de kilómetros y miles de años, la gente volvía a estos lugares profundos a dejar sus marcas en la oscuridad. Signifiquen lo que signifiquen las pinturas, prueban que los humanos glaciales poseían ricos mundos simbólicos, internos y compartidos — creencias, relatos y rituales que unían a una comunidad. La mente simbólica, una vez encendida, ya nunca volvería a apagarse.",
      "El arte no se limitó a las paredes de las cuevas. Por toda la Europa y Asia glaciales, la gente talló pequeñas esculturas — las famosas \"figuras de Venus\", mujeres del tamaño de la palma trabajadas en piedra, marfil y arcilla cocida. La Venus de Willendorf, tallada hace unos 25.000 años, y docenas más comparten un llamativo parecido de familia a lo largo de miles de kilómetros, lo que insinúa creencias compartidas que abarcaban todo el continente. Representaran fertilidad, ancestros, diosas u otra cosa por completo, muestran un pueblo que invertía hondo significado en la forma humana.\n\nMás antiguo aún es el Hombre León de Hohlenstein-Stadel, una figura de 40.000 años de un humano de cabeza de león, tallada en marfil de mamut. Es quizá el objeto más importante de la prehistoria, pues representa algo que no existe en la naturaleza — un ser mitad humano, mitad bestia. Para tallarlo, su artífice tuvo que imaginar una criatura nunca vista y luego traerla al mundo. Esa es la esencia de la imaginación humana: el poder de concebir lo que no es, ya sea un hombre-león, un dios, una nación o un número.",
      "La mente glacial cantaba tanto como pintaba. De las mismas cuevas y campamentos proceden los instrumentos musicales más antiguos del mundo: flautas talladas en hueso de ave y marfil de mamut, algunas de más de 40.000 años, con orificios para los dedos cuidadosamente perforados y afinados para producir una escala. Una réplica de una de estas flautas toca melodías reconocibles. Donde había flautas había sin duda voces, tambores y danza, aunque solo perdure el hueso.\n\nLa música, como la pintura, no sirve a ningún propósito de supervivencia obvio — no puedes comerte una canción — y sin embargo toda cultura humana de la Tierra la hace, lo que nos dice que el impulso es antiguo y universal. En torno al fuego glacial, la música habría unido a la gente en ritmo y emoción compartidos, portado relatos y memoria a través de generaciones antes de la escritura, y marcado los grandes momentos de la vida y la muerte. El descubrimiento de estas flautas nos recuerda que nuestros ancestros no solo sobrevivieron a la glaciación; la llenaron de significado, imagen y canto.",
      "El florecimiento del arte, el adorno y la música en el Paleolítico Superior marca uno de los verdaderos puntos de inflexión de la historia humana — posiblemente tan importante como el dominio del fuego o la invención de la agricultura. Es la firma arqueológica de la \"modernidad conductual\": el momento en que podemos estar seguros de que nuestros ancestros pensaban, sentían, creían e imaginaban como nosotros. Todo lo que hace distintiva la cultura humana — la religión, la narración, el arte, la ciencia, la capacidad de compartir ideas que solo existen en la mente — fluye de la capacidad simbólica que revelan estas paredes de cueva.\n\nUn pueblo capaz de pintar un caballo puede también imaginar un espíritu, una ley, un plan para la caza del año que viene o un dios. El mismo poder que llenó las cuevas de bestias llenaría, con el tiempo, el mundo de mitos, matemáticas y máquinas. Cuando estamos en un museo ante una figura tallada de 30.000 años y sentimos un destello de reconocimiento, estamos encontrándonos con nuestra propia mente a través de un abismo inmenso de tiempo — y descubriendo que el ser humano esencial, el que imagina, ya estaba plenamente presente mucho antes de que se construyera la primera ciudad.",
    ],
    ru: [
      "В глубине пещер по всей ледниковой Европе, в залах, никогда не видящих дневного света, наши предки оставили потрясение красоты. В 1994 году исследователи протиснулись в пещеру Шове на юге Франции и увидели, как их лампы освещают стены, живые от львов, носорогов, медведей и лошадей, написанных с такой уверенностью и изяществом, что иные наблюдатели отказывались верить, будто им 36 000 лет. Им столько и было, а с тех пор ещё более древнее фигуративное искусство обнаружилось в Индонезии, где изображение бородавчатой свиньи датируется по меньшей мере 45 500 годами.\n\nЭти образы не были праздными каракулями. Они лежат глубоко под землёй, достижимые лишь долгими проползаниями во тьме, написанные при мерцании жировых светильников. Художники понимали перспективу, движение и вздутие живого тела; они использовали естественные выпуклости скалы, чтобы придать своим животным трёхмерную форму. Стоять перед ними — значит ощущать присутствие ума, в точности подобного нашему, — ума, который видел, воображал и нуждался сделать зримым воображённое. Здесь, за десятки тысяч лет до письменности, — безошибочный рассвет искусства.",
      "Для чего были пещерные росписи? Мы никогда не узнаем вполне, но сами образы дают подсказки. Животные — преимущественно великие звери ледникового периода: лошади, бизоны, туры, мамонты, львы, — тогда как растения и мелкие твари, составлявшие значительную часть повседневного рациона, почти отсутствуют. Это наводит на мысль, что пещеры были не иллюстрированными меню, а чем-то заряженным смыслом: быть может, местами ритуала, посвящения, охотничьей магии или соприкосновения с духовным миром, угадываемым за животными.\n\nПризрачные отпечатки рук населяют многие пещеры — трафареты, сделанные выдуванием пигмента вокруг руки, прижатой к стене, некоторые — детских рук, у многих словно недостают пальцы. На протяжении тысяч километров и тысяч лет люди возвращались в эти глубокие места, чтобы оставить свои метки во тьме. Что бы ни значили росписи, они доказывают, что люди ледникового периода обладали богатыми внутренними и общими символическими мирами — верованиями, преданиями и обрядами, связывавшими общину. Символический ум, однажды зажжённый, уже никогда не погаснет.",
      "Искусство не ограничивалось стенами пещер. По всей ледниковой Европе и Азии люди вырезали малые скульптуры — знаменитые «фигурки Венеры», женщины размером с ладонь, выполненные в камне, слоновой кости и обожжённой глине. Венера из Виллендорфа, вырезанная около 25 000 лет назад, и десятки других имеют поразительное семейное сходство на протяжении тысяч километров, что намекает на общие верования, охватывавшие весь материк. Изображали ли они плодородие, предков, богинь или что-то совсем иное, они показывают народ, вкладывавший глубокий смысл в человеческую форму.\n\nЕщё древнее — Человек-лев из Холенштайн-Штаделя, фигура возрастом 40 000 лет: стоящий человек с головой льва, вырезанный из мамонтовой кости. Это, пожалуй, самый важный предмет доистории, ибо он изображает то, чего нет в природе, — существо наполовину человека, наполовину зверя. Чтобы вырезать его, творцу пришлось вообразить никогда не виданное существо, а затем привести его в мир. В этом суть человеческого воображения: способность помыслить то, чего нет, — будь то человек-лев, бог, нация или число.",
      "Ледниковый ум пел не меньше, чем рисовал. Из тех же пещер и стоянок происходят древнейшие музыкальные инструменты в мире: флейты, вырезанные из птичьей кости и мамонтовой кости, некоторым более 40 000 лет, с тщательно просверлёнными пальцевыми отверстиями, настроенными на звукоряд. Копия одной такой флейты играет узнаваемые мелодии. Где были флейты, там наверняка были голоса, барабаны и танец, хотя уцелела лишь кость.\n\nМузыка, как и живопись, не служит никакой очевидной цели выживания — песню не съешь, — и всё же всякая человеческая культура на Земле её творит, что говорит нам: этот порыв древен и всеобщ. Вокруг ледникового огня музыка связывала бы людей в общем ритме и чувстве, несла бы предания и память сквозь поколения до письменности и отмечала бы великие мгновения жизни и смерти. Открытие этих флейт напоминает, что наши предки не просто пережили ледниковый период; они наполнили его смыслом, образом и песней.",
      "Расцвет искусства, украшения и музыки в верхнем палеолите отмечает один из подлинных поворотных пунктов человеческой истории — пожалуй, столь же важный, как покорение огня или изобретение земледелия. Это археологический признак «поведенческой современности»: миг, когда мы можем быть уверены, что наши предки мыслили, чувствовали, верили и воображали, как мы. Всё, что делает человеческую культуру особенной — религия, повествование, искусство, наука, способность делиться идеями, существующими лишь в уме, — вытекает из символической способности, которую являют эти пещерные стены.\n\nНарод, способный написать лошадь, способен и вообразить духа, закон, план будущей охоты или бога. Та самая сила, что наполнила пещеры зверями, со временем наполнит мир мифами, математикой и машинами. Когда мы стоим в музее перед вырезанной 30 000 лет назад фигурой и ощущаем проблеск узнавания, мы встречаем собственный ум через огромную бездну времени — и обнаруживаем, что сущностный человек, воображающий, уже вполне присутствовал задолго до того, как был построен первый город.",
    ],
    mk: [
      "Длабоко во пештерите низ цела ледничка Европа, во одаи што никогаш не гледаат дневна светлина, нашите предци оставиле шок на убавина. Во 1994 година, истражувачи се провлекле во пештерата Шове во јужна Франција и ги нашле своите ламби како осветлуваат ѕидови живи од лавови, носорози, мечки и коњи — насликани со таква сигурност и грациозност што некои набљудувачи одбиле да поверуваат дека се стари 36.000 години. Биле, а оттогаш се појавила и постара фигуративна уметност во Индонезија, каде што слика на брадавичесто прасе датира од најмалку 45.500 години.\n\nОвие слики не биле безделни шкработини. Тие лежат длабоко под земја, достигнати преку долги ползења во темнина, насликани при трепкањето на лоени ламби. Уметниците ја разбирале перспективата, движењето и надуеноста на живото тело; ги користеле природните испакнатини на карпата за да им дадат на своите животни тродимензионална форма. Да се стои пред нив значи да се почувствува присуство на ум точно ист како нашиот — ум што гледал, замислувал и имал потреба да го направи видливо она што го замислувал. Тука, десетици илјади години пред писмото, е непогрешливата зора на уметноста.",
      "За што биле пештерските слики? Никогаш нема да дознаеме целосно, но самите слики нудат траги. Животните се претежно големите ѕверови на глацијацијата — коњи, бизони, тури, мамути, лавови — додека растенијата и малите суштества што сочинувале голем дел од секојдневната исхрана се речиси отсутни. Ова наведува дека пештерите не биле сликовници на менито, туку нешто наполнето со значење: можеби места на ритуал, на иницијација, на ловечка магија или на допир со духовен свет насетен зад животните.\n\nДуховни отпечатоци од раце населуваат многу пештери — шаблони направени со дување пигмент околу рака притисната на ѕидот, некои од мали деца, многу со прсти навидум што недостасуваат. Низ илјадници километри и илјадници години, луѓето се враќале на овие длабоки места да ги остават своите траги во темнината. Што и да значеле сликите, тие докажуваат дека ледничките луѓе поседувале богати внатрешни и споделени симболички светови — верувања, приказни и ритуали што поврзувале заедница. Симболичкиот ум, еднаш запален, никогаш повеќе нема да се изгасне.",
      "Уметноста не се ограничила на пештерските ѕидови. Низ ледничка Европа и Азија, луѓето резеле мали скулптури — славните „фигурки на Венера“, жени со големина на дланка обработени во камен, слонова коска и печена глина. Венера од Вилендорф, изрежана пред околу 25.000 години, и десетици други делат впечатлива семејна сличност низ илјадници километри, наговестувајќи споделени верувања што го опфаќале целиот континент. Дали претставувале плодност, предци, божици или нешто сосема друго, тие покажуваат народ што вложувал длабоко значење во човечката форма.\n\nУште постар е Човекот-Лав од Холенштајн-Штадел, фигура стара 40.000 години на исправен човек со глава на лав, изрежана од мамутска слонова коска. Тоа е можеби најважниот предмет во праисторијата, зашто прикажува нешто што не постои во природата — суштество полу-човек, полу-ѕвер. За да го изреже, неговиот творец морал да замисли суштество никогаш видено, а потоа да го донесе на светот. Тоа е суштината на човечката имагинација: моќта да се замисли она што не е, било тоа човек-лав, бог, нација или број.",
      "Ледничкиот ум пеел исто колку што сликал. Од истите пештери и логори потекнуваат најстарите музички инструменти во светот: флејти изрежани од птичја коска и мамутска слонова коска, некои постари од 40.000 години, со внимателно продупчени дупки за прсти наштимани да произведат скала. Реплика на една таква флејта свири препознатливи мелодии. Каде што имало флејти сигурно имало гласови, тапани и танц, иако само коската опстојува.\n\nМузиката, како и сликарството, не служи на ниту една очигледна цел за преживување — не можеш да изедеш песна — а сепак секоја човечка култура на Земјата ја создава, што ни кажува дека поривот е древен и универзален. Околу ледничкиот оган, музиката би ги поврзала луѓето во споделен ритам и емоција, би носела приказни и меморија низ генерации пред писмото, и би ги обележувала големите мигови на животот и смртта. Откритието на овие флејти нè потсетува дека нашите предци не само што ја преживеале глацијацијата; ја исполниле со значење, слика и песна.",
      "Расцутот на уметноста, украсувањето и музиката во Горниот Палеолит означува една од вистинските пресвртници во човечката приказна — веројатно исто толку важна колку припитомувањето на огнот или изумот на земјоделството. Тоа е археолошкиот потпис на „бихејвиоралната модерност“: мигот кога можеме да бидеме сигурни дека нашите предци мислеле, чувствувале, верувале и замислувале како нас. Сè што ја прави човечката култура особена — религијата, раскажувањето, уметноста, науката, способноста да се споделуваат идеи што постојат само во умот — произлегува од симболичката способност што ја откриваат овие пештерски ѕидови.\n\nНарод што може да наслика коњ може и да замисли дух, закон, план за следногодишниот лов или бог. Истата моќ што ги наполнила пештерите со ѕверови ќе го наполни, со време, светот со митови, математика и машини. Кога стоиме во музеј пред изрежана фигура стара 30.000 години и чувствуваме искра на препознавање, ние се среќаваме со сопствениот ум преку огромен јаз на времето — и откриваме дека суштинскиот човек, оној што замислува, веќе бил целосно присутен долго пред да се изгради првиот град.",
    ],
    de: [
      "Tief in Höhlen über das ganze eiszeitliche Europa, in Kammern, die nie Tageslicht sehen, hinterließen unsere Vorfahren einen Schock der Schönheit. 1994 zwängten sich Forscher in die Chauvet-Höhle in Südfrankreich und fanden ihre Lampen Wände erhellen, lebendig von Löwen, Nashörnern, Bären und Pferden — mit solcher Sicherheit und Anmut gemalt, dass manche Betrachter sich weigerten zu glauben, sie seien 36.000 Jahre alt. Sie waren es, und seither ist noch ältere figürliche Kunst in Indonesien aufgetaucht, wo die Malerei eines Warzenschweins auf mindestens 45.500 Jahre datiert.\n\nDiese Bilder waren keine müßigen Kritzeleien. Sie liegen tief unter der Erde, erreicht durch lange Kriechgänge in der Dunkelheit, gemalt beim Flackern von Talglampen. Die Künstler verstanden Perspektive, Bewegung und die Wölbung eines lebenden Körpers; sie nutzten die natürlichen Vorwölbungen des Felsens, um ihren Tieren dreidimensionale Form zu geben. Vor ihnen zu stehen heißt, die Gegenwart eines Geistes zu spüren, der genau wie unserer ist — eines Geistes, der sah, sich vorstellte und das Vorgestellte sichtbar machen musste. Hier, zehntausende Jahre vor der Schrift, ist die unverkennbare Morgenröte der Kunst.",
      "Wozu dienten die Höhlenmalereien? Wir werden es nie ganz wissen, doch die Bilder selbst bieten Hinweise. Die Tiere sind überwältigend die großen Bestien der Eiszeit — Pferde, Bisons, Auerochsen, Mammuts, Löwen — während die Pflanzen und kleinen Geschöpfe, die einen Großteil der täglichen Nahrung ausmachten, fast fehlen. Das deutet darauf, dass die Höhlen keine Bilderbücher der Speisekarte waren, sondern etwas mit Bedeutung Aufgeladenes: vielleicht Stätten des Rituals, der Initiation, des Jagdzaubers oder der Berührung mit einer hinter den Tieren geahnten Geisterwelt.\n\nGespenstische Handabdrücke bevölkern viele Höhlen — Schablonen, gemacht, indem man Pigment um eine an die Wand gepresste Hand blies, manche von kleinen Kinderhänden, viele mit scheinbar fehlenden Fingern. Über tausende Kilometer und tausende Jahre kehrten Menschen an diese tiefen Orte zurück, um ihre Male im Dunkeln zu setzen. Was auch immer die Malereien bedeuteten, sie beweisen, dass eiszeitliche Menschen reiche innere und geteilte symbolische Welten besaßen — Glaubensvorstellungen, Geschichten und Rituale, die eine Gemeinschaft banden. Der symbolische Geist, einmal entzündet, würde nie wieder erlöschen.",
      "Kunst beschränkte sich nicht auf Höhlenwände. Über das eiszeitliche Europa und Asien schnitzten Menschen kleine Skulpturen — die berühmten „Venusfiguren“, handtellergroße Frauen aus Stein, Elfenbein und gebranntem Ton. Die Venus von Willendorf, vor etwa 25.000 Jahren geschnitzt, und Dutzende andere teilen eine auffallende Familienähnlichkeit über tausende Kilometer, was auf geteilte Glaubensvorstellungen über den ganzen Kontinent hindeutet. Ob sie Fruchtbarkeit, Ahnen, Göttinnen oder etwas ganz anderes darstellten, sie zeigen ein Volk, das tiefe Bedeutung in die menschliche Gestalt legte.\n\nNoch älter ist der Löwenmensch von Hohlenstein-Stadel, eine 40.000 Jahre alte Figur eines stehenden löwenköpfigen Menschen, aus Mammutelfenbein geschnitzt. Er ist vielleicht das wichtigste Objekt der Urgeschichte, denn er stellt etwas dar, das es in der Natur nicht gibt — ein Wesen halb Mensch, halb Bestie. Um ihn zu schnitzen, musste sein Schöpfer ein nie gesehenes Geschöpf sich vorstellen und es dann in die Welt bringen. Das ist das Wesen der menschlichen Vorstellungskraft: die Macht, sich das zu denken, was nicht ist — ob ein Löwenmensch, ein Gott, eine Nation oder eine Zahl.",
      "Der eiszeitliche Geist sang ebenso, wie er malte. Aus denselben Höhlen und Lagern stammen die ältesten Musikinstrumente der Welt: Flöten aus Vogelknochen und Mammutelfenbein, manche über 40.000 Jahre alt, mit sorgfältig gebohrten Fingerlöchern, auf eine Tonleiter gestimmt. Ein Nachbau einer solchen Flöte spielt erkennbare Melodien. Wo es Flöten gab, gab es gewiss Stimmen, Trommeln und Tanz, auch wenn nur der Knochen überdauert.\n\nMusik dient, wie die Malerei, keinem offensichtlichen Überlebenszweck — man kann kein Lied essen — und doch macht sie jede menschliche Kultur der Erde, was uns sagt, dass der Antrieb uralt und universell ist. Um das eiszeitliche Feuer hätte Musik Menschen in geteiltem Rhythmus und Gefühl gebunden, Geschichten und Gedächtnis über Generationen vor der Schrift getragen und die großen Augenblicke von Leben und Tod markiert. Die Entdeckung dieser Flöten erinnert daran, dass unsere Vorfahren die Eiszeit nicht bloß überlebten; sie füllten sie mit Bedeutung, Bild und Gesang.",
      "Die Blüte von Kunst, Schmuck und Musik im Jungpaläolithikum markiert einen der wahren Wendepunkte der Menschheitsgeschichte — wohl ebenso bedeutend wie die Zähmung des Feuers oder die Erfindung der Landwirtschaft. Es ist die archäologische Signatur der „Verhaltensmoderne“: der Augenblick, in dem wir gewiss sein können, dass unsere Vorfahren dachten, fühlten, glaubten und sich vorstellten wie wir. Alles, was die menschliche Kultur eigentümlich macht — Religion, Erzählung, Kunst, Wissenschaft, die Fähigkeit, Ideen zu teilen, die nur im Geist existieren — entspringt der symbolischen Fähigkeit, die diese Höhlenwände offenbaren.\n\nEin Volk, das ein Pferd malen kann, kann sich auch einen Geist, ein Gesetz, einen Plan für die Jagd des nächsten Jahres oder einen Gott vorstellen. Dieselbe Macht, die die Höhlen mit Bestien füllte, würde mit der Zeit die Welt mit Mythen, Mathematik und Maschinen füllen. Wenn wir in einem Museum vor einer 30.000 Jahre alten geschnitzten Figur stehen und einen Funken des Wiedererkennens spüren, begegnen wir unserem eigenen Geist über eine ungeheure Kluft der Zeit hinweg — und entdecken, dass der wesentliche Mensch, der Vorstellende, schon lange vor dem Bau der ersten Stadt vollständig vorhanden war.",
    ],
    fr: [
      "Au fond de grottes partout dans l'Europe glaciaire, dans des salles qui ne voient jamais la lumière du jour, nos ancêtres laissèrent un choc de beauté. En 1994, des explorateurs se glissèrent dans la grotte Chauvet, dans le sud de la France, et virent leurs lampes éclairer des parois vivantes de lions, de rhinocéros, d'ours et de chevaux — peints avec une telle assurance et une telle grâce que certains observateurs refusèrent de croire qu'ils avaient 36 000 ans. Ils les avaient, et un art figuratif plus ancien encore est depuis apparu en Indonésie, où une peinture de cochon verruqueux date d'au moins 45 500 ans.\n\nCes images n'étaient pas des gribouillis oisifs. Elles gisent au fond de la terre, atteintes par de longues reptations dans l'obscurité, peintes à la lueur vacillante de lampes à graisse. Les artistes comprenaient la perspective, le mouvement et le gonflement d'un corps vivant ; ils utilisaient les renflements naturels de la roche pour donner à leurs animaux une forme tridimensionnelle. Se tenir devant elles, c'est sentir la présence d'un esprit exactement semblable au nôtre — un esprit qui voyait, imaginait et avait besoin de rendre visible ce qu'il imaginait. Ici, des dizaines de milliers d'années avant l'écriture, se trouve l'aube indubitable de l'art.",
      "À quoi servaient les peintures rupestres ? Nous ne le saurons jamais tout à fait, mais les images elles-mêmes offrent des indices. Les animaux sont massivement les grandes bêtes de la glaciation — chevaux, bisons, aurochs, mammouths, lions — tandis que les plantes et les petites créatures qui composaient une grande part du régime quotidien sont presque absentes. Cela suggère que les grottes n'étaient pas des livres d'images du menu, mais quelque chose de chargé de sens : peut-être des lieux de rituel, d'initiation, de magie de chasse ou de contact avec un monde spirituel pressenti derrière les animaux.\n\nDes mains fantomatiques hantent bien des grottes — des pochoirs faits en soufflant du pigment autour d'une main pressée contre la paroi, certaines de petits enfants, beaucoup aux doigts apparemment manquants. Sur des milliers de kilomètres et des milliers d'années, les gens revenaient à ces lieux profonds y laisser leurs marques dans le noir. Quel qu'ait été le sens des peintures, elles prouvent que les humains de la glaciation possédaient de riches mondes symboliques, intérieurs et partagés — croyances, récits et rituels qui liaient une communauté. L'esprit symbolique, une fois allumé, ne s'éteindrait plus jamais.",
      "L'art ne se limita pas aux parois des grottes. À travers l'Europe et l'Asie glaciaires, les gens sculptèrent de petites statuettes — les célèbres « figurines de Vénus », des femmes de la taille de la paume travaillées dans la pierre, l'ivoire et l'argile cuite. La Vénus de Willendorf, sculptée il y a quelque 25 000 ans, et des dizaines d'autres partagent un frappant air de famille sur des milliers de kilomètres, laissant entrevoir des croyances partagées à l'échelle du continent. Qu'elles aient représenté la fécondité, les ancêtres, des déesses ou tout autre chose, elles montrent un peuple investissant un sens profond dans la forme humaine.\n\nPlus ancien encore est l'Homme-Lion de Hohlenstein-Stadel, une figure de 40 000 ans d'un humain à tête de lion, sculptée dans l'ivoire de mammouth. C'est peut-être l'objet le plus important de la préhistoire, car il représente quelque chose qui n'existe pas dans la nature — un être mi-humain, mi-bête. Pour le sculpter, son créateur dut imaginer une créature jamais vue, puis la faire venir au monde. C'est là l'essence de l'imagination humaine : le pouvoir de concevoir ce qui n'est pas, que ce soit un homme-lion, un dieu, une nation ou un nombre.",
      "L'esprit glaciaire chantait autant qu'il peignait. Des mêmes grottes et campements proviennent les plus anciens instruments de musique du monde : des flûtes taillées dans l'os d'oiseau et l'ivoire de mammouth, certaines de plus de 40 000 ans, aux trous de doigt soigneusement percés et accordés pour produire une gamme. Une réplique d'une telle flûte joue des mélodies reconnaissables. Là où il y avait des flûtes, il y avait sûrement des voix, des tambours et de la danse, même si seul l'os subsiste.\n\nLa musique, comme la peinture, ne sert aucun but de survie évident — on ne mange pas une chanson — et pourtant toute culture humaine de la Terre en fait, ce qui nous dit que l'impulsion est ancienne et universelle. Autour du feu glaciaire, la musique aurait lié les gens dans un rythme et une émotion partagés, porté récits et mémoire à travers les générations avant l'écriture, et marqué les grands moments de la vie et de la mort. La découverte de ces flûtes rappelle que nos ancêtres ne se contentèrent pas de survivre à la glaciation ; ils la remplirent de sens, d'image et de chant.",
      "L'épanouissement de l'art, de la parure et de la musique au Paléolithique supérieur marque l'un des véritables tournants de l'histoire humaine — sans doute aussi important que la maîtrise du feu ou l'invention de l'agriculture. C'est la signature archéologique de la « modernité comportementale » : le moment où nous pouvons être certains que nos ancêtres pensaient, ressentaient, croyaient et imaginaient comme nous. Tout ce qui rend la culture humaine distinctive — la religion, le récit, l'art, la science, la capacité de partager des idées qui n'existent que dans l'esprit — découle de la capacité symbolique que révèlent ces parois de grotte.\n\nUn peuple capable de peindre un cheval peut aussi imaginer un esprit, une loi, un plan pour la chasse de l'année prochaine ou un dieu. Le même pouvoir qui emplit les grottes de bêtes emplirait, avec le temps, le monde de mythes, de mathématiques et de machines. Quand nous nous tenons dans un musée devant une figure sculptée de 30 000 ans et ressentons un éclair de reconnaissance, nous rencontrons notre propre esprit par-delà un gouffre immense de temps — et découvrons que l'être humain essentiel, celui qui imagine, était déjà pleinement présent bien avant que la première ville ne fût bâtie.",
    ],
  },
  'prehistoric-07': {
    es: [
      "Durante la mayor parte de los últimos dos millones y medio de años — la época geológica llamada Pleistoceno — la Tierra estuvo presa de glaciaciones recurrentes. Vastos mantos de hielo, de kilómetros de espesor, avanzaban y retrocedían a lo largo de decenas de miles de años, impulsados por sutiles bamboleos de reloj en la órbita y la inclinación de la Tierra. En el punto más frío, hace unos 20.000 años, los glaciares sepultaron Escandinavia, gran parte de Britania y casi todo Canadá, y el mundo estaba, de media, unos cinco o seis grados más frío que hoy.\n\nToda la evolución humana se desplegó contra este telón de fondo pulsante de hielo. Tanta agua quedó atrapada en los glaciares que el nivel del mar global descendió más de cien metros, dejando al descubierto puentes de tierra y vastas llanuras costeras hoy ahogadas bajo las olas. Britania estaba unida a Europa; Siberia a Alaska; las islas del Sudeste Asiático se fundían en una sola masa de tierra. Para entender dónde y cómo vivían y se movían los pueblos antiguos, primero debemos imaginar un mapa del mundo profundamente distinto del nuestro.",
      "Por todo el norte helado se extendía un ecosistema desaparecido sin igual exacto hoy: la estepa del mamut, una vasta pradera fría y seca que iba de España a través de Eurasia hasta el Yukón. Lejos de ser un yermo estéril, rebosaba de vida. Manadas de mamuts lanudos, con sus pelajes hirsutos y orejas pequeñas contra el frío, pastaban junto a rinocerontes lanudos, caballos salvajes, bisontes, renos y ciervos gigantes, cazados a su vez por leones de las cavernas, hienas y lobos.\n\nEsta \"megafauna\" — las grandes bestias de la glaciación — moldeó profundamente la vida humana. Un solo mamut era una montaña de carne, grasa, piel y marfil. En la estepa sin árboles de Ucrania y Rusia, la gente construía cabañas extraordinarias armadas por entero con huesos y colmillos de mamut, techadas con pieles — algunas usando los huesos de docenas de animales. El mamut era para estos cazadores del norte lo que el bisonte sería después para los pueblos de las Grandes Llanuras: alimento, cobijo, herramientas y el centro mismo de su mundo.",
      "Sobrevivir a la glaciación exigía un ingenio del más alto orden, y la arqueología muestra cuán ingeniosa era esta gente. Los cazadores-recolectores glaciales vestían ropa entallada y en capas, cosida con agujas de hueso — parkas y pantalones tan sofisticados como cualquier atuendo ártico histórico. Construían refugios sólidos, controlaban el fuego en cuevas profundas y almacenaban comida contra los meses de escasez, guardando carne en el congelador natural del permafrost del suelo helado.\n\nEran también expertos lectores de la tierra y sus animales, ajustando sus movimientos a las grandes migraciones de renos y caballos. La supervivencia era un esfuerzo grupal que ligaba bandas en redes más amplias: piedra, conchas y ámbar viajaban cientos de kilómetros entre comunidades distantes, portando no solo bienes sino información y alianzas. Lejos de aferrarse al borde de la extinción, los pueblos glaciales florecieron en algunos de los entornos más duros que el planeta haya ofrecido jamás — un triunfo de la cultura y la cooperación sobre el clima crudo.",
      "Al terminar la última glaciación, entre hace unos 15.000 y 10.000 años, las grandes bestias del Pleistoceno se extinguieron en gran parte del mundo. El mamut lanudo, el rinoceronte lanudo, el perezoso terrestre gigante, el tigre dientes de sable y docenas de otras especies de megafauna se esfumaron — una ola de extinción que despojó al planeta de sus mayores animales terrestres. El debate sobre qué los mató es uno de los más animados de la prehistoria.\n\nDos sospechosos están acusados, y ambos actuaron probablemente. El clima se sacudió drásticamente al final de la glaciación, calentándose con rapidez y transformando las estepas frías y secas de las que dependía la megafauna en bosques y humedales. Al mismo tiempo, hábiles cazadores humanos armados con lanzas y arcos se extendían por tierras nuevas. Llamativamente, las extinciones tienden a seguir a la llegada de los humanos — peores en Australia y las Américas, donde los animales gigantes se toparon con la gente por primera vez, y más leves en África, donde habían coevolucionado con homínidos durante millones de años. El veredicto más probable es una combinación letal: un clima cambiante que empujó a los gigantes al borde, y la caza humana que los empujó al vacío.",
      "El fin de la glaciación, hace unos 11.700 años, abrió un nuevo capítulo en la historia de la Tierra y en la nuestra: el Holoceno, el intervalo cálido y estable en el que aún vivimos hoy. Al fundirse los glaciares, el nivel del mar subió hasta alturas más o menos modernas, ahogando los viejos puentes de tierra y llanuras costeras, y separando Britania de Europa y Asia de América. Los bosques se extendieron al norte sobre lo que había sido tundra abierta, y toda la distribución de plantas y animales se rebarajó.\n\nEste calentamiento no fue un zumbido de fondo suave, sino el escenario mismo sobre el que se desplegaría la siguiente gran transformación humana. En el clima recién cálido, húmedo y estable, las gramíneas silvestres crecían espesas en unas pocas regiones favorecidas — y entre los pueblos que las recolectaban, algunos pronto darían el paso fatídico de plantar las semillas ellos mismos. La glaciación había forjado una especie de cazadores y recolectores supremamente adaptables, extendida por toda la Tierra. El deshielo que la puso fin preparó el escenario para que inventaran una forma de vivir por completo nueva: la agricultura.",
    ],
    ru: [
      "Большую часть последних двух с половиной миллионов лет — геологическую эпоху, называемую плейстоценом, — Землю сжимали повторяющиеся ледниковые периоды. Обширные ледяные щиты в километры толщиной наступали и отступали на протяжении десятков тысяч лет, движимые тонкими, часовыми покачиваниями орбиты и наклона Земли. В самый холодный момент, около 20 000 лет назад, ледники погребли Скандинавию, большую часть Британии и почти всю Канаду, а мир был в среднем на пять-шесть градусов холоднее нынешнего.\n\nВся человеческая эволюция развернулась на этом пульсирующем ледяном фоне. Столько воды было заперто в ледниках, что глобальный уровень моря упал более чем на сто метров, обнажив перешейки и обширные прибрежные равнины, ныне утопленные под волнами. Британия соединялась с Европой; Сибирь — с Аляской; острова Юго-Восточной Азии сливались в единый массив суши. Чтобы понять, где и как жили и передвигались древние народы, надо сперва представить карту мира, глубоко отличную от нашей.",
      "По всему студёному северу простиралась исчезнувшая экосистема, не имеющая точного подобия сегодня: мамонтовая степь, обширная холодная сухая травянистая равнина, тянувшаяся от Испании через Евразию до Юкона. Вовсе не бесплодная пустошь, она кишела жизнью. Стада шерстистых мамонтов с косматой шерстью и малыми ушами против холода паслись рядом с шерстистыми носорогами, дикими лошадьми, бизонами, северными оленями и гигантскими оленями, на которых в свою очередь охотились пещерные львы, гиены и волки.\n\nЭта «мегафауна» — великие звери ледникового периода — глубоко формировала человеческую жизнь. Один мамонт был горой мяса, жира, шкуры и бивня. В безлесной степи Украины и России люди строили удивительные хижины, целиком собранные из костей и бивней мамонта, крытые шкурами, — иные из костей десятков животных. Мамонт был для этих северных охотников тем, чем позднее станет бизон для народов Великих равнин: пищей, кровом, орудиями и самым средоточием их мира.",
      "Пережить ледниковый период требовало изобретательности высшего порядка, и археология показывает, сколь находчивы были эти люди. Ледниковые охотники-собиратели носили подогнанную, многослойную одежду, сшитую костяными иглами, — парки и штаны, столь же изощрённые, как любое историческое арктическое облачение. Они строили прочные жилища, владели огнём в глубоких пещерах и запасали пищу на скудные месяцы, пряча мясо в природном морозильнике вечной мерзлоты промёрзшей земли.\n\nОни были также искусными чтецами земли и её животных, приноравливая свои перемещения к великим миграциям северного оленя и лошади. Выживание было делом группы, связывавшим общины в более широкие сети: камень, раковины и янтарь путешествовали на сотни километров меж далёкими общинами, неся не только товары, но сведения и союз. Отнюдь не цепляясь за край вымирания, ледниковые народы процветали в одних из самых суровых сред, какие только предлагала планета, — торжество культуры и сотрудничества над лютым климатом.",
      "Когда последний ледниковый период кончался, между примерно 15 000 и 10 000 лет назад, великие звери плейстоцена вымерли на большей части мира. Шерстистый мамонт, шерстистый носорог, гигантский наземный ленивец, саблезубая кошка и десятки других видов мегафауны исчезли — волна вымирания, лишившая планету её крупнейших наземных животных. Спор о том, что их убило, — один из самых живых в доистории.\n\nПодозреваемых двое, и оба, вероятно, действовали. Климат резко качнулся в конце ледникового периода, стремительно теплея и превращая холодные сухие степи, от которых зависела мегафауна, в леса и болота. В тот же самый час умелые охотники-люди, вооружённые копьями и луками, расселялись по новым землям. Примечательно, что вымирания склонны следовать за приходом людей — тяжелее всего в Австралии и Америках, где гигантские животные впервые встретили людей, и мягче всего в Африке, где они сомиллионнолетно эволюционировали с гомининами. Наиболее вероятный вердикт — смертельное сочетание: меняющийся климат, толкнувший гигантов на край, и человеческая охота, столкнувшая их вниз.",
      "Конец ледникового периода, около 11 700 лет назад, открыл новую главу в истории Земли и нашей собственной: голоцен, тёплый устойчивый промежуток, в котором мы живём и поныне. Когда ледники таяли, уровень моря поднялся до примерно современных высот, затопив старые перешейки и прибрежные равнины и отсекши Британию от Европы, а Азию от Америки. Леса распространились на север над тем, что было открытой тундрой, и всё распределение растений и животных перетасовалось.\n\nЭто потепление было не тихим фоновым гулом, а самой сценой, на которой развернётся следующее великое человеческое преображение. В новом тёплом, влажном и устойчивом климате дикие злаки росли густо в немногих благодатных областях — и среди народов, что их собирали, некоторые вскоре сделают роковой шаг, сами посеяв семена. Ледниковый период выковал вид в высшей степени приспособляемых охотников и собирателей, расселённых по всей Земле. Оттепель, что его завершила, подготовила сцену для того, чтобы они изобрели совершенно новый способ жизни: земледелие.",
    ],
    mk: [
      "Во најголемиот дел од последните два и пол милиони години — геолошката епоха наречена плеистоцен — Земјата била зафатена од повторливи ледени доба. Огромни ледени плочи, дебели по неколку километри, напредувале и отстапувале низ десетици илјади години, поттикнати од суптилни, часовникарски нишања во орбитата и наклонот на Земјата. Во најстудениот момент, пред околу 20.000 години, глечерите ги погребале Скандинавија, голем дел од Британија и речиси цела Канада, а светот бил, во просек, некои пет или шест степени постуден од денес.\n\nЦелата човечка еволуција се одвивала врз оваа пулсирачка ледена позадина. Толку многу вода била заклучена во глечерите што глобалното морско ниво паднало повеќе од сто метри, откривајќи копнени мостови и пространи крајбрежни рамнини денес удавени под брановите. Британија била споена со Европа; Сибир со Алјаска; островите на Југоисточна Азија се стопувале во една единствена копнена маса. За да разбереме каде и како живееле и се движеле древните народи, мораме прво да замислиме мапа на светот длабоко различна од нашата.",
      "Низ смрзнатиот север се протегал исчезнат екосистем без точен пандан денес: мамутската степа, пространа студена сува тревна рамнина што одела од Шпанија низ Евроазија до Јукон. Далеку од да биде неплодна пустелија, таа врела од живот. Стада волнести мамути, со своите рунтави крзна и мали уши против студот, паселе заедно со волнести носорози, диви коњи, бизони, ирваси и џиновски елени, ловени пак од пештерски лавови, хиени и волци.\n\nОваа „мегафауна“ — големите ѕверови на глацијацијата — длабоко го обликувала човечкиот живот. Еден единствен мамут бил планина од месо, маст, кожа и слонова коска. Во безшумската степа на Украина и Русија, луѓето граделе извонредни колиби составени целосно од мамутски коски и колкови, покриени со кожи — некои користејќи ги коските на десетици животни. Мамутот бил за овие северни ловци она што бизонот подоцна ќе биде за народите на Големите Рамнини: храна, засолниште, алат и самиот центар на нивниот свет.",
      "Преживувањето на глацијацијата барало досетливост од највисок ред, и археологијата покажува колку снаодливи биле овие луѓе. Ледничките ловци-собирачи носеле кроена, слоевита облека, шиена со коскени игли — парки и панталони софистицирани колку и која било историска арктичка облека. Граделе цврсти засолништа, владееле со огнот во длабоки пештери и складирале храна за посните месеци, чувајќи месо во природниот замрзнувач на вечниот мраз на смрзнатата земја.\n\nБиле и вешти читачи на земјата и нејзините животни, приспособувајќи ги своите движења кон големите преселби на ирвасите и коњите. Преживувањето било групен напор што поврзувал групи во пошироки мрежи: камен, школки и килибар патувале стотици километри меѓу далечни заедници, носејќи не само добра туку и информации и сојузи. Далеку од да се држат на работ на изумирањето, ледничките народи цветале во некои од најсуровите средини што планетата некогаш ги понудила — триумф на културата и соработката над суровата клима.",
      "Кога завршувала последната глацијација, меѓу пред околу 15.000 и 10.000 години, големите ѕверови на плеистоценот изумреле во голем дел од светот. Волнестиот мамут, волнестиот носорог, џиновскиот копнен мрзливец, сабљозабата мачка и десетици други видови мегафауна исчезнале — бран на изумирање што ја лишил планетата од нејзините најголеми копнени животни. Дебатата за тоа што ги убило е една од најживите во праисторијата.\n\nДвајца осомничени се обвинети, и обајцата веројатно дејствувале. Климата драстично се залула на крајот на глацијацијата, брзо затоплувајќи се и претворајќи ги студените суви степи од кои зависела мегафауната во шуми и мочуришта. Во истиот момент, вешти човечки ловци вооружени со копја и лакови се ширеле во нови земји. Впечатливо, изумирањата тежнеат да го следат доаѓањето на луѓето — најлоши во Австралија и Америките, каде што џиновските животни ги сретнале луѓето за првпат, и најблаги во Африка, каде што коеволуирале со хоминини милиони години. Најверојатната пресуда е смртоносна комбинација: клима што се менува и што ги турнала џиновите на работ, и човечки лов што ги турнал преку него.",
      "Крајот на глацијацијата, пред околу 11.700 години, отворил ново поглавје во приказната на Земјата и нашата: холоценот, топлиот, стабилен интервал во кој сè уште живееме денес. Како што глечерите се топеле, морското ниво се качило до отприлика модерни височини, удавувајќи ги старите копнени мостови и крајбрежни рамнини, и одвојувајќи ја Британија од Европа и Азија од Америка. Шумите се рашириле на север над она што било отворена тундра, и целата распределба на растенијата и животните се преместила.\n\nОва затоплување не било благо позадинско брмчење, туку самата сцена врз која ќе се одвиела следната голема човечка преобразба. Во новонастанатата топла, влажна и стабилна клима, дивите треви растеле густо во неколку поволни региони — и меѓу народите што ги собирале, некои наскоро ќе го направеле судбоносниот чекор сами да ги посеат семињата. Глацијацијата исковала вид на врвно приспособливи ловци и собирачи, раширени по целата Земја. Топењето што ѝ ставило крај ја подготвило сцената за тие да измислат сосема нов начин на живеење: земјоделството.",
    ],
    de: [
      "Über den größten Teil der letzten zweieinhalb Millionen Jahre — die geologische Epoche des Pleistozäns — war die Erde von wiederkehrenden Eiszeiten erfasst. Riesige, kilometerdicke Eisschilde rückten über zehntausende Jahre vor und zurück, angetrieben von subtilen, uhrwerkartigen Schwankungen der Erdbahn und -neigung. Auf dem kältesten Punkt, vor etwa 20.000 Jahren, begruben Gletscher Skandinavien, weite Teile Britanniens und fast ganz Kanada, und die Welt war im Schnitt um etwa fünf oder sechs Grad kälter als heute.\n\nDie gesamte menschliche Evolution entfaltete sich vor diesem pulsierenden Hintergrund aus Eis. So viel Wasser war in den Gletschern gebunden, dass der globale Meeresspiegel um mehr als hundert Meter fiel und Landbrücken sowie weite Küstenebenen freilegte, die heute unter den Wellen ertrunken sind. Britannien war mit Europa verbunden; Sibirien mit Alaska; die Inseln Südostasiens verschmolzen zu einer einzigen Landmasse. Um zu verstehen, wo und wie alte Völker lebten und sich bewegten, müssen wir uns zuerst eine Weltkarte vorstellen, die sich zutiefst von der unseren unterscheidet.",
      "Über den gefrorenen Norden erstreckte sich ein verschwundenes Ökosystem ohne genaue Entsprechung heute: die Mammutsteppe, eine weite, kalte, trockene Grassteppe, die von Spanien über Eurasien bis zum Yukon reichte. Weit davon entfernt, eine öde Wüste zu sein, wimmelte sie von Leben. Herden von Wollmammuts, mit zottigem Fell und kleinen Ohren gegen die Kälte, grasten neben Wollnashörnern, Wildpferden, Bisons, Rentieren und Riesenhirschen, ihrerseits gejagt von Höhlenlöwen, Hyänen und Wölfen.\n\nDiese „Megafauna“ — die großen Bestien der Eiszeit — prägte das menschliche Leben zutiefst. Ein einziges Mammut war ein Berg aus Fleisch, Fett, Haut und Elfenbein. In der baumlosen Steppe der Ukraine und Russlands bauten Menschen außergewöhnliche Hütten, ganz aus Mammutknochen und -stoßzähnen gefügt, mit Häuten gedeckt — manche aus den Knochen Dutzender Tiere. Das Mammut war diesen nördlichen Jägern, was der Bison später den Völkern der Great Plains sein würde: Nahrung, Obdach, Werkzeug und das eigentliche Zentrum ihrer Welt.",
      "Die Eiszeit zu überleben verlangte Einfallsreichtum höchster Ordnung, und die Archäologie zeigt, wie findig diese Menschen waren. Eiszeitliche Jäger und Sammler trugen maßgeschneiderte, geschichtete Kleidung, mit Knochennadeln genäht — Parkas und Hosen, so ausgefeilt wie jede historische arktische Tracht. Sie bauten feste Behausungen, beherrschten das Feuer in tiefen Höhlen und lagerten Nahrung gegen die mageren Monate ein, indem sie Fleisch im natürlichen Gefrierfach des Permafrosts der gefrorenen Erde vergruben.\n\nSie waren auch versierte Leser des Landes und seiner Tiere und stimmten ihre Bewegungen auf die großen Wanderungen von Rentier und Pferd ab. Überleben war eine Gruppenanstrengung, die Banden zu weiteren Netzen band: Stein, Muscheln und Bernstein wanderten Hunderte Kilometer zwischen fernen Gemeinschaften und trugen nicht nur Güter, sondern Information und Bündnis. Weit davon entfernt, am Rand des Aussterbens zu hängen, gediehen eiszeitliche Völker in einigen der härtesten Umwelten, die der Planet je bot — ein Triumph von Kultur und Zusammenarbeit über das rohe Klima.",
      "Als die letzte Eiszeit endete, zwischen etwa 15.000 und 10.000 Jahren, starben die großen Bestien des Pleistozäns in weiten Teilen der Welt aus. Das Wollmammut, das Wollnashorn, das Riesenfaultier, die Säbelzahnkatze und Dutzende anderer Megafauna-Arten verschwanden — eine Aussterbewelle, die den Planeten seiner größten Landtiere beraubte. Die Debatte, was sie tötete, ist eine der lebhaftesten der Urgeschichte.\n\nZwei Verdächtige stehen angeklagt, und beide waren wahrscheinlich am Werk. Das Klima taumelte am Ende der Eiszeit dramatisch, erwärmte sich rasch und verwandelte die kalten, trockenen Steppen, von denen die Megafauna abhing, in Wälder und Feuchtgebiete. Zur selben Zeit breiteten sich geschickte menschliche Jäger, mit Speeren und Bögen bewaffnet, in neue Länder aus. Auffällig ist, dass die Aussterben der Ankunft der Menschen zu folgen pflegen — am schlimmsten in Australien und den Amerikas, wo die Riesentiere zum ersten Mal auf Menschen trafen, und am mildesten in Afrika, wo sie sich Millionen Jahre mit Homininen gemeinsam entwickelt hatten. Das wahrscheinlichste Urteil ist eine tödliche Kombination: ein wandelndes Klima, das die Riesen an den Rand drängte, und menschliche Jagd, die sie darüber hinausstieß.",
      "Das Ende der Eiszeit, vor etwa 11.700 Jahren, eröffnete ein neues Kapitel in der Geschichte der Erde und unserer eigenen: das Holozän, das warme, stabile Intervall, in dem wir noch heute leben. Als die Gletscher schmolzen, stieg der Meeresspiegel auf etwa moderne Höhen, ertränkte die alten Landbrücken und Küstenebenen und trennte Britannien von Europa und Asien von Amerika. Wälder breiteten sich nach Norden über die einstige offene Tundra aus, und die gesamte Verteilung von Pflanzen und Tieren wurde neu gemischt.\n\nDiese Erwärmung war kein sanftes Hintergrundsummen, sondern die Bühne selbst, auf der sich die nächste große menschliche Verwandlung entfalten würde. Im neu warmen, feuchten und stabilen Klima wuchsen wilde Gräser dicht in einigen wenigen begünstigten Regionen — und unter den Völkern, die sie sammelten, würden einige bald den folgenschweren Schritt tun, die Samen selbst zu pflanzen. Die Eiszeit hatte eine Art höchst anpassungsfähiger Jäger und Sammler geschmiedet, über die ganze Erde verteilt. Das Tauwetter, das sie beendete, bereitete die Bühne dafür, dass sie eine völlig neue Weise zu leben erfanden: die Landwirtschaft.",
    ],
    fr: [
      "Pendant l'essentiel des deux derniers millions et demi d'années — l'époque géologique dite Pléistocène — la Terre fut saisie de glaciations récurrentes. De vastes calottes de glace, épaisses de plusieurs kilomètres, avançaient et reculaient sur des dizaines de milliers d'années, mues par de subtiles oscillations d'horlogerie de l'orbite et de l'inclinaison de la Terre. Au point le plus froid, il y a environ 20 000 ans, les glaciers ensevelirent la Scandinavie, une grande partie de la Grande-Bretagne et presque tout le Canada, et le monde était en moyenne quelque cinq ou six degrés plus froid qu'aujourd'hui.\n\nToute l'évolution humaine se déploya sur cette toile de fond pulsante de glace. Tant d'eau était emprisonnée dans les glaciers que le niveau des mers baissa de plus de cent mètres, dégageant des ponts terrestres et de vastes plaines côtières aujourd'hui noyées sous les flots. La Grande-Bretagne était rattachée à l'Europe ; la Sibérie à l'Alaska ; les îles de l'Asie du Sud-Est se fondaient en une seule masse terrestre. Pour comprendre où et comment vivaient et se déplaçaient les peuples anciens, il faut d'abord imaginer une carte du monde profondément différente de la nôtre.",
      "À travers le Nord gelé s'étendait un écosystème disparu sans équivalent exact aujourd'hui : la steppe à mammouths, une vaste prairie froide et sèche allant de l'Espagne à travers l'Eurasie jusqu'au Yukon. Loin d'être un désert stérile, elle grouillait de vie. Des troupeaux de mammouths laineux, à la toison hirsute et aux petites oreilles contre le froid, paissaient aux côtés de rhinocéros laineux, de chevaux sauvages, de bisons, de rennes et de cerfs géants, chassés à leur tour par les lions des cavernes, les hyènes et les loups.\n\nCette « mégafaune » — les grandes bêtes de la glaciation — façonna profondément la vie humaine. Un seul mammouth était une montagne de viande, de graisse, de peau et d'ivoire. Dans la steppe sans arbres d'Ukraine et de Russie, les gens bâtissaient des huttes extraordinaires charpentées entièrement d'os et de défenses de mammouth, couvertes de peaux — certaines utilisant les os de dizaines d'animaux. Le mammouth était pour ces chasseurs du Nord ce que le bison serait plus tard pour les peuples des Grandes Plaines : nourriture, abri, outils et le centre même de leur monde.",
      "Survivre à la glaciation exigeait une ingéniosité du plus haut ordre, et l'archéologie montre à quel point ces gens étaient débrouillards. Les chasseurs-cueilleurs glaciaires portaient des vêtements ajustés et superposés, cousus à l'aiguille d'os — parkas et pantalons aussi sophistiqués que n'importe quelle tenue arctique historique. Ils bâtissaient des abris solides, maîtrisaient le feu dans des grottes profondes et stockaient la nourriture contre les mois maigres, mettant la viande en réserve dans le congélateur naturel du pergélisol du sol gelé.\n\nC'étaient aussi d'experts lecteurs de la terre et de ses animaux, réglant leurs déplacements sur les grandes migrations du renne et du cheval. La survie était un effort de groupe qui liait les bandes en réseaux plus vastes : pierre, coquillages et ambre voyageaient sur des centaines de kilomètres entre communautés lointaines, portant non seulement des biens mais de l'information et de l'alliance. Loin de s'accrocher au bord de l'extinction, les peuples glaciaires prospérèrent dans certains des environnements les plus rudes que la planète ait jamais offerts — un triomphe de la culture et de la coopération sur le climat brut.",
      "Comme la dernière glaciation prenait fin, entre environ 15 000 et 10 000 ans, les grandes bêtes du Pléistocène s'éteignirent dans une grande partie du monde. Le mammouth laineux, le rhinocéros laineux, le paresseux terrestre géant, le tigre à dents de sabre et des dizaines d'autres espèces de mégafaune s'évanouirent — une vague d'extinction qui dépouilla la planète de ses plus grands animaux terrestres. Le débat sur ce qui les tua est l'un des plus animés de la préhistoire.\n\nDeux suspects sont accusés, et tous deux furent probablement à l'œuvre. Le climat bascula brutalement à la fin de la glaciation, se réchauffant vite et transformant les steppes froides et sèches dont dépendait la mégafaune en forêts et zones humides. Au même moment, d'habiles chasseurs humains armés de lances et d'arcs se répandaient sur des terres nouvelles. De façon frappante, les extinctions tendent à suivre l'arrivée des humains — pires en Australie et dans les Amériques, où les animaux géants rencontrèrent les gens pour la première fois, et plus douces en Afrique, où ils avaient coévolué avec les hominidés pendant des millions d'années. Le verdict le plus probable est une combinaison mortelle : un climat changeant qui poussa les géants au bord, et la chasse humaine qui les fit basculer.",
      "La fin de la glaciation, il y a environ 11 700 ans, ouvrit un nouveau chapitre dans l'histoire de la Terre et la nôtre : l'Holocène, l'intervalle chaud et stable dans lequel nous vivons encore aujourd'hui. À mesure que les glaciers fondaient, le niveau des mers monta jusqu'à des hauteurs à peu près modernes, noyant les anciens ponts terrestres et plaines côtières, et séparant la Grande-Bretagne de l'Europe et l'Asie de l'Amérique. Les forêts s'étendirent vers le nord sur ce qui avait été une toundra ouverte, et toute la distribution des plantes et des animaux fut rebattue.\n\nCe réchauffement ne fut pas un doux bourdonnement de fond, mais la scène même sur laquelle se déploierait la prochaine grande transformation humaine. Dans le climat nouvellement chaud, humide et stable, les graminées sauvages poussaient dru dans quelques régions favorisées — et parmi les peuples qui les récoltaient, certains allaient bientôt franchir le pas fatidique de semer eux-mêmes les graines. La glaciation avait forgé une espèce de chasseurs et de cueilleurs suprêmement adaptables, répandue sur toute la Terre. Le dégel qui y mit fin prépara la scène pour qu'ils inventent une manière de vivre entièrement nouvelle : l'agriculture.",
    ],
  },
  'prehistoric-08': {
    es: [
      "Durante más de dos millones de años, todo ser humano en la Tierra vivió de cazar animales y recolectar plantas silvestres. Entonces, a partir de hace unos diez mil años, en un puñado de regiones, la gente empezó a plantar cultivos y a criar animales — y toda la trayectoria de la historia humana cambió para siempre. Este giro, la Revolución Neolítica, fue posiblemente la transformación más trascendental de la historia humana, el cimiento sobre el que se edificarían las ciudades, los estados, la escritura y todo lo que llamamos \"civilización\".\n\nLa palabra \"revolución\" puede engañar, pues el cambio se desplegó a lo largo de siglos, generación a generación, y nadie se propuso inventar la agricultura. Pero sus efectos fueron revolucionarios en el sentido más hondo. La agricultura permitió que un mismo trozo de tierra alimentara a mucha más gente que la recolección; ató a esa gente a un lugar; y produjo, por primera vez, los excedentes almacenables que un día sostendrían a reyes, sacerdotes, soldados y escribas. Todo lo posterior — para bien y para mal — creció de la siembra de las primeras semillas.",
      "El lugar de nacimiento más temprano y mejor documentado de la agricultura fue el Creciente Fértil — un arco de tierra de colinas bien regada que se curva desde el Levante a través del sudeste de Turquía hasta los montes Zagros de Irán. Esta región gozó de un raro don de la naturaleza: un conjunto de plantas y animales silvestres singularmente aptos para la domesticación. Trigo y cebada silvestres crecían espesos en las laderas; ovejas, cabras, vacas y cerdos salvajes rondaban cerca. En ninguna otra parte de la Tierra había tantas especies prometedoras concentradas en una región.\n\nHacia el 9500 a.C., los pueblos del Creciente Fértil habían empezado a plantar y cosechar trigo, cebada, lentejas y guisantes, y pronto a criar cabras y ovejas. A lo largo de generaciones, los cultivos cambiaron bajo el cuidado humano: los agricultores seleccionaron sin saberlo el trigo cuyas espigas no se desgranaban y dispersaban, sino que se mantenían unidas para una cosecha fácil, y a favor de semillas más grandes y animales dóciles. Esto es la domesticación — un lento remodelado mutuo en el que los humanos y sus cultivos y rebaños se transformaban unos a otros, ligando sus destinos para todo tiempo por venir.",
      "La agricultura no fue una sola invención que se difundió desde un lugar ingenioso; se descubrió de forma independiente, una y otra vez, por pueblos que jamás se conocieron. En China, los agricultores del Yangtsé cultivaban arroz y los del río Amarillo criaban mijo hacia el 8000 a.C. En las tierras altas de México, la gente domesticó el maíz a partir de una gramínea silvestre y escuálida llamada teosinte, junto con frijoles y calabazas. En los Andes cultivaron papas y quinua y criaron llamas; en Nueva Guinea cultivaron taro y plátanos; en África, sorgo, ñames y mijo.\n\nQue la agricultura surgiera por separado en casi cada continente habitado, en unos pocos miles de años tras el fin de la glaciación, es uno de los hechos más notables de toda la prehistoria. Nos dice que el giro no fue una casualidad de un solo genio, sino una respuesta, de nuestra especie supremamente adaptable, al nuevo clima cálido y estable del Holoceno. Dado un mundo asentado y las plantas silvestres adecuadas, el ingenio humano alcanzó la agricultura dondequiera que pudo — y cada uno de estos focos separados haría crecer sus propias civilizaciones distintas.",
      "La agricultura suele contarse como un triunfo sin más, pero la verdad es más inquietante y más interesante. Los estudios de esqueletos antiguos revelan que los primeros agricultores eran a menudo más bajos, más enfermizos y más desgastados que los cazadores-recolectores que los precedieron. Una dieta estrechada a uno o dos cultivos básicos traía carencias vitamínicas y dientes cariados; hacinar a personas y animales criaba enfermedades nuevas como el sarampión y la viruela; y la dependencia de unos pocos cultivos significaba que una cosecha fallida traía hambruna. Algunos estudiosos han llamado a la agricultura \"el peor error de la historia de la raza humana\".\n\nEntonces, ¿por qué venció la agricultura? Porque, aunque hizo más dura la vida de la persona media, permitió que muchísima más gente sobreviviera en la misma tierra. Una sociedad agrícola superaba con creces en número a una recolectora, y el número venció: los agricultores se expandieron, despejaron tierras y, o bien absorbieron, o bien desplazaron a sus vecinos cazadores-recolectores por casi todo el globo. El pacto neolítico cambió la salud y la libertad del individuo por el puro poder reproductivo del grupo. Fue, en cierto sentido, una trampa — pero una trampa de la que no había vuelta atrás, porque un mundo de miles de millones no puede alimentarse recolectando.",
      "Las consecuencias de la Revolución Neolítica irradian por toda la historia posterior. Las aldeas agrícolas asentadas produjeron, por primera vez, excedentes almacenados de grano — riqueza que podía contarse, gravarse, robarse y disputarse. El excedente de alimento liberó a algunas personas de producirlo, permitiendo a los primeros especialistas: alfareros, tejedores, sacerdotes, jefes y guerreros. El asentamiento permanente y la riqueza almacenada dieron origen a la propiedad, la herencia y a divisiones de rango más marcadas de lo que los recolectores móviles habían conocido jamás.\n\nEn unos pocos miles de años, las regiones agrícolas mayores y más fértiles — los valles fluviales de Mesopotamia, Egipto, el Indo y China — darían a luz las primeras ciudades, reinos y sistemas de escritura: el comienzo de lo que solemos llamar historia registrada. Pero todo ello descansaba sobre la callada, transformadora labor de los agricultores neolíticos. Cuando la Era Antigua se abre con los sumerios grabando la primera cuneiforme en arcilla, se abre sobre un escenario que las manos prehistóricas habían pasado miles de años preparando. Los agricultores vinieron primero, y los faraones y escribas fueron sus herederos.",
    ],
    ru: [
      "Более двух миллионов лет всякий человек на Земле жил охотой на животных и собиранием диких растений. Затем, начиная примерно с десяти тысяч лет назад, в горстке областей люди начали сажать посевы и разводить животных — и вся траектория человеческой истории изменилась навсегда. Этот поворот, неолитическая революция, был, пожалуй, самым судьбоносным преображением в человеческой истории, основанием, на котором воздвигнутся города, государства, письменность и всё, что мы зовём «цивилизацией».\n\nСлово «революция» может ввести в заблуждение, ибо перемена разворачивалась веками, поколение за поколением, и никто не задавался целью изобрести земледелие. Но её последствия были революционны в глубочайшем смысле. Земледелие позволило одному и тому же участку земли кормить куда больше людей, чем собирательство; оно привязало этих людей к одному месту; и оно произвело впервые запасаемые излишки, которые однажды будут содержать царей, жрецов, воинов и писцов. Всё последующее — к лучшему и к худшему — выросло из посева первых семян.",
      "Древнейшей и лучше всего задокументированной колыбелью земледелия был Плодородный полумесяц — дуга хорошо орошаемой холмистой земли, изгибающаяся от Леванта через юго-восточную Турцию до гор Загрос в Иране. Эта область располагала редким даром природы: скоплением диких растений и животных, единственно пригодных для одомашнивания. Дикая пшеница и ячмень росли густо на склонах; дикие овцы, козы, коровы и свиньи бродили рядом. Нигде более на Земле не было столько многообещающих видов, собранных в одной области.\n\nПримерно к 9500 году до н.э. народы Плодородного полумесяца начали сажать и убирать пшеницу, ячмень, чечевицу и горох, а вскоре разводить коз и овец. За поколения посевы изменились под человеческой заботой: земледельцы невольно отбирали пшеницу, чьи колосья не осыпались и не рассеивались, а держались вместе для лёгкой жатвы, а также более крупные зёрна и покорных животных. Это и есть одомашнивание — медленное взаимное переформирование, в котором люди и их посевы и стада преображали друг друга, связывая свои судьбы на все грядущие времена.",
      "Земледелие не было единственным изобретением, распространившимся из одного смекалистого места; оно открывалось независимо, снова и снова, народами, никогда не знавшими друг о друге. В Китае земледельцы вдоль Янцзы возделывали рис, а вдоль Хуанхэ выращивали просо примерно к 8000 году до н.э. В нагорьях Мексики люди одомашнили кукурузу из чахлого дикого злака под названием теосинте, а также бобы и тыкву. В Андах выращивали картофель и киноа и разводили лам; в Новой Гвинее возделывали таро и бананы; в Африке — сорго, ямс и просо.\n\nТо, что земледелие возникло по отдельности почти на каждом обитаемом материке, за несколько тысяч лет по окончании ледникового периода, — один из самых замечательных фактов во всей доистории. Он говорит нам, что этот поворот не был случайностью одного гения, а откликом нашего в высшей степени приспособляемого вида на новый тёплый и устойчивый климат голоцена. При осевшем мире и подходящих диких растениях человеческая изобретательность тянулась к земледелию везде, где могла, — и каждый из этих отдельных очагов вырастит свои особые цивилизации.",
      "Земледелие часто рассказывают как безоговорочное торжество, но правда тревожнее и интереснее. Изучение древних скелетов показывает, что первые земледельцы нередко были ниже ростом, болезненнее и изношеннее, чем охотники-собиратели до них. Рацион, суженный до одной-двух основных культур, приносил витаминную недостаточность и гнилые зубы; скучивание людей и животных плодило новые болезни вроде кори и оспы; а зависимость от немногих культур означала, что неурожай нёс голод. Иные учёные называли земледелие «худшей ошибкой в истории человеческого рода».\n\nТак почему же земледелие победило? Потому что, хотя оно сделало жизнь среднего человека тяжелее, оно позволило куда большему числу людей выжить на той же земле. Земледельческое общество несравнимо превосходило числом собирательское, и число победило: земледельцы расширялись, расчищали земли и либо поглощали, либо вытесняли своих соседей-собирателей почти по всему земному шару. Неолитическая сделка обменяла здоровье и свободу отдельного человека на чистую воспроизводственную мощь группы. Это была в некотором смысле ловушка — но ловушка, из которой не было возврата, ибо мир в миллиарды нельзя прокормить собирательством.",
      "Последствия неолитической революции излучаются сквозь всю последующую историю. Осевшие земледельческие деревни произвели впервые запасённые излишки зерна — богатство, которое можно было счесть, обложить, украсть и оспорить. Излишек пищи освободил некоторых людей от её производства, дав первых специалистов: гончаров, ткачей, жрецов, вождей и воинов. Постоянное поселение и запасённое богатство породили собственность, наследование и более резкие сословные различия, чем когда-либо знали подвижные собиратели.\n\nЗа несколько тысяч лет крупнейшие и плодороднейшие земледельческие области — речные долины Месопотамии, Египта, Инда и Китая — родят первые города, царства и системы письма: начало того, что мы обычно зовём записанной историей. Но всё это покоилось на тихом, преображающем труде неолитических земледельцев. Когда Древняя эра открывается шумерами, вдавливающими первую клинопись в глину, она открывается на сцене, которую доисторические руки тысячи лет готовили. Земледельцы пришли первыми, а фараоны и писцы были их наследниками.",
    ],
    mk: [
      "Повеќе од два милиони години, секое човечко суштество на Земјата живеело од ловење животни и собирање диви растенија. Потоа, почнувајќи од пред околу десет илјади години, во грст региони, луѓето почнале да садат посеви и да одгледуваат животни — и целата патека на човечката историја се променила засекогаш. Овој пресврт, Неолитската Револуција, беше веројатно најсудбоносната преобразба во човечката историја, темелот врз кој ќе се изградат градовите, државите, писмото и сè што го нарекуваме „цивилизација“.\n\nЗборот „револуција“ може да залаже, зашто промената се одвивала низ векови, генерација по генерација, и никој не си поставил за цел да го измисли земјоделството. Но нејзините ефекти биле револуционерни во најдлабока смисла. Земјоделството овозможило едно исто парче земја да нахрани многу повеќе луѓе од собирателството; ги врзало тие луѓе за едно место; и произвело, за првпат, складливи вишоци што еден ден ќе издржуваат кралеви, свештеници, војници и писари. Сè подоцна — за добро и за лошо — израснало од садењето на првите семиња.",
      "Најраната и најдобро документирана родна земја на земјоделството бил Плодородниот Полумесец — лак од добро наводнета ридска земја што се извива од Левант преку југоисточна Турција до планините Загрос во Иран. Овој регион уживал редок дар на природата: збир диви растенија и животни единствено погодни за припитомување. Дива пченица и јачмен растеле густо по падините; диви овци, кози, крави и свињи талкале во близина. Никаде на друго место на Земјата немало толку многу ветувачки видови збиени во еден регион.\n\nДо околу 9500 п.н.е., народите на Плодородниот Полумесец почнале да садат и жнеат пченица, јачмен, леќа и грашок, и наскоро да одгледуваат кози и овци. Низ генерации, посевите се менувале под човечка грижа: земјоделците несвесно ја селектирале пченицата чии класови не се распрснувале и растурале, туку се држеле заедно за лесна жетва, и во корист на поголеми зрна и кротки животни. Ова е припитомувањето — бавно взаемно преобликување во кое луѓето и нивните посеви и стада се преобразувале едни со други, врзувајќи ги своите судбини за сите времиња што доаѓаат.",
      "Земјоделството не било еден единствен изум што се раширил од едно досетливо место; се откривало независно, одново и одново, од народи што никогаш не се познавале. Во Кина, земјоделците долж Јангце одгледувале ориз, а долж Жолтата Река просо околу 8000 п.н.е. Во високите предели на Мексико, луѓето го припитомиле пченкарот од грмушеста дива трева наречена теосинте, заедно со грав и тиква. Во Андите одгледувале компири и киноа и одгледувале лами; во Нова Гвинеја одгледувале таро и банани; во Африка, сорго, јам и просо.\n\nФактот дека земјоделството се појавило одделно на речиси секој населен континент, за неколку илјади години по крајот на глацијацијата, е еден од најзабележителните факти во целата праисторија. Ни кажува дека пресвртот не бил случајност на еден единствен гениј, туку одговор, на нашиот врвно приспособлив вид, на новата топла и стабилна клима на холоценот. Со населен свет и вистинските диви растенија, човечката досетливост посегнала кон земјоделството секаде каде што можела — и секое од овие одделни огништа ќе ги израсне своите посебни цивилизации.",
      "Земјоделството честопати се раскажува како чист триумф, но вистината е попотресна и поинтересна. Проучувањата на древни скелети откриваат дека првите земјоделци честопати биле пониски, поболникави и поизнурени од ловците-собирачи што им претходеле. Исхрана стеснета на еден или два основни посеви носела витамински недостатоци и скапани заби; збивањето на луѓе и животни заедно раѓало нови болести како морбили и сипаници; а зависноста од неколку посеви значела дека неуспешна жетва носела глад. Некои научници го нарекле земјоделството „најлошата грешка во историјата на човечкиот род“.\n\nПа зошто победило земјоделството? Затоа што, иако го направило животот на просечниот човек потежок, овозможило многу повеќе луѓе да преживеат на истата земја. Земјоделско општество далеку ги надбројувало собирачите, и бројот победил: земјоделците се шириле, крчеле земја и или ги впивале или ги истиснувале своите соседи ловци-собирачи низ речиси целиот свет. Неолитската спогодба го заменила здравјето и слободата на поединецот за чистата репродуктивна моќ на групата. Тоа било, во извесна смисла, стапица — но стапица од која немало враќање назад, зашто свет од милијарди не може да се нахрани со собирателство.",
      "Последиците од Неолитската Револуција зрачат низ целата подоцнежна историја. Населените земјоделски села произвеле, за првпат, складирани вишоци жито — богатство што можело да се брои, оданочи, украде и за кое можело да се војува. Вишокот храна ослободил некои луѓе од производството, овозможувајќи ги првите специјалисти: грнчари, ткајачи, свештеници, поглавари и воини. Постојаното населување и складираното богатство ги родиле сопственоста, наследството и поостри поделби на ранг отколку што подвижните собирачи некогаш познавале.\n\nЗа неколку илјади години, најголемите и најплодните земјоделски региони — речните долини на Месопотамија, Египет, Инд и Кина — ќе ги родат првите градови, кралства и системи на пишување: почетокот на она што обично го нарекуваме запишана историја. Но сето тоа почивало врз тивката, преобразувачка работа на неолитските земјоделци. Кога Античката Ера се отвора со Шумерите што ја втиснуваат првата клинопис во глина, таа се отвора врз сцена што праисториските раце ја подготвувале илјадници години. Земјоделците дошле први, а фараоните и писарите биле нивни наследници.",
    ],
    de: [
      "Über zwei Millionen Jahre lang lebte jeder Mensch auf Erden von der Jagd auf Tiere und dem Sammeln wilder Pflanzen. Dann, ab etwa zehntausend Jahren, begannen Menschen in einer Handvoll Regionen, Feldfrüchte anzupflanzen und Tiere zu halten — und die gesamte Bahn der Menschheitsgeschichte änderte sich für immer. Diese Wende, die Neolithische Revolution, war wohl die folgenreichste Verwandlung der Menschheitsgeschichte, das Fundament, auf dem Städte, Staaten, Schrift und alles, was wir „Zivilisation“ nennen, errichtet würden.\n\nDas Wort „Revolution“ kann in die Irre führen, denn der Wandel entfaltete sich über Jahrhunderte, Generation um Generation, und niemand setzte sich vor, die Landwirtschaft zu erfinden. Doch ihre Wirkungen waren im tiefsten Sinne revolutionär. Die Landwirtschaft ließ ein und dasselbe Stück Land weit mehr Menschen ernähren, als das Sammeln je vermochte; sie band diese Menschen an einen Ort; und sie erzeugte erstmals die lagerfähigen Überschüsse, die eines Tages Könige, Priester, Soldaten und Schreiber tragen würden. Alles Spätere — zum Guten wie zum Schlechten — wuchs aus der Aussaat der ersten Samen.",
      "Der früheste und bestbelegte Geburtsort der Landwirtschaft war der Fruchtbare Halbmond — ein Bogen gut bewässerten Hügellandes, der sich von der Levante über die Südosttürkei bis zum Zagros-Gebirge Irans krümmt. Diese Region genoss ein seltenes Geschenk der Natur: eine Ansammlung wilder Pflanzen und Tiere, einzigartig zur Domestikation geeignet. Wilder Weizen und Gerste wuchsen dicht an den Hängen; wilde Schafe, Ziegen, Rinder und Schweine streiften umher. Nirgends sonst auf Erden waren so viele vielversprechende Arten in einer Region gedrängt.\n\nUm etwa 9500 v. Chr. hatten die Menschen des Fruchtbaren Halbmonds begonnen, Weizen, Gerste, Linsen und Erbsen zu pflanzen und zu ernten, und bald Ziegen und Schafe zu halten. Über Generationen änderten sich die Feldfrüchte unter menschlicher Pflege: Bauern wählten unwissentlich Weizen aus, dessen Ähren nicht zerbrachen und ausstreuten, sondern zusammenhielten für eine leichte Ernte, und größere Körner und fügsame Tiere. Dies ist die Domestikation — eine langsame gegenseitige Umformung, in der Menschen und ihre Feldfrüchte und Herden einander verwandelten und ihre Schicksale für alle kommende Zeit banden.",
      "Die Landwirtschaft war keine einzelne Erfindung, die sich von einem klugen Ort verbreitete; sie wurde unabhängig immer wieder entdeckt, von Völkern, die einander nie kannten. In China bauten Bauern entlang des Jangtse Reis an und entlang des Gelben Flusses Hirse um 8000 v. Chr. Im Hochland Mexikos domestizierten Menschen Mais aus einem struppigen wilden Gras namens Teosinte, dazu Bohnen und Kürbis. In den Anden zogen sie Kartoffeln und Quinoa und hielten Lamas; in Neuguinea bauten sie Taro und Bananen an; in Afrika Sorghum, Yams und Hirse.\n\nDass die Landwirtschaft auf nahezu jedem bewohnten Kontinent gesondert entstand, innerhalb weniger tausend Jahre nach dem Ende der Eiszeit, ist eine der bemerkenswertesten Tatsachen der ganzen Urgeschichte. Sie sagt uns, dass die Wende kein Zufall eines einzelnen Genies war, sondern eine Antwort unserer höchst anpassungsfähigen Art auf das neue warme und stabile Klima des Holozäns. Bei einer sesshaften Welt und den richtigen wilden Pflanzen griff der menschliche Erfindungsgeist nach der Landwirtschaft, wo immer er konnte — und jeder dieser gesonderten Herde würde eigene, verschiedene Zivilisationen wachsen lassen.",
      "Die Landwirtschaft wird oft als schlichter Triumph erzählt, doch die Wahrheit ist beunruhigender und interessanter. Studien alter Skelette zeigen, dass die ersten Bauern häufig kleiner, kränker und abgearbeiteter waren als die Jäger und Sammler vor ihnen. Eine auf ein oder zwei Grundnahrungspflanzen verengte Ernährung brachte Vitaminmangel und faulende Zähne; das Zusammendrängen von Menschen und Tieren brütete neue Krankheiten wie Masern und Pocken; und die Abhängigkeit von wenigen Feldfrüchten bedeutete, dass eine misslungene Ernte Hungersnot brachte. Manche Gelehrte haben die Landwirtschaft „den schlimmsten Fehler in der Geschichte des Menschengeschlechts“ genannt.\n\nWarum also siegte die Landwirtschaft? Weil sie, obwohl sie das Leben des Durchschnittsmenschen härter machte, weit mehr Menschen auf demselben Land überleben ließ. Eine bäuerliche Gesellschaft übertraf eine sammelnde zahlenmäßig bei weitem, und die Zahl siegte: Bauern breiteten sich aus, rodeten Land und nahmen ihre jägerischen Nachbarn entweder in sich auf oder verdrängten sie über fast den ganzen Globus. Der neolithische Handel tauschte die Gesundheit und Freiheit des Einzelnen gegen die schiere Fortpflanzungsmacht der Gruppe. Es war gewissermaßen eine Falle — doch eine Falle ohne Rückweg, denn eine Welt von Milliarden lässt sich nicht durch Sammeln ernähren.",
      "Die Folgen der Neolithischen Revolution strahlen durch die gesamte spätere Geschichte. Sesshafte Bauerndörfer erzeugten erstmals gelagerte Getreideüberschüsse — Reichtum, der gezählt, besteuert, gestohlen und umkämpft werden konnte. Der Nahrungsüberschuss befreite manche Menschen davon, ihn zu erzeugen, und erlaubte die ersten Spezialisten: Töpfer, Weber, Priester, Häuptlinge und Krieger. Dauerhafte Siedlung und gelagerter Reichtum ließen Eigentum, Erbe und schärfere Rangunterschiede entstehen, als mobile Sammler sie je gekannt hatten.\n\nInnerhalb weniger tausend Jahre würden die größten und fruchtbarsten Ackerbaugebiete — die Flusstäler Mesopotamiens, Ägyptens, des Indus und Chinas — die ersten Städte, Königreiche und Schriftsysteme hervorbringen: der Beginn dessen, was wir gewöhnlich aufgezeichnete Geschichte nennen. Doch all das ruhte auf der stillen, verwandelnden Arbeit neolithischer Bauern. Wenn die Antike sich mit Sumerern öffnet, die die erste Keilschrift in Ton drücken, öffnet sie sich auf einer Bühne, die urgeschichtliche Hände tausende Jahre vorbereitet hatten. Die Bauern kamen zuerst, und die Pharaonen und Schreiber waren ihre Erben.",
    ],
    fr: [
      "Pendant plus de deux millions d'années, tout être humain sur Terre vécut de la chasse aux animaux et de la cueillette de plantes sauvages. Puis, à partir d'environ dix mille ans, dans une poignée de régions, les gens se mirent à planter des cultures et à élever des animaux — et toute la trajectoire de l'histoire humaine changea pour toujours. Ce tournant, la révolution néolithique, fut sans doute la transformation la plus lourde de conséquences de l'histoire humaine, le fondement sur lequel seraient bâtis les villes, les États, l'écriture et tout ce que nous appelons « civilisation ».\n\nLe mot « révolution » peut induire en erreur, car le changement se déploya sur des siècles, génération après génération, et nul ne se proposa d'inventer l'agriculture. Mais ses effets furent révolutionnaires au sens le plus profond. L'agriculture permit à un même lopin de terre de nourrir bien plus de gens que la cueillette ne le put jamais ; elle attacha ces gens à un lieu ; et elle produisit, pour la première fois, les surplus stockables qui soutiendraient un jour rois, prêtres, soldats et scribes. Tout ce qui suivit — pour le meilleur et pour le pire — poussa du semis des premières graines.",
      "Le berceau le plus ancien et le mieux documenté de l'agriculture fut le Croissant fertile — un arc de collines bien arrosées se courbant du Levant à travers le sud-est de la Turquie jusqu'aux monts Zagros d'Iran. Cette région jouit d'un rare don de la nature : un ensemble de plantes et d'animaux sauvages singulièrement propices à la domestication. Blé et orge sauvages poussaient dru sur les coteaux ; moutons, chèvres, bovins et porcs sauvages rôdaient à proximité. Nulle part ailleurs sur Terre autant d'espèces prometteuses n'étaient rassemblées en une région.\n\nVers 9500 av. J.-C., les peuples du Croissant fertile avaient commencé à planter et à récolter blé, orge, lentilles et pois, et bientôt à élever chèvres et moutons. Au fil des générations, les cultures changèrent sous le soin humain : les agriculteurs sélectionnèrent sans le savoir le blé dont les épis ne se brisaient ni ne se dispersaient, mais tenaient ensemble pour une récolte aisée, ainsi que des graines plus grosses et des animaux dociles. C'est la domestication — un lent remodelage mutuel où les humains et leurs cultures et troupeaux se transformaient les uns les autres, liant leurs destins pour tous les temps à venir.",
      "L'agriculture ne fut pas une invention unique diffusée depuis un lieu ingénieux ; elle fut découverte indépendamment, encore et encore, par des peuples qui ne se connurent jamais. En Chine, les agriculteurs du Yangtsé cultivaient le riz et ceux du fleuve Jaune le millet vers 8000 av. J.-C. Dans les hautes terres du Mexique, les gens domestiquèrent le maïs à partir d'une herbe sauvage chétive appelée téosinte, avec haricots et courges. Dans les Andes, ils cultivèrent pommes de terre et quinoa et élevèrent des lamas ; en Nouvelle-Guinée, ils cultivèrent taro et bananes ; en Afrique, sorgho, ignames et millet.\n\nQue l'agriculture ait surgi séparément sur presque chaque continent habité, en quelques milliers d'années après la fin de la glaciation, est l'un des faits les plus remarquables de toute la préhistoire. Il nous dit que le tournant ne fut pas le hasard d'un seul génie, mais une réponse, de notre espèce suprêmement adaptable, au nouveau climat chaud et stable de l'Holocène. Étant donné un monde sédentaire et les bonnes plantes sauvages, l'ingéniosité humaine tendit vers l'agriculture partout où elle le put — et chacun de ces foyers séparés ferait croître ses propres civilisations distinctes.",
      "L'agriculture est souvent racontée comme un triomphe pur et simple, mais la vérité est plus troublante et plus intéressante. L'étude de squelettes anciens révèle que les premiers agriculteurs étaient souvent plus petits, plus maladifs et plus usés que les chasseurs-cueilleurs qui les précédèrent. Un régime réduit à une ou deux cultures de base apportait carences vitaminiques et dents cariées ; entasser gens et animaux couvait des maladies nouvelles comme la rougeole et la variole ; et la dépendance à quelques cultures signifiait qu'une récolte manquée apportait la famine. Certains savants ont appelé l'agriculture « la pire erreur de l'histoire de la race humaine ».\n\nAlors pourquoi l'agriculture l'emporta-t-elle ? Parce que, bien qu'elle rendît la vie de l'individu moyen plus dure, elle permit à bien plus de gens de survivre sur la même terre. Une société agricole surpassait de loin en nombre une société de cueilleurs, et le nombre l'emporta : les agriculteurs s'étendirent, défrichèrent des terres et, soit absorbèrent, soit déplacèrent leurs voisins chasseurs-cueilleurs sur presque tout le globe. Le marché néolithique échangea la santé et la liberté de l'individu contre la pure puissance reproductive du groupe. Ce fut, en un sens, un piège — mais un piège dont il n'y avait pas de retour, car un monde de milliards ne peut se nourrir de cueillette.",
      "Les conséquences de la révolution néolithique irradient à travers toute l'histoire ultérieure. Les villages agricoles sédentaires produisirent, pour la première fois, des surplus stockés de grain — une richesse qui pouvait être comptée, taxée, volée et disputée. Le surplus alimentaire libéra certaines personnes de sa production, permettant les premiers spécialistes : potiers, tisserands, prêtres, chefs et guerriers. L'établissement permanent et la richesse stockée firent naître la propriété, l'héritage et des divisions de rang plus marquées que les cueilleurs mobiles n'en avaient jamais connu.\n\nEn quelques milliers d'années, les régions agricoles les plus vastes et les plus fertiles — les vallées fluviales de la Mésopotamie, de l'Égypte, de l'Indus et de la Chine — donneraient naissance aux premières villes, royaumes et systèmes d'écriture : le commencement de ce que nous appelons d'ordinaire l'histoire consignée. Mais tout cela reposait sur le travail silencieux et transformateur des agriculteurs néolithiques. Quand l'Ère antique s'ouvre avec les Sumériens gravant la première écriture cunéiforme dans l'argile, elle s'ouvre sur une scène que des mains préhistoriques avaient passé des milliers d'années à préparer. Les agriculteurs vinrent d'abord, et les pharaons et les scribes furent leurs héritiers.",
    ],
  },
  'prehistoric-09': {
    es: [
      "En una cima azotada por el viento del sudeste de Turquía se alza un descubrimiento que trastocó todo lo que los estudiosos creían saber sobre el nacimiento de la civilización. Göbekli Tepe, iniciado hacia el 9500 a.C., es un complejo de macizos círculos de piedra — anillos de pilares de piedra caliza en forma de T de hasta cinco metros de alto y de muchas toneladas, tallados en relieve con zorros, serpientes, escorpiones, buitres y jabalíes. Es la arquitectura monumental más antigua jamás hallada, más antigua que Stonehenge en seis mil años, más antigua que las pirámides en siete.\n\nLo asombroso es que lo construyeron cazadores-recolectores, antes de la agricultura, antes de la cerámica, antes de la rueda, el metal o la escritura. La vieja historia sostenía que la gente primero se asentó para cultivar, se enriqueció con el excedente y solo entonces pudo permitirse templos. Göbekli Tepe sugiere que lo inverso puede ser cierto: que el deseo de reunirse en gran número para el ritual compartido — de levantar juntos algo sagrado — pudo haber ayudado a empujar a la gente hacia la vida asentada y la agricultura en primer lugar. El templo, al parecer, pudo venir antes que el pueblo.",
      "Unos pocos miles de años después, en las llanuras del centro de Turquía, surgió una de las primeras protociudades del mundo: Çatalhöyük, ocupada desde hacia el 7500 a.C. y hogar, en su apogeo, de quizá cinco a ocho mil personas. Era distinta de cualquier ciudad posterior. No había calles ni puertas a nivel del suelo. Las casas de adobe estaban apretadas pared con pared en un panal, y la gente entraba por un agujero en el techo, caminando por los tejados del pueblo y bajando por una escalera a sus hogares.\n\nPor dentro, las casas de Çatalhöyük eran asombrosas. Las paredes estaban enlucidas y pintadas con escenas de caza, patrones geométricos e imágenes de buitres y leopardos; algunas contenían los cráneos moldeados de uros. Los muertos eran enterrados bajo los mismos suelos sobre los que dormían los vivos, manteniendo a los ancestros literalmente bajo los pies. Sorprendentemente, las casas son todas de tamaño muy parecido, sin grandes palacios ni un barrio rico evidente — una comunidad grande y densa que parece haber vivido, durante mil años, sin reyes. Çatalhöyük nos muestra un momento suspendido entre el viejo mundo igualitario de los recolectores y el mundo jerárquico de las ciudades por venir.",
      "Las aldeas asentadas del Neolítico tardío se convirtieron en talleres de invención. La cerámica — el moldeado y cocido de arcilla en vasijas duraderas e impermeables — se difundió ampliamente tras hacia el 7000 a.C., transformando cómo la gente cocinaba, almacenaba grano y transportaba agua; un cacharro cocido es una de las pistas más preciosas de la arqueología, pues sus estilos cambian con la moda y marcan las culturas a través del tiempo y el espacio. El tejido convirtió el lino y la lana en tela, dando a la humanidad una segunda piel que podía diseñar a voluntad.\n\nLo más trascendental de todo, el Neolítico tardío vio el primer trabajo del metal. La gente empezó martillando cobre natural, luego aprendió a fundirlo del mineral con fuego, y por fin, hacia el 3300 a.C., a alear cobre con estaño para hacer bronce — un metal lo bastante duro para herramientas y armas serias. La Edad de Piedra tocaba a su fin. Cada uno de estos oficios — cerámica, textiles, metalurgia — exigía especialistas, y los especialistas exigían el excedente de alimento que solo las aldeas agrícolas podían proveer. El mundo asentado se estaba volviendo un mundo de destrezas, oficios y cosas.",
      "A medida que las sociedades agrícolas se enriquecían y organizaban más, vertían su trabajo excedente en monumentos — vastas construcciones de tierra y piedra que exigían el esfuerzo coordinado de comunidades enteras a lo largo de generaciones. Por toda la Europa neolítica se alzaron miles de megalitos (\"grandes piedras\"): piedras erguidas, hileras de piedras y tumbas de cámara de colosales rocas. El más famoso es Stonehenge, en la llanura de Salisbury, construido y reconstruido a lo largo de siglos desde hacia el 3000 a.C., sus grandes verticales de sarsen coronadas con dinteles y alineadas con la salida y la puesta del sol en los solsticios.\n\nEstos monumentos fueron hazañas de organización asombrosa para pueblos sin escritura, ruedas ni animales de tiro dignos de mención. Algunas de las piedras azules de Stonehenge fueron arrastradas unos doscientos kilómetros desde las montañas de Gales. Mover y erguir piedras de muchas toneladas, alinearlas con precisión con los cielos, exigía no solo músculo sino planificación, matemáticas, astronomía y un propósito compartido lo bastante poderoso para atar a un pueblo disperso a una tarea común durante generaciones enteras. Los megalitos son la firma monumental de un nuevo tipo de sociedad — asentada, cooperativa y alzándose hacia el cielo.",
      "Hacia el 3000 a.C., la profunda edad sin palabras de la prehistoria tocaba a su fin. En los grandes valles fluviales — el Tigris y el Éufrates de Mesopotamia, el Nilo de Egipto, pronto el Indo y el río Amarillo — la aldea neolítica se hinchaba en algo nuevo: la ciudad, hogar de decenas de miles, gobernada por reyes y sacerdotes, defendida por murallas y alimentada por campos irrigados y excedentes gravados. Para gestionar todo esto, la gente dio el paso final y transformador de inventar la escritura — y con las primeras marcas grabadas en arcilla, la prehistoria terminó y la historia registrada comenzó.\n\nPero nunca deberíamos confundir ese umbral con el verdadero comienzo de la historia humana. Todo lo que hizo posible la historia — el cuerpo erguido, el dominio del fuego, la mente simbólica, la colonización de la Tierra, la domesticación de plantas y animales, las primeras aldeas y monumentos — se había logrado en las inmensas y silenciosas edades anteriores. La prehistoria no es el prólogo de la historia humana; es la abrumadora mayoría de ella. Cuando el escriba sumerio presionó su estilo en la arcilla húmeda, escribió la primera frase de un libro cuyos capítulos primeros, más largos y más decisivos ya habían sido vividos, sin escribir, por cien mil generaciones de sus ancestros.",
    ],
    ru: [
      "На обдуваемой ветром вершине на юго-востоке Турции стоит открытие, опрокинувшее всё, что учёные думали знать о рождении цивилизации. Гёбекли-Тепе, начатый около 9500 года до н.э., — комплекс массивных каменных кругов, колец Т-образных известняковых столбов до пяти метров высотой и во много тонн весом, покрытых рельефами лис, змей, скорпионов, грифов и кабанов. Это древнейшая монументальная архитектура, когда-либо найденная, старше Стоунхенджа на шесть тысяч лет, старше пирамид — на семь.\n\nПотрясение в том, что его возвели охотники-собиратели — до земледелия, до гончарства, до колеса, металла или письменности. Прежняя повесть гласила, что люди сперва осели, чтобы возделывать землю, разбогатели на излишках и лишь тогда смогли позволить себе храмы. Гёбекли-Тепе намекает, что верно может быть обратное: что желание собираться во множестве ради общего обряда — возвести вместе нечто священное — могло само подтолкнуть людей к осёдлой жизни и земледелию в первую очередь. Храм, похоже, мог явиться прежде города.",
      "Несколько тысяч лет спустя на равнинах центральной Турции возник один из первых протогородов мира: Чатал-Хёюк, заселённый примерно с 7500 года до н.э. и вмещавший на своём пике, быть может, от пяти до восьми тысяч человек. Он был не похож ни на один город с тех пор. Не было ни улиц, ни дверей на уровне земли. Глинобитные дома были стиснуты стена к стене сотами, и люди входили через отверстие в крыше, идя по кровлям города и спускаясь по лестнице в свои жилища.\n\nВнутри дома Чатал-Хёюка были поразительны. Стены были оштукатурены и расписаны сценами охоты, геометрическими узорами и образами грифов и леопардов; иные хранили вылепленные черепа туров. Мёртвых хоронили под теми самыми полами, на которых спали живые, держа предков буквально под ногами. Что примечательно, дома все примерно одного размера, без величавых дворцов и явного богатого квартала, — большая, плотная община, что, кажется, жила тысячу лет без царей. Чатал-Хёюк являет нам миг, повисший между старым равноправным миром собирателей и иерархическим миром грядущих городов.",
      "Осёдлые деревни позднего неолита стали мастерскими изобретения. Гончарство — лепка и обжиг глины в прочные, водонепроницаемые сосуды — широко распространилось после примерно 7000 года до н.э., преобразив то, как люди готовили, хранили зерно и носили воду; обожжённый горшок — одна из драгоценнейших улик археологии, ибо его стили меняются с модой и отмечают культуры сквозь время и пространство. Ткачество превращало лён и шерсть в ткань, давая человечеству вторую кожу, которую оно могло замышлять по своей воле.\n\nСудьбоноснее всего — поздний неолит увидел первую обработку металла. Люди начали с ковки самородной меди, затем научились выплавлять её из руды огнём и наконец, около 3300 года до н.э., сплавлять медь с оловом ради бронзы — металла, достаточно твёрдого для серьёзных орудий и оружия. Каменный век близился к концу. Каждое из этих ремёсел — гончарство, ткачество, металлургия — требовало специалистов, а специалисты требовали пищевого излишка, который могли дать лишь земледельческие деревни. Осёдлый мир становился миром умений, ремёсел и вещей.",
      "По мере того как земледельческие общества богатели и лучше организовывались, они вливали свой избыточный труд в монументы — огромные сооружения из земли и камня, требовавшие согласованного усилия целых общин на протяжении поколений. По всей неолитической Европе воздвиглись тысячи мегалитов («великих камней»): стоячие камни, каменные ряды и камерные гробницы из колоссальных валунов. Знаменитейший — Стоунхендж на Солсберийской равнине, строившийся и перестраивавшийся веками с примерно 3000 года до н.э., его великие сарсеновые опоры, увенчанные перемычками и выровненные на восход и закат солнца в солнцестояния.\n\nЭти монументы были подвигами поразительной организации для народов без письменности, колёс и сколько-нибудь значимых тягловых животных. Иные голубые камни Стоунхенджа тащили около двухсот километров из гор Уэльса. Двигать и воздвигать камни во много тонн, точно выравнивать их с небесами требовало не только мышц, но планирования, математики, астрономии и общей цели, достаточно могучей, чтобы привязать рассеянный народ к совместной задаче на целые жизни. Мегалиты — монументальный признак нового рода общества: осёдлого, сотрудничающего и тянущегося к небу.",
      "К примерно 3000 году до н.э. глубокая, бессловесная эпоха доистории близилась к концу. В великих речных долинах — Тигра и Евфрата Месопотамии, Нила Египта, вскоре Инда и Хуанхэ — неолитская деревня раздувалась во нечто новое: город, дом десятков тысяч, управляемый царями и жрецами, защищённый стенами и питаемый орошёнными полями и обложенными излишками. Чтобы управлять всем этим, люди сделали последний, преображающий шаг — изобрели письменность, и с первыми знаками, вдавленными в глину, доистория кончилась и записанная история началась.\n\nНо мы никогда не должны принимать этот порог за истинное начало человеческой истории. Всё, что сделало историю возможной — прямое тело, покорение огня, символический ум, заселение Земли, одомашнивание растений и животных, первые деревни и монументы, — было достигнуто в необъятные, безмолвные эпохи прежде. Доистория — не пролог человеческой истории; она — её подавляющее большинство. Когда шумерский писец вдавил свой стиль в мокрую глину, он написал первую фразу книги, чьи первые, длиннейшие и решающие главы уже были прожиты, неписаными, ста тысячами поколений его предков.",
    ],
    mk: [
      "На ветровит врв во југоисточна Турција стои откритие што го преврте сè што научниците мислеле дека знаат за раѓањето на цивилизацијата. Гебекли Тепе, започнат околу 9500 п.н.е., е комплекс од масивни камени кругови — прстени од Т-обликувани варовнички столбови високи до пет метри и тешки по многу тони, изрежани во релјеф со лисици, змии, скорпии, мршојадци и диви свињи. Тоа е најстарата монументална архитектура некогаш пронајдена, постара од Стоунхенџ за шест илјади години, постара од пирамидите за седум.\n\nШокот е што го изградиле ловци-собирачи, пред земјоделството, пред грнчарството, пред тркалото, металот или писмото. Старата приказна тврдела дека луѓето прво се населиле за да обработуваат земја, се збогатиле од вишокот и дури тогаш можеле да си дозволат храмови. Гебекли Тепе наведува дека обратното може да е вистина: дека желбата да се собираат во голем број за споделен ритуал — да кренат заедно нешто свето — можеби помогнала да ги турне луѓето кон населен живот и земјоделство на прво место. Храмот, се чини, можеби дошол пред градот.",
      "Неколку илјади години подоцна, на рамнините на централна Турција, се појавил еден од првите протоградови во светот: Чаталхујук, населен од околу 7500 п.н.е. и дом, на својот врв, на можеби пет до осум илјади луѓе. Бил различен од кој било град оттогаш. Немало улици ниту врати на ниво на земјата. Куќите од кал биле збиени ѕид до ѕид во саќе, и луѓето влегувале преку дупка на кровот, одејќи по крововите на градот и качувајќи се по скала во своите домови.\n\nОдвнатре, куќите на Чаталхујук биле зачудувачки. Ѕидовите биле измалтерисани и насликани со ловечки сцени, геометриски шари и слики на мршојадци и леопарди; некои содржеле обликувани черепи на тури. Мртвите биле погребувани под самите подови на кои спиеле живите, држејќи ги предците буквално под нозе. Впечатливо, куќите се сите со многу слична големина, без големи палати ниту очигледен богат кварт — голема, густа заедница што се чини живеела, илјада години, без кралеви. Чаталхујук ни покажува момент зависнат меѓу стариот рамноправен свет на собирачите и хиерархискиот свет на градовите што доаѓаат.",
      "Населените села од доцниот неолит станале работилници на изумот. Грнчарството — обликувањето и печењето на глината во трајни, водоотпорни садови — се раширило нашироко по околу 7000 п.н.е., преобразувајќи го начинот на кој луѓето готвеле, складирале жито и носеле вода; печен сад е една од најдрагоцените траги на археологијата, зашто неговите стилови се менуваат со модата и ги обележуваат културите низ времето и просторот. Ткаењето го претворало ленот и волната во ткаенина, давајќи ѝ на човештвото втора кожа што можело да ја обликува по волја.\n\nНајсудбоносно од сè, доцниот неолит видел прва обработка на метал. Луѓето почнале со чукање природен бакар, потоа научиле да го топат од руда со оган, и најпосле, околу 3300 п.н.е., да го легираат бакарот со калај за да направат бронза — метал доволно тврд за сериозни алатки и оружја. Каменото Доба се приближувало кон крајот. Секој од овие занаети — грнчарство, текстил, металургија — барал специјалисти, а специјалистите барале вишок храна што само земјоделските села можеле да го обезбедат. Населениот свет станувал свет на вештини, занаети и предмети.",
      "Како што земјоделските општества станувале побогати и поорганизирани, тие го влевале својот вишок труд во споменици — огромни градби од земја и камен што барале координиран напор на цели заедници низ генерации. Низ неолитска Европа се кренале илјадници мегалити („големи камења“): исправени камења, редови камења и коморни гробници од колосални карпи. Најпознат е Стоунхенџ на Рамнината Солсбери, граден и преградуван низ векови од околу 3000 п.н.е., неговите големи сарсенски столбови крунисани со надвратници и порамнети со изгревот и зајдисонцето на сонцето при солстициите.\n\nОвие споменици биле подвизи на зачудувачка организација за народи без писмо, тркала или впрежни животни вредни за спомнување. Некои од сините камења на Стоунхенџ биле влечени околу двесте километри од планините на Велс. Да се движат и креваат камења од многу тони, да се порамнат прецизно со небесата, барало не само мускул туку планирање, математика, астрономија и заедничка цел доволно моќна да го врзе распрснатиот народ за заедничка задача за цели животи. Мегалитите се монументалниот потпис на нов вид општество — населено, соработничко и посегнувачко кон небото.",
      "До околу 3000 п.н.е., длабокото, бесзборно доба на праисторијата се приближувало кон својот крај. Во големите речни долини — Тигар и Еуфрат на Месопотамија, Нилот на Египет, наскоро Инд и Жолтата Река — неолитското село набабрувало во нешто ново: градот, дом на десетици илјади, владеан од кралеви и свештеници, бранет со ѕидини и хранет со наводнувани полиња и оданочени вишоци. За да управуваат со сето ова, луѓето го направиле последниот, преобразувачки чекор — го измислиле писмото — и со првите ознаки втиснати во глина, праисторијата завршила и запишаната историја започнала.\n\nНо никогаш не смееме да го помешаме тој праг со вистинскиот почеток на човечката приказна. Сè што ја направило историјата можна — исправеното тело, совладувањето на огнот, симболичкиот ум, населувањето на Земјата, припитомувањето на растенијата и животните, првите села и споменици — било постигнато во огромните, тивки времиња претходно. Праисторијата не е предговор на човечката историја; таа е нејзиното огромно мнозинство. Кога шумерскиот писар го притиснал својот стилус во влажната глина, тој ја напишал првата реченица на книга чии први, најдолги и најодлучувачки поглавја веќе биле проживеани, ненапишани, од сто илјади генерации на неговите предци.",
    ],
    de: [
      "Auf einem windgepeitschten Hügel der Südosttürkei steht eine Entdeckung, die alles umstürzte, was Gelehrte über die Geburt der Zivilisation zu wissen glaubten. Göbekli Tepe, um 9500 v. Chr. begonnen, ist ein Komplex massiver Steinkreise — Ringe T-förmiger Kalksteinpfeiler von bis zu fünf Metern Höhe und vielen Tonnen Gewicht, in Relief mit Füchsen, Schlangen, Skorpionen, Geiern und Wildschweinen geschnitzt. Es ist die älteste je gefundene monumentale Architektur, älter als Stonehenge um sechstausend Jahre, älter als die Pyramiden um siebentausend.\n\nDer Schock ist, dass es von Jägern und Sammlern errichtet wurde, vor der Landwirtschaft, vor der Töpferei, vor Rad, Metall oder Schrift. Die alte Geschichte besagte, die Menschen seien zuerst sesshaft geworden, um zu ackern, hätten sich am Überschuss bereichert und sich erst dann Tempel leisten können. Göbekli Tepe deutet an, dass das Umgekehrte wahr sein könnte: dass der Wunsch, sich in großer Zahl zum gemeinsamen Ritual zu versammeln — zusammen etwas Heiliges zu errichten — die Menschen überhaupt erst zur Sesshaftigkeit und Landwirtschaft getrieben haben mag. Der Tempel, so scheint es, könnte vor der Stadt gekommen sein.",
      "Ein paar tausend Jahre später erhob sich auf den Ebenen Zentralanatoliens eine der ersten Protostädte der Welt: Çatalhöyük, seit etwa 7500 v. Chr. bewohnt und auf seinem Höhepunkt Heimat von vielleicht fünf- bis achttausend Menschen. Es war anders als jede spätere Stadt. Es gab keine Straßen und keine Türen auf Bodenhöhe. Die Lehmziegelhäuser waren Wand an Wand zu einer Wabe gedrängt, und die Menschen betraten sie durch ein Loch im Dach, gingen über die Dächer der Stadt und stiegen eine Leiter in ihre Häuser hinab.\n\nInnen waren die Häuser Çatalhöyüks erstaunlich. Wände waren verputzt und mit Jagdszenen, geometrischen Mustern und Bildern von Geiern und Leoparden bemalt; manche bargen die geformten Schädel von Auerochsen. Die Toten wurden unter denselben Böden bestattet, auf denen die Lebenden schliefen, und hielten die Ahnen buchstäblich unter den Füßen. Bemerkenswerterweise sind die Häuser alle etwa gleich groß, ohne prächtige Paläste oder ein offensichtliches Reichenviertel — eine große, dichte Gemeinschaft, die tausend Jahre lang ohne Könige gelebt zu haben scheint. Çatalhöyük zeigt uns einen Augenblick, der zwischen der alten egalitären Welt der Sammler und der hierarchischen Welt der bald kommenden Städte schwebt.",
      "Die sesshaften Dörfer des späten Neolithikums wurden zu Werkstätten der Erfindung. Die Töpferei — das Formen und Brennen von Ton zu haltbaren, wasserdichten Gefäßen — verbreitete sich nach etwa 7000 v. Chr. weithin und verwandelte, wie Menschen kochten, Getreide lagerten und Wasser trugen; ein gebrannter Topf ist einer der kostbarsten Hinweise der Archäologie, denn seine Stile wechseln mit der Mode und markieren Kulturen durch Zeit und Raum. Das Weben verwandelte Flachs und Wolle in Tuch und gab der Menschheit eine zweite Haut, die sie nach Belieben gestalten konnte.\n\nAm folgenreichsten von allem sah das späte Neolithikum die erste Metallverarbeitung. Menschen begannen, natürlich vorkommendes Kupfer zu hämmern, lernten dann, es mit Feuer aus Erz zu schmelzen, und schließlich, um 3300 v. Chr., Kupfer mit Zinn zu Bronze zu legieren — ein Metall, hart genug für ernsthafte Werkzeuge und Waffen. Die Steinzeit ging zu Ende. Jedes dieser Handwerke — Töpferei, Textilien, Metallurgie — verlangte Spezialisten, und Spezialisten verlangten den Nahrungsüberschuss, den nur Bauerndörfer liefern konnten. Die sesshafte Welt wurde zu einer Welt der Fertigkeiten, Gewerbe und Dinge.",
      "Als Ackerbaugesellschaften reicher und geordneter wurden, gossen sie ihre überschüssige Arbeit in Monumente — riesige Bauten aus Erde und Stein, die die abgestimmte Anstrengung ganzer Gemeinschaften über Generationen verlangten. Über das neolithische Europa erhoben sich tausende Megalithen („große Steine“): Menhire, Steinreihen und Kammergräber aus kolossalen Felsblöcken. Der berühmteste ist Stonehenge in der Ebene von Salisbury, über Jahrhunderte ab etwa 3000 v. Chr. errichtet und umgebaut, seine großen Sarsen-Pfeiler mit Deckbalken gekrönt und auf Sonnenaufgang und -untergang zu den Sonnenwenden ausgerichtet.\n\nDiese Monumente waren Leistungen erstaunlicher Organisation für Völker ohne Schrift, Räder oder nennenswerte Zugtiere. Manche von Stonehenges Blausteinen wurden etwa zweihundert Kilometer aus den Bergen von Wales geschleppt. Steine von vielen Tonnen zu bewegen und aufzurichten, sie genau an den Himmeln auszurichten, verlangte nicht nur Muskeln, sondern Planung, Mathematik, Astronomie und ein gemeinsames Ziel, mächtig genug, um ein verstreutes Volk über Menschenleben hinweg an eine gemeinsame Aufgabe zu binden. Die Megalithen sind die monumentale Signatur einer neuen Art von Gesellschaft — sesshaft, kooperativ und zum Himmel greifend.",
      "Um etwa 3000 v. Chr. ging das tiefe, wortlose Zeitalter der Urgeschichte seinem Ende zu. In den großen Flusstälern — dem Tigris und Euphrat Mesopotamiens, dem Nil Ägyptens, bald dem Indus und dem Gelben Fluss — schwoll das neolithische Dorf zu etwas Neuem an: der Stadt, Heimat zehntausender, von Königen und Priestern beherrscht, von Mauern verteidigt und von bewässerten Feldern und besteuerten Überschüssen genährt. Um all dies zu verwalten, taten die Menschen den letzten, verwandelnden Schritt, die Schrift zu erfinden — und mit den ersten in Ton gedrückten Zeichen endete die Urgeschichte und die aufgezeichnete Geschichte begann.\n\nDoch wir sollten diese Schwelle nie mit dem wahren Anfang der Menschheitsgeschichte verwechseln. Alles, was Geschichte möglich machte — der aufrechte Körper, die Beherrschung des Feuers, der symbolische Geist, die Besiedlung der Erde, die Domestikation von Pflanzen und Tieren, die ersten Dörfer und Monumente — war in den unermesslichen, stillen Zeitaltern zuvor erreicht worden. Die Urgeschichte ist nicht der Prolog der Menschheitsgeschichte; sie ist ihr überwältigender Großteil. Als der sumerische Schreiber seinen Griffel in den nassen Ton drückte, schrieb er den ersten Satz eines Buches, dessen erste, längste und entscheidendste Kapitel bereits gelebt worden waren, ungeschrieben, von hunderttausend Generationen seiner Vorfahren.",
    ],
    fr: [
      "Sur une colline balayée par le vent du sud-est de la Turquie se dresse une découverte qui renversa tout ce que les savants croyaient savoir sur la naissance de la civilisation. Göbekli Tepe, commencé vers 9500 av. J.-C., est un complexe de massifs cercles de pierre — des anneaux de piliers de calcaire en forme de T, hauts de jusqu'à cinq mètres et pesant plusieurs tonnes, sculptés en relief de renards, de serpents, de scorpions, de vautours et de sangliers. C'est la plus ancienne architecture monumentale jamais trouvée, plus ancienne que Stonehenge de six mille ans, plus ancienne que les pyramides de sept mille.\n\nLe choc est qu'elle fut bâtie par des chasseurs-cueilleurs, avant l'agriculture, avant la poterie, avant la roue, le métal ou l'écriture. La vieille histoire soutenait que les gens s'étaient d'abord fixés pour cultiver, s'étaient enrichis du surplus et n'avaient pu qu'alors s'offrir des temples. Göbekli Tepe suggère que l'inverse pourrait être vrai : que le désir de se rassembler en grand nombre pour le rituel partagé — d'ériger ensemble quelque chose de sacré — a pu contribuer à pousser les gens vers la vie sédentaire et l'agriculture en premier lieu. Le temple, semble-t-il, a pu venir avant la ville.",
      "Quelques milliers d'années plus tard, sur les plaines de la Turquie centrale, surgit l'une des premières proto-villes du monde : Çatalhöyük, occupée depuis environ 7500 av. J.-C. et abritant, à son apogée, peut-être cinq à huit mille personnes. Elle était différente de toute ville ultérieure. Il n'y avait ni rues ni portes au niveau du sol. Les maisons de brique crue étaient serrées mur contre mur en un nid d'abeilles, et les gens entraient par un trou dans le toit, marchant sur les toits de la ville et descendant une échelle jusqu'à leur logis.\n\nÀ l'intérieur, les maisons de Çatalhöyük étaient stupéfiantes. Les murs étaient enduits et peints de scènes de chasse, de motifs géométriques et d'images de vautours et de léopards ; certaines abritaient les crânes moulés d'aurochs. Les morts étaient enterrés sous les sols mêmes sur lesquels dormaient les vivants, gardant les ancêtres littéralement sous les pieds. Fait remarquable, les maisons sont toutes de taille très semblable, sans grands palais ni quartier riche manifeste — une communauté vaste et dense qui semble avoir vécu, pendant mille ans, sans rois. Çatalhöyük nous montre un moment suspendu entre l'ancien monde égalitaire des cueilleurs et le monde hiérarchique des villes à venir.",
      "Les villages sédentaires du Néolithique tardif devinrent des ateliers d'invention. La poterie — le façonnage et la cuisson de l'argile en récipients durables et étanches — se répandit largement après environ 7000 av. J.-C., transformant la façon dont les gens cuisinaient, stockaient le grain et transportaient l'eau ; un pot cuit est l'un des indices les plus précieux de l'archéologie, car ses styles changent avec la mode et marquent les cultures à travers le temps et l'espace. Le tissage transforma le lin et la laine en étoffe, donnant à l'humanité une seconde peau qu'elle pouvait concevoir à volonté.\n\nPlus décisif de tout, le Néolithique tardif vit le premier travail du métal. Les gens commencèrent en martelant le cuivre natif, puis apprirent à le fondre du minerai par le feu, et enfin, vers 3300 av. J.-C., à allier le cuivre à l'étain pour faire le bronze — un métal assez dur pour des outils et des armes sérieux. L'âge de pierre touchait à sa fin. Chacun de ces métiers — poterie, textiles, métallurgie — exigeait des spécialistes, et les spécialistes exigeaient le surplus alimentaire que seuls les villages agricoles pouvaient fournir. Le monde sédentaire devenait un monde de savoir-faire, de métiers et d'objets.",
      "À mesure que les sociétés agricoles s'enrichissaient et s'organisaient davantage, elles versaient leur travail excédentaire dans des monuments — de vastes constructions de terre et de pierre qui exigeaient l'effort coordonné de communautés entières sur des générations. À travers l'Europe néolithique s'élevèrent des milliers de mégalithes (« grandes pierres ») : pierres dressées, alignements de pierres et tombes à chambre de blocs colossaux. Le plus célèbre est Stonehenge, dans la plaine de Salisbury, bâti et rebâti au fil des siècles à partir d'environ 3000 av. J.-C., ses grands montants de sarsen coiffés de linteaux et alignés sur le lever et le coucher du soleil aux solstices.\n\nCes monuments furent des exploits d'organisation stupéfiante pour des peuples sans écriture, sans roues ni animaux de trait dignes de mention. Certaines des pierres bleues de Stonehenge furent traînées sur quelque deux cents kilomètres depuis les montagnes du pays de Galles. Déplacer et dresser des pierres de plusieurs tonnes, les aligner avec précision sur les cieux, exigeait non seulement du muscle mais de la planification, des mathématiques, de l'astronomie et un dessein commun assez puissant pour lier un peuple dispersé à une tâche commune durant des vies entières. Les mégalithes sont la signature monumentale d'un nouveau type de société — sédentaire, coopérative et tendue vers le ciel.",
      "Vers 3000 av. J.-C., l'âge profond et sans mots de la préhistoire touchait à sa fin. Dans les grandes vallées fluviales — le Tigre et l'Euphrate de Mésopotamie, le Nil d'Égypte, bientôt l'Indus et le fleuve Jaune — le village néolithique enflait en quelque chose de nouveau : la ville, foyer de dizaines de milliers de gens, gouvernée par des rois et des prêtres, défendue par des murs et nourrie par des champs irrigués et des surplus taxés. Pour gérer tout cela, les gens franchirent le pas ultime et transformateur d'inventer l'écriture — et avec les premières marques imprimées dans l'argile, la préhistoire prit fin et l'histoire consignée commença.\n\nMais nous ne devrions jamais confondre ce seuil avec le véritable commencement de l'histoire humaine. Tout ce qui rendit l'histoire possible — le corps debout, la maîtrise du feu, l'esprit symbolique, le peuplement de la Terre, la domestication des plantes et des animaux, les premiers villages et monuments — avait été accompli dans les âges immenses et silencieux d'avant. La préhistoire n'est pas le prologue de l'histoire humaine ; elle en est l'écrasante majorité. Quand le scribe sumérien pressa son stylet dans l'argile humide, il écrivit la première phrase d'un livre dont les premiers, les plus longs et les plus décisifs chapitres avaient déjà été vécus, non écrits, par cent mille générations de ses ancêtres.",
    ],
  },
};
